# region src/Private/Common.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

$script:WinToolPublishedUrl = "https://raw.githubusercontent.com/Hinrikao/WinTool/main/wintool.ps1"
$script:WinToolProfileBegin = "# >>> WinTool terminal setup >>>"
$script:WinToolProfileEnd = "# <<< WinTool terminal setup <<<"

if ([string]::IsNullOrWhiteSpace($script:WinToolVersion)) {
    $script:WinToolVersion = "1.0.0"
}

function Get-WinToolNote {
    param(
        $Object,
        [Parameter(Mandatory = $true)][string]$Name,
        $Default = $null
    )
    if ($null -eq $Object) {
        return $Default
    }
    $property = $Object.PSObject.Properties[$Name]
    if ($null -eq $property -or $null -eq $property.Value) {
        return $Default
    }
    return $property.Value
}

function Test-WinToolWindows {
    return ($env:OS -eq "Windows_NT")
}

function Test-WinToolTextMatch {
    param(
        [string]$Haystack,
        [string]$Query
    )
    if ([string]::IsNullOrWhiteSpace($Query)) {
        return $true
    }
    if ([string]::IsNullOrWhiteSpace($Haystack)) {
        return $false
    }
    return ($Haystack.IndexOf($Query.Trim(), [System.StringComparison]::OrdinalIgnoreCase) -ge 0)
}

function Get-WinToolPayloadText {
    param(
        [Parameter(Mandatory = $true)][string]$Name
    )
    $embedded = $script:WinToolEmbedded
    if ($null -ne $embedded -and $embedded.ContainsKey($Name)) {
        $clean = ([string]$embedded[$Name]) -replace '\s', ''
        $bytes = [Convert]::FromBase64String($clean)
        return [System.Text.Encoding]::UTF8.GetString($bytes)
    }

    if ([string]::IsNullOrWhiteSpace($script:WinToolRoot)) {
        throw "WinTool payload '$Name' is not embedded and no source folder is set."
    }

    $relative = @{
        Apps = "data/apps.json"
        Tweaks = "data/tweaks.json"
        Terminal = "data/terminal.json"
        Fonts = "data/fonts.json"
        OmpThemes = "data/omp-themes.json"
        Updates = "data/updates.json"
        Fixes = "data/fixes.json"
        Features = "data/features.json"
        System = "data/system.json"
        Xaml = "assets/MainWindow.xaml"
        Wsl = "data/wsl-setup.sh"
    }
    if (-not $relative.ContainsKey($Name)) {
        throw "Unknown WinTool payload '$Name'."
    }

    $path = Join-Path $script:WinToolRoot $relative[$Name]
    return [System.IO.File]::ReadAllText($path)
}

function Get-WinToolLogPath {
    if (-not [string]::IsNullOrWhiteSpace($script:WinToolLogFile)) {
        return $script:WinToolLogFile
    }
    if ([string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
        return $null
    }
    $directory = Join-Path $env:LOCALAPPDATA "WinTool/logs"
    if (-not (Test-Path -LiteralPath $directory)) {
        New-Item -ItemType Directory -Path $directory -Force | Out-Null
    }
    $name = "wintool-" + (Get-Date -Format "yyyyMMdd-HHmmss") + ".log"
    $script:WinToolLogFile = Join-Path $directory $name
    return $script:WinToolLogFile
}

function Add-WinToolLogLine {
    param(
        [Parameter(Mandatory = $true)][string]$Line
    )
    $path = Get-WinToolLogPath
    if (-not [string]::IsNullOrWhiteSpace($path)) {
        try {
            Add-Content -LiteralPath $path -Value $Line -Encoding UTF8
        }
        catch {
            $null = $_.Exception.Message
        }
    }

    if ($null -eq $script:WinToolLogBox) {
        Write-Host $Line
        return
    }

    $box = $script:WinToolLogBox
    $write = {
        $box.AppendText($Line + [Environment]::NewLine)
        $box.ScrollToEnd()
    }.GetNewClosure()

    if ($box.Dispatcher.CheckAccess()) {
        & $write
    }
    else {
        $box.Dispatcher.BeginInvoke([System.Action]$write) | Out-Null
    }
}

function Write-WinToolLog {
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Message,
        [ValidateSet("info", "ok", "warn", "error")]
        [string]$Level = "info",
        # Also append to %TEMP%\WinTool\wintool.log, the file people send in bug reports.
        [switch]$Diagnostic
    )
    if ([string]::IsNullOrWhiteSpace($Message)) {
        return
    }
    $prefix = "INFO"
    if ($Level -eq "ok") { $prefix = " OK " }
    elseif ($Level -eq "warn") { $prefix = "WARN" }
    elseif ($Level -eq "error") { $prefix = "FAIL" }
    $stamp = Get-Date -Format "HH:mm:ss"
    $line = "{0}  {1}  {2}" -f $stamp, $prefix, $Message
    Add-WinToolLogLine -Line $line
    if ($Diagnostic) {
        Write-WinToolDiagnosticLine -Line $line
    }
}

function Write-WinToolDiagnosticLine {
    param(
        [Parameter(Mandatory = $true)][string]$Line,
        [string]$Path
    )
    try {
        if ([string]::IsNullOrWhiteSpace($Path)) {
            if ([string]::IsNullOrWhiteSpace($env:TEMP)) {
                return
            }
            $directory = Join-Path $env:TEMP "WinTool"
            if (-not (Test-Path -LiteralPath $directory)) {
                New-Item -ItemType Directory -Path $directory -Force | Out-Null
            }
            $Path = Join-Path $directory "wintool.log"
        }
        Add-Content -LiteralPath $Path -Value ((Get-Date -Format "yyyy-MM-dd ") + $Line) -Encoding UTF8
    }
    catch {
        $null = $_.Exception.Message
    }
}

function ConvertTo-WinToolArgumentLine {
    param(
        [string[]]$ArgumentList
    )
    $parts = New-Object System.Collections.Generic.List[string]
    foreach ($argument in @($ArgumentList)) {
        if ($null -eq $argument) {
            continue
        }
        $text = [string]$argument
        if ($text -match '[\s"]') {
            $escaped = $text.Replace('"', '\"')
            $parts.Add('"' + $escaped + '"')
        }
        else {
            $parts.Add($text)
        }
    }
    return ($parts -join " ")
}

function Format-WinToolErrorText {
    param(
        $ErrorRecord,
        [string]$Title = "WinTool could not start."
    )
    if ($null -eq $ErrorRecord) {
        return $Title
    }
    $body = ""
    try {
        $body = ($ErrorRecord | Out-String).Trim()
    }
    catch {
        $body = [string]$ErrorRecord
    }
    if ([string]::IsNullOrWhiteSpace($body) -and $null -ne $ErrorRecord.Exception) {
        $body = [string]$ErrorRecord.Exception.Message
    }
    $text = $Title + "`r`n`r`n" + $body
    $stack = [string]$ErrorRecord.ScriptStackTrace
    if (-not [string]::IsNullOrWhiteSpace($stack)) {
        $text += "`r`n`r`n" + $stack
    }
    return $text
}

function Write-WinToolFailureLog {
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Text,
        [string]$Path
    )
    if ([string]::IsNullOrWhiteSpace($Path)) {
        $directory = Join-Path $env:TEMP "WinTool"
        if (-not (Test-Path -LiteralPath $directory)) {
            New-Item -ItemType Directory -Path $directory -Force | Out-Null
        }
        $Path = Join-Path $directory "wintool.log"
    }
    else {
        $directory = Split-Path -Parent $Path
        if (-not [string]::IsNullOrWhiteSpace($directory) -and -not (Test-Path -LiteralPath $directory)) {
            New-Item -ItemType Directory -Path $directory -Force | Out-Null
        }
    }
    $stamp = [DateTime]::UtcNow.ToString("yyyy-MM-ddTHH:mm:ssZ")
    $block = "==== $stamp ====`r`n" + $Text + "`r`n"
    Add-Content -LiteralPath $Path -Value $block -Encoding UTF8
    return $Path
}

function Show-WinToolFailure {
    param(
        $ErrorRecord
    )
    try {
        Show-WinToolConsole
    }
    catch {
        $null = $_.Exception.Message
    }
    $text = Format-WinToolErrorText -ErrorRecord $ErrorRecord
    $path = $null
    try {
        $path = Write-WinToolFailureLog -Text $text
    }
    catch {
        $path = $null
    }
    Write-Host ""
    Write-Host $text
    if (-not [string]::IsNullOrWhiteSpace($path)) {
        Write-Host ""
        Write-Host "Log: $path"
    }
    try {
        Add-Type -AssemblyName PresentationFramework -ErrorAction Stop
        $dialog = $text
        if (-not [string]::IsNullOrWhiteSpace($path)) {
            $dialog += "`r`n`r`nLog: $path"
        }
        if ($dialog.Length -gt 3500) {
            $dialog = $dialog.Substring(0, 3500) + "..."
        }
        [System.Windows.MessageBox]::Show($dialog, "WinTool") | Out-Null
    }
    catch {
        Write-Host $_.Exception.Message
    }
    if ($env:WINTOOL_PAUSE_ON_ERROR -eq "1") {
        Write-Host ""
        Write-Host "Press Enter to close this window."
        Read-Host | Out-Null
        exit 1
    }
}

function Write-WinToolUtf8File {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Text,
        [switch]$Bom
    )
    $encoding = New-Object System.Text.UTF8Encoding ([bool]$Bom)
    [System.IO.File]::WriteAllText($Path, $Text, $encoding)
}
# endregion

# region src/Private/Console.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

# WinTool is a window app, so the PowerShell console that starts it is hidden
# once the window is on screen. -ShowConsole (or WINTOOL_SHOW_CONSOLE=1) keeps
# it visible for debugging. Startup errors always bring the console back.

function Test-WinToolShowConsole {
    if ($script:WinToolShowConsole) {
        return $true
    }
    return ($env:WINTOOL_SHOW_CONSOLE -eq "1")
}

function Get-WinToolConsoleMode {
    param(
        [bool]$ShowConsole,
        [bool]$Unattended,
        [string]$TerminalSession,
        [string]$HiddenChild
    )
    # show: leave the console alone.
    # hide: hide this console while the window is open.
    # relaunch: the console belongs to Windows Terminal, which cannot be hidden
    #           from here, so WinTool starts again in its own hidden console.
    if ($ShowConsole -or $Unattended) {
        return "show"
    }
    if ($HiddenChild -eq "1") {
        return "hide"
    }
    if (-not [string]::IsNullOrWhiteSpace($TerminalSession)) {
        return "relaunch"
    }
    return "hide"
}

function Get-WinToolCurrentConsoleMode {
    return Get-WinToolConsoleMode -ShowConsole (Test-WinToolShowConsole) -Unattended ([bool]$script:WinToolUnattended) -TerminalSession ([string]$env:WT_SESSION) -HiddenChild ([string]$env:WINTOOL_HIDDEN)
}

function Initialize-WinToolConsoleApi {
    if ($null -ne ("WinToolConsoleApi" -as [type])) {
        return $true
    }
    if (-not (Test-WinToolWindows)) {
        return $false
    }
    try {
        Add-Type -TypeDefinition (Get-WinToolConsoleApiSource) -Language CSharp -ErrorAction Stop
        return $true
    }
    catch {
        return $false
    }
}

function Get-WinToolConsoleApiSource {
    return @"
using System;
using System.Runtime.InteropServices;
using System.Text;

public static class WinToolConsoleApi
{
    public delegate bool EnumWindowsProc(IntPtr handle, IntPtr param);

    [DllImport("kernel32.dll")]
    public static extern IntPtr GetConsoleWindow();

    [DllImport("user32.dll")]
    public static extern bool ShowWindow(IntPtr handle, int command);

    [DllImport("user32.dll", CharSet = CharSet.Unicode)]
    public static extern IntPtr FindWindow(string className, string windowName);

    [DllImport("user32.dll")]
    public static extern bool SetForegroundWindow(IntPtr handle);

    [DllImport("user32.dll")]
    public static extern bool IsIconic(IntPtr handle);

    [DllImport("user32.dll")]
    public static extern bool IsWindowVisible(IntPtr handle);

    [DllImport("user32.dll")]
    public static extern bool AllowSetForegroundWindow(int processId);

    [DllImport("user32.dll")]
    public static extern bool EnumWindows(EnumWindowsProc callback, IntPtr param);

    [DllImport("user32.dll", CharSet = CharSet.Unicode)]
    public static extern int GetWindowText(IntPtr handle, StringBuilder buffer, int maxCount);

    [DllImport("user32.dll", CharSet = CharSet.Unicode)]
    public static extern int GetClassName(IntPtr handle, StringBuilder buffer, int maxCount);

    public static IntPtr FindWinToolWindow()
    {
        IntPtr found = IntPtr.Zero;
        EnumWindows(delegate(IntPtr handle, IntPtr param)
        {
            if (!IsWindowVisible(handle)) { return true; }
            StringBuilder title = new StringBuilder(64);
            if (GetWindowText(handle, title, title.Capacity) <= 0) { return true; }
            if (!string.Equals(title.ToString(), "WinTool", StringComparison.Ordinal)) { return true; }
            StringBuilder cls = new StringBuilder(128);
            if (GetClassName(handle, cls, cls.Capacity) <= 0) { return true; }
            if (!cls.ToString().StartsWith("HwndWrapper[", StringComparison.Ordinal)) { return true; }
            found = handle;
            return false;
        }, IntPtr.Zero);
        return found;
    }

    public static bool FocusWinToolWindow()
    {
        IntPtr handle = FindWinToolWindow();
        if (handle == IntPtr.Zero) { return false; }
        if (IsIconic(handle)) { ShowWindow(handle, 9); }
        else { ShowWindow(handle, 5); }
        SetForegroundWindow(handle);
        return true;
    }
}
"@
}

function Set-WinToolConsoleVisible {
    param(
        [Parameter(Mandatory = $true)][bool]$Visible
    )
    if (-not (Initialize-WinToolConsoleApi)) {
        return $false
    }
    try {
        $handle = [WinToolConsoleApi]::GetConsoleWindow()
        if ($handle -eq [IntPtr]::Zero) {
            return $false
        }
        $command = 0
        if ($Visible) {
            $command = 5
        }
        $null = [WinToolConsoleApi]::ShowWindow($handle, $command)
        $script:WinToolConsoleHidden = -not $Visible
        return $true
    }
    catch {
        return $false
    }
}

function Hide-WinToolConsole {
    if ((Get-WinToolCurrentConsoleMode) -eq "show") {
        return
    }
    $null = Set-WinToolConsoleVisible -Visible $false
}

function Show-WinToolConsole {
    if ($script:WinToolConsoleHidden -or $env:WINTOOL_HIDDEN -eq "1") {
        $null = Set-WinToolConsoleVisible -Visible $true
    }
}
# endregion

# region src/Private/Json.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function ConvertTo-WinToolJsonString {
    param(
        [AllowNull()][string]$Text
    )
    if ($null -eq $Text) {
        return "null"
    }
    $builder = New-Object System.Text.StringBuilder
    [void]$builder.Append('"')
    foreach ($char in $Text.ToCharArray()) {
        $code = [int]$char
        if ($code -eq 34) {
            [void]$builder.Append('\"')
        }
        elseif ($code -eq 92) {
            [void]$builder.Append('\\')
        }
        elseif ($code -eq 8) {
            [void]$builder.Append('\b')
        }
        elseif ($code -eq 12) {
            [void]$builder.Append('\f')
        }
        elseif ($code -eq 10) {
            [void]$builder.Append('\n')
        }
        elseif ($code -eq 13) {
            [void]$builder.Append('\r')
        }
        elseif ($code -eq 9) {
            [void]$builder.Append('\t')
        }
        elseif ($code -lt 32) {
            [void]$builder.Append('\u')
            [void]$builder.Append($code.ToString("x4"))
        }
        else {
            [void]$builder.Append($char)
        }
    }
    [void]$builder.Append('"')
    return $builder.ToString()
}

function ConvertTo-WinToolJsonText {
    param(
        $Value,
        [int]$Indent = 0
    )
    $pad = " " * ($Indent * 2)
    $next = $Indent + 1
    $inner = " " * ($next * 2)

    if ($null -eq $Value) {
        return "null"
    }
    if ($Value -is [string]) {
        return (ConvertTo-WinToolJsonString -Text $Value)
    }
    if ($Value -is [bool]) {
        if ($Value) { return "true" }
        return "false"
    }
    if ($Value -is [ValueType]) {
        return [Convert]::ToString($Value, [System.Globalization.CultureInfo]::InvariantCulture)
    }

    $isCustom = $Value -is [System.Management.Automation.PSCustomObject]
    if (-not $isCustom -and $Value -is [System.Collections.IDictionary]) {
        $names = @($Value.Keys)
        if ($names.Count -eq 0) {
            return "{}"
        }
        $lines = New-Object System.Collections.Generic.List[string]
        foreach ($name in $names) {
            $encoded = ConvertTo-WinToolJsonString -Text ([string]$name)
            $child = ConvertTo-WinToolJsonText -Value $Value[$name] -Indent $next
            $lines.Add($inner + $encoded + ": " + $child)
        }
        return "{`n" + ($lines -join ",`n") + "`n" + $pad + "}"
    }

    if (-not $isCustom -and $Value -is [System.Collections.IEnumerable]) {
        $items = @($Value)
        if ($items.Count -eq 0) {
            return "[]"
        }
        $lines = New-Object System.Collections.Generic.List[string]
        foreach ($item in $items) {
            $lines.Add($inner + (ConvertTo-WinToolJsonText -Value $item -Indent $next))
        }
        return "[`n" + ($lines -join ",`n") + "`n" + $pad + "]"
    }

    $properties = @($Value.PSObject.Properties)
    if ($properties.Count -eq 0) {
        return "{}"
    }
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($property in $properties) {
        $encoded = ConvertTo-WinToolJsonString -Text ([string]$property.Name)
        $child = ConvertTo-WinToolJsonText -Value $property.Value -Indent $next
        $lines.Add($inner + $encoded + ": " + $child)
    }
    return "{`n" + ($lines -join ",`n") + "`n" + $pad + "}"
}

function ConvertTo-WinToolPlainJson {
    param(
        [AllowEmptyString()][string]$Text
    )
    if ([string]::IsNullOrEmpty($Text)) {
        return $Text
    }
    $builder = New-Object System.Text.StringBuilder
    $chars = $Text.ToCharArray()
    $inString = $false
    $escape = $false
    $index = 0
    while ($index -lt $chars.Length) {
        $char = $chars[$index]
        if ($inString) {
            [void]$builder.Append($char)
            if ($escape) {
                $escape = $false
            }
            elseif ($char -eq '\') {
                $escape = $true
            }
            elseif ($char -eq '"') {
                $inString = $false
            }
            $index++
            continue
        }
        if ($char -eq '"') {
            $inString = $true
            [void]$builder.Append($char)
            $index++
            continue
        }
        if ($char -eq '/' -and ($index + 1) -lt $chars.Length) {
            $next = $chars[$index + 1]
            if ($next -eq '/') {
                $index += 2
                while ($index -lt $chars.Length -and $chars[$index] -ne "`n") {
                    $index++
                }
                continue
            }
            if ($next -eq '*') {
                $index += 2
                while (($index + 1) -lt $chars.Length -and -not ($chars[$index] -eq '*' -and $chars[$index + 1] -eq '/')) {
                    $index++
                }
                if (($index + 1) -lt $chars.Length) {
                    $index += 2
                }
                else {
                    $index = $chars.Length
                }
                continue
            }
        }
        [void]$builder.Append($char)
        $index++
    }
    return [regex]::Replace($builder.ToString(), ',(?=\s*[}\]])', '')
}

function ConvertFrom-WinToolJsonText {
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Text
    )
    $plain = ConvertTo-WinToolPlainJson -Text $Text
    if ([string]::IsNullOrWhiteSpace($plain)) {
        throw "The JSON text was empty."
    }
    return ($plain | ConvertFrom-Json)
}

function Read-WinToolJsonFile {
    param(
        [Parameter(Mandatory = $true)][string]$Path
    )
    $text = [System.IO.File]::ReadAllText($Path)
    return (ConvertFrom-WinToolJsonText -Text $text)
}

function Write-WinToolJsonFile {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)]$Value
    )
    $json = ConvertTo-WinToolJsonText -Value $Value
    Write-WinToolUtf8File -Path $Path -Text ($json + "`n")
}
# endregion

# region src/Private/Catalog.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function Get-WinToolAppCatalog {
    return (ConvertFrom-WinToolJsonText -Text (Get-WinToolPayloadText -Name "Apps"))
}

function Get-WinToolTweakCatalog {
    return (ConvertFrom-WinToolJsonText -Text (Get-WinToolPayloadText -Name "Tweaks"))
}

function Get-WinToolTerminalCatalog {
    return (ConvertFrom-WinToolJsonText -Text (Get-WinToolPayloadText -Name "Terminal"))
}

function Get-WinToolUpdateCatalog {
    return (ConvertFrom-WinToolJsonText -Text (Get-WinToolPayloadText -Name "Updates"))
}

function Get-WinToolPresetTweak {
    param(
        [Parameter(Mandatory = $true)]$Catalog,
        [Parameter(Mandatory = $true)][string]$PresetId
    )
    $matched = New-Object System.Collections.Generic.List[object]
    foreach ($tweak in @($Catalog.tweaks)) {
        $presets = @(Get-WinToolNote -Object $tweak -Name "presets" -Default @())
        if ($presets -contains $PresetId) {
            $matched.Add($tweak)
        }
    }
    return $matched.ToArray()
}

function Test-WinToolWingetId {
    param(
        [string]$Id
    )
    if ([string]::IsNullOrWhiteSpace($Id)) {
        return $false
    }
    return ($Id -match '^[A-Za-z0-9][A-Za-z0-9._+-]*\.[A-Za-z0-9][A-Za-z0-9._+-]*$')
}

function Add-WinToolDataError {
    param(
        $Errors,
        [string]$Message
    )
    $Errors.Add($Message)
}

function Test-WinToolRegistryAction {
    param(
        $Action,
        [string]$Label,
        $Errors
    )
    $type = [string](Get-WinToolNote -Object $Action -Name "type" -Default "")
    if ($type -eq "group") {
        $nested = @(Get-WinToolNote -Object $Action -Name "actions" -Default @())
        if ($nested.Count -eq 0) {
            Add-WinToolDataError -Errors $Errors -Message "$Label group has no actions."
        }
        foreach ($child in $nested) {
            Test-WinToolRegistryAction -Action $child -Label $Label -Errors $Errors
        }
        return
    }
    if ($type -eq "registry" -or $type -eq "registry-remove") {
        $entries = @(Get-WinToolNote -Object $Action -Name "entries" -Default @())
        if ($entries.Count -eq 0) {
            Add-WinToolDataError -Errors $Errors -Message "$Label has no registry entries."
        }
        foreach ($entry in $entries) {
            $path = [string](Get-WinToolNote -Object $entry -Name "path" -Default "")
            if ($path -notmatch '^(HKCU|HKLM):\\') {
                Add-WinToolDataError -Errors $Errors -Message "$Label has a registry path that is not HKCU or HKLM."
            }
            $nameProperty = $entry.PSObject.Properties["name"]
            if ($null -eq $nameProperty) {
                Add-WinToolDataError -Errors $Errors -Message "$Label is missing a registry value name."
            }
            if ($type -eq "registry") {
                $kind = [string](Get-WinToolNote -Object $entry -Name "kind" -Default "")
                if (@("DWord", "QWord", "String", "ExpandString", "MultiString") -notcontains $kind) {
                    Add-WinToolDataError -Errors $Errors -Message "$Label uses an unknown registry kind '$kind'."
                }
                if ($null -eq $entry.PSObject.Properties["value"]) {
                    Add-WinToolDataError -Errors $Errors -Message "$Label is missing a registry value."
                }
            }
        }
        return
    }
    if ($type -eq "registry-key") {
        $path = [string](Get-WinToolNote -Object $Action -Name "path" -Default "")
        $operation = [string](Get-WinToolNote -Object $Action -Name "operation" -Default "")
        if ($path -notmatch '^(HKCU|HKLM):\\') {
            Add-WinToolDataError -Errors $Errors -Message "$Label has a registry key outside HKCU or HKLM."
        }
        if (@("add", "remove") -notcontains $operation) {
            Add-WinToolDataError -Errors $Errors -Message "$Label registry key operation must be add or remove."
        }
        return
    }
    if ($type -eq "service") {
        $name = [string](Get-WinToolNote -Object $Action -Name "name" -Default "")
        $startup = [string](Get-WinToolNote -Object $Action -Name "startupType" -Default "")
        if ([string]::IsNullOrWhiteSpace($name)) {
            Add-WinToolDataError -Errors $Errors -Message "$Label is missing a service name."
        }
        if (@("Automatic", "Manual", "Disabled") -notcontains $startup) {
            Add-WinToolDataError -Errors $Errors -Message "$Label has an unknown service startup type."
        }
        return
    }
    if ($type -eq "scheduled-task") {
        $taskName = [string](Get-WinToolNote -Object $Action -Name "taskName" -Default "")
        $taskPath = [string](Get-WinToolNote -Object $Action -Name "taskPath" -Default "")
        $state = [string](Get-WinToolNote -Object $Action -Name "state" -Default "")
        if ([string]::IsNullOrWhiteSpace($taskName) -or [string]::IsNullOrWhiteSpace($taskPath)) {
            Add-WinToolDataError -Errors $Errors -Message "$Label is missing a scheduled task name or path."
        }
        if (@("Enabled", "Disabled") -notcontains $state) {
            Add-WinToolDataError -Errors $Errors -Message "$Label has an unknown scheduled task state."
        }
        return
    }
    if ($type -eq "appx") {
        $packages = @(Get-WinToolNote -Object $Action -Name "packages" -Default @())
        if ($packages.Count -eq 0) {
            Add-WinToolDataError -Errors $Errors -Message "$Label does not list any inbox apps."
        }
        foreach ($package in $packages) {
            if ([string]$package -match 'WindowsStore|SecHealthUI') {
                Add-WinToolDataError -Errors $Errors -Message "$Label tries to remove a protected inbox app."
            }
        }
        return
    }
    if ($type -eq "appx-restore") {
        return
    }
    Add-WinToolDataError -Errors $Errors -Message "$Label uses an unknown action type '$type'."
}

function Test-WinToolDataFile {
    $errors = New-Object System.Collections.Generic.List[string]
    $apps = Get-WinToolAppCatalog
    $tweaks = Get-WinToolTweakCatalog
    $terminal = Get-WinToolTerminalCatalog
    $updates = Get-WinToolUpdateCatalog

    if ([int](Get-WinToolNote -Object $apps -Name "schemaVersion" -Default 0) -ne 1) {
        Add-WinToolDataError -Errors $errors -Message "apps.json schemaVersion must be 1."
    }
    if ([int](Get-WinToolNote -Object $tweaks -Name "schemaVersion" -Default 0) -ne 1) {
        Add-WinToolDataError -Errors $errors -Message "tweaks.json schemaVersion must be 1."
    }
    if ([int](Get-WinToolNote -Object $terminal -Name "schemaVersion" -Default 0) -ne 1) {
        Add-WinToolDataError -Errors $errors -Message "terminal.json schemaVersion must be 1."
    }
    if ([int](Get-WinToolNote -Object $updates -Name "schemaVersion" -Default 0) -ne 1) {
        Add-WinToolDataError -Errors $errors -Message "updates.json schemaVersion must be 1."
    }

    $appIds = @{}
    $categories = @(Get-WinToolNote -Object $apps -Name "categories" -Default @())
    if ($categories.Count -eq 0) {
        Add-WinToolDataError -Errors $errors -Message "apps.json has no categories."
    }
    foreach ($category in $categories) {
        $categoryId = [string](Get-WinToolNote -Object $category -Name "id" -Default "")
        $categoryName = [string](Get-WinToolNote -Object $category -Name "name" -Default "")
        if ([string]::IsNullOrWhiteSpace($categoryId) -or [string]::IsNullOrWhiteSpace($categoryName)) {
            Add-WinToolDataError -Errors $errors -Message "A category is missing an id or name."
        }
        foreach ($app in @(Get-WinToolNote -Object $category -Name "apps" -Default @())) {
            $id = [string](Get-WinToolNote -Object $app -Name "id" -Default "")
            $name = [string](Get-WinToolNote -Object $app -Name "name" -Default "")
            $description = [string](Get-WinToolNote -Object $app -Name "description" -Default "")
            $wingetId = [string](Get-WinToolNote -Object $app -Name "wingetId" -Default "")
            if ([string]::IsNullOrWhiteSpace($id) -or [string]::IsNullOrWhiteSpace($name) -or [string]::IsNullOrWhiteSpace($description)) {
                Add-WinToolDataError -Errors $errors -Message "An app in '$categoryId' is missing an id, name, or description."
            }
            if ($appIds.ContainsKey($id)) {
                Add-WinToolDataError -Errors $errors -Message "Duplicate app id '$id'."
            }
            else {
                $appIds[$id] = $true
            }
            if (-not (Test-WinToolWingetId -Id $wingetId)) {
                Add-WinToolDataError -Errors $errors -Message "App '$id' has an unexpected winget id '$wingetId'."
            }
            $scope = [string](Get-WinToolNote -Object $app -Name "scope" -Default "")
            if (-not [string]::IsNullOrWhiteSpace($scope) -and @("user", "machine") -notcontains $scope) {
                Add-WinToolDataError -Errors $errors -Message "App '$id' has an unknown scope."
            }
            foreach ($detectName in @(Get-WinToolNote -Object $app -Name "detectNames" -Default @())) {
                if ([string]::IsNullOrWhiteSpace([string]$detectName) -or [string]$detectName -match '[\r\n]') {
                    Add-WinToolDataError -Errors $errors -Message "App '$id' has an empty or multi-line detect name."
                }
            }
        }
    }

    $presetIds = @{}
    foreach ($preset in @(Get-WinToolNote -Object $tweaks -Name "presets" -Default @())) {
        $presetId = [string](Get-WinToolNote -Object $preset -Name "id" -Default "")
        $presetName = [string](Get-WinToolNote -Object $preset -Name "name" -Default "")
        if ([string]::IsNullOrWhiteSpace($presetId) -or [string]::IsNullOrWhiteSpace($presetName)) {
            Add-WinToolDataError -Errors $errors -Message "A preset is missing an id or name."
            continue
        }
        if ($presetIds.ContainsKey($presetId)) {
            Add-WinToolDataError -Errors $errors -Message "Duplicate preset id '$presetId'."
        }
        $presetIds[$presetId] = $true
    }

    $tweakIds = @{}
    foreach ($tweak in @(Get-WinToolNote -Object $tweaks -Name "tweaks" -Default @())) {
        $id = [string](Get-WinToolNote -Object $tweak -Name "id" -Default "")
        $name = [string](Get-WinToolNote -Object $tweak -Name "name" -Default "")
        $description = [string](Get-WinToolNote -Object $tweak -Name "description" -Default "")
        $risk = [string](Get-WinToolNote -Object $tweak -Name "risk" -Default "")
        $refresh = [string](Get-WinToolNote -Object $tweak -Name "refresh" -Default "")
        if ([string]::IsNullOrWhiteSpace($id) -or [string]::IsNullOrWhiteSpace($name) -or [string]::IsNullOrWhiteSpace($description)) {
            Add-WinToolDataError -Errors $errors -Message "A tweak is missing an id, name, or description."
        }
        if ($tweakIds.ContainsKey($id)) {
            Add-WinToolDataError -Errors $errors -Message "Duplicate tweak id '$id'."
        }
        else {
            $tweakIds[$id] = $true
        }
        if (@("safe", "caution") -notcontains $risk) {
            Add-WinToolDataError -Errors $errors -Message "Tweak '$id' has an unknown risk."
        }
        if (@("none", "theme", "explorer") -notcontains $refresh) {
            Add-WinToolDataError -Errors $errors -Message "Tweak '$id' has an unknown refresh value."
        }
        foreach ($presetId in @(Get-WinToolNote -Object $tweak -Name "presets" -Default @())) {
            if (-not $presetIds.ContainsKey([string]$presetId)) {
                Add-WinToolDataError -Errors $errors -Message "Tweak '$id' uses an unknown preset '$presetId'."
            }
        }
        $apply = Get-WinToolNote -Object $tweak -Name "apply"
        $undo = Get-WinToolNote -Object $tweak -Name "undo"
        if ($null -eq $apply -or $null -eq $undo) {
            Add-WinToolDataError -Errors $errors -Message "Tweak '$id' needs both apply and undo."
            continue
        }
        Test-WinToolRegistryAction -Action $apply -Label "Tweak '$id' apply" -Errors $errors
        Test-WinToolRegistryAction -Action $undo -Label "Tweak '$id' undo" -Errors $errors
    }

    foreach ($prompt in @(Get-WinToolNote -Object $terminal -Name "prompts" -Default @())) {
        $id = [string](Get-WinToolNote -Object $prompt -Name "id" -Default "")
        $wingetId = [string](Get-WinToolNote -Object $prompt -Name "wingetId" -Default "")
        $shell = [string](Get-WinToolNote -Object $prompt -Name "shell" -Default "")
        if ([string]::IsNullOrWhiteSpace($id) -or [string]::IsNullOrWhiteSpace($shell)) {
            Add-WinToolDataError -Errors $errors -Message "A terminal prompt is missing an id or shell."
        }
        if (-not [string]::IsNullOrWhiteSpace($wingetId) -and -not (Test-WinToolWingetId -Id $wingetId)) {
            Add-WinToolDataError -Errors $errors -Message "Terminal prompt '$id' has an unexpected winget id."
        }
    }
    foreach ($scheme in @(Get-WinToolNote -Object $terminal -Name "schemes" -Default @())) {
        # Windows Terminal drops a scheme without all 16 colors, and then any
        # profile that names it shows an "invalid colorScheme" warning.
        $palette = Get-WinToolNote -Object $scheme -Name "palette"
        foreach ($key in $script:WinToolSchemeColorKeys) {
            $value = [string](Get-WinToolNote -Object $palette -Name $key -Default "")
            if ($value -notmatch '^#[0-9A-Fa-f]{6}$') {
                Add-WinToolDataError -Errors $errors -Message ("Color scheme '" + [string]$scheme.id + "' needs a " + $key + " color.")
            }
        }
    }
    if (@(Get-WinToolNote -Object $terminal -Name "prompts" -Default @()).Count -lt 8) {
        Add-WinToolDataError -Errors $errors -Message "terminal.json should list the prompt engines."
    }
    $fontDoc = ConvertFrom-WinToolJsonText -Text (Get-WinToolPayloadText -Name "Fonts")
    $fontRows = @(Get-WinToolNote -Object $fontDoc -Name "fonts" -Default @())
    if ($fontRows.Count -lt 60) {
        Add-WinToolDataError -Errors $errors -Message "fonts.json should include the Nerd Fonts catalog."
    }
    foreach ($font in $fontRows) {
        $id = [string](Get-WinToolNote -Object $font -Name "id" -Default "")
        $face = [string](Get-WinToolNote -Object $font -Name "face" -Default "")
        $match = [string](Get-WinToolNote -Object $font -Name "match" -Default "")
        $wingetId = [string](Get-WinToolNote -Object $font -Name "wingetId" -Default "")
        if ([string]::IsNullOrWhiteSpace($id) -or [string]::IsNullOrWhiteSpace($face) -or [string]::IsNullOrWhiteSpace($match)) {
            Add-WinToolDataError -Errors $errors -Message "A terminal font is missing an id, face, or match token."
        }
        if (-not [string]::IsNullOrWhiteSpace($wingetId) -and -not (Test-WinToolWingetId -Id $wingetId)) {
            Add-WinToolDataError -Errors $errors -Message "Terminal font '$id' has an unexpected winget id."
        }
        $asset = [string](Get-WinToolNote -Object $font -Name "asset" -Default "")
        $github = Get-WinToolNote -Object $font -Name "github"
        $sources = 0
        if (-not [string]::IsNullOrWhiteSpace($wingetId)) { $sources++ }
        if (-not [string]::IsNullOrWhiteSpace($asset)) { $sources++ }
        if ($null -ne $github) { $sources++ }
        if ($sources -ne 1) {
            Add-WinToolDataError -Errors $errors -Message "Terminal font '$id' needs exactly one source: a Nerd Fonts asset, a GitHub release, or a checked winget id."
        }
        if ([string](Get-WinToolNote -Object $font -Name "source" -Default "") -eq "nerd-fonts" -and [string]::IsNullOrWhiteSpace($asset)) {
            Add-WinToolDataError -Errors $errors -Message "Nerd Font '$id' must come from the Nerd Fonts release."
        }
        if ($null -ne $github) {
            $repo = [string](Get-WinToolNote -Object $github -Name "repo" -Default "")
            $pattern = [string](Get-WinToolNote -Object $github -Name "asset" -Default "")
            if ($repo -notmatch '^[A-Za-z0-9-]+/[A-Za-z0-9._-]+$' -or [string]::IsNullOrWhiteSpace($pattern) -or @(Get-WinToolNote -Object $github -Name "files" -Default @()).Count -eq 0) {
                Add-WinToolDataError -Errors $errors -Message "Terminal font '$id' has an incomplete GitHub source."
            }
        }
    }
    $themeDoc = ConvertFrom-WinToolJsonText -Text (Get-WinToolPayloadText -Name "OmpThemes")
    $themeRows = @(Get-WinToolNote -Object $themeDoc -Name "themes" -Default @())
    if ($themeRows.Count -lt 80) {
        Add-WinToolDataError -Errors $errors -Message "omp-themes.json should include the official Oh My Posh themes."
    }
    foreach ($theme in $themeRows) {
        $themeId = [string](Get-WinToolNote -Object $theme -Name "id" -Default "")
        $themeFile = [string](Get-WinToolNote -Object $theme -Name "file" -Default "")
        if ([string]::IsNullOrWhiteSpace($themeId) -or -not $themeFile.EndsWith(".omp.json")) {
            Add-WinToolDataError -Errors $errors -Message "An Oh My Posh theme is missing an id or file name."
        }
    }

    foreach ($vendor in @(Get-WinToolNote -Object $updates -Name "vendors" -Default @())) {
        $id = [string](Get-WinToolNote -Object $vendor -Name "id" -Default "")
        $url = [string](Get-WinToolNote -Object $vendor -Name "url" -Default "")
        $match = @(Get-WinToolNote -Object $vendor -Name "match" -Default @())
        if ([string]::IsNullOrWhiteSpace($id) -or $match.Count -eq 0) {
            Add-WinToolDataError -Errors $errors -Message "A graphics vendor is missing an id or match list."
        }
        if ($url -notmatch '^https://') {
            Add-WinToolDataError -Errors $errors -Message "Vendor '$id' must use an https link."
        }
    }

    Test-WinToolFixCatalog -Catalog (Get-WinToolFixCatalog) -Errors $errors
    Test-WinToolFeatureCatalog -Catalog (Get-WinToolFeatureCatalog) -Errors $errors
    Test-WinToolUpdateModeCatalog -Catalog $updates -Errors $errors
    Test-WinToolSystemCatalog -Catalog (Get-WinToolSystemCatalog) -Errors $errors

    return $errors.ToArray()
}
# endregion

# region src/Private/Winget.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

# winget returns 0x8A15002B when the package is already installed and no upgrade applies.
$script:WinToolWingetAlreadyInstalled = -1978335189

function Sync-WinToolProcessPath {
    if (-not (Test-WinToolWindows)) {
        return
    }
    $machine = [Environment]::GetEnvironmentVariable("Path", "Machine")
    $user = [Environment]::GetEnvironmentVariable("Path", "User")
    if ([string]::IsNullOrWhiteSpace($machine)) {
        $env:Path = [string]$user
        return
    }
    if ([string]::IsNullOrWhiteSpace($user)) {
        $env:Path = [string]$machine
        return
    }
    $env:Path = "$machine;$user"
}

function Get-WinToolWingetCandidate {
    # Every winget.exe this PC might have, best first. The per-user alias in
    # WindowsApps is what a normal shell runs, but an elevated process can
    # fail to start it ("The file cannot be accessed by the system"), so the
    # real file inside the App Installer package is kept as a fallback.
    if (-not (Test-WinToolWindows)) {
        return @()
    }
    Sync-WinToolProcessPath
    $list = New-Object System.Collections.Generic.List[string]
    $command = Get-Command -Name "winget.exe" -ErrorAction SilentlyContinue
    if ($null -ne $command -and -not [string]::IsNullOrWhiteSpace([string]$command.Source)) {
        $list.Add([string]$command.Source)
    }
    if (-not [string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
        $alias = Join-Path $env:LOCALAPPDATA "Microsoft\WindowsApps\winget.exe"
        if (Test-Path -LiteralPath $alias) {
            $list.Add($alias)
        }
    }
    try {
        foreach ($package in @(Get-AppxPackage -Name "Microsoft.DesktopAppInstaller" -ErrorAction Stop | Sort-Object -Property Version -Descending)) {
            $file = Join-Path ([string]$package.InstallLocation) "winget.exe"
            if (Test-Path -LiteralPath $file) {
                $list.Add($file)
            }
        }
    }
    catch {
        $null = $_.Exception.Message
    }
    $pattern = Join-Path $env:ProgramFiles "WindowsApps\Microsoft.DesktopAppInstaller_*__8wekyb3d8bbwe\winget.exe"
    foreach ($item in @(Resolve-Path -Path $pattern -ErrorAction SilentlyContinue | Sort-Object -Property Path -Descending)) {
        $list.Add([string]$item.Path)
    }
    $seen = @{}
    $unique = New-Object System.Collections.Generic.List[string]
    foreach ($path in $list) {
        $key = $path.ToLowerInvariant()
        if (-not $seen.ContainsKey($key)) {
            $seen[$key] = $true
            $unique.Add($path)
        }
    }
    return $unique.ToArray()
}

function Get-WinToolWingetPath {
    if ($null -ne $script:WinToolWingetWorking -and (Test-Path -LiteralPath $script:WinToolWingetWorking)) {
        return $script:WinToolWingetWorking
    }
    $candidates = @(Get-WinToolWingetCandidate)
    if ($candidates.Count -eq 0) {
        return $null
    }
    return $candidates[0]
}

function ConvertFrom-WinToolWingetExport {
    param(
        [AllowEmptyString()][string]$Text
    )
    # The file winget export writes: Sources[].Packages[].PackageIdentifier.
    $ids = New-Object System.Collections.Generic.List[string]
    if ([string]::IsNullOrWhiteSpace($Text)) {
        return $ids.ToArray()
    }
    $data = ConvertFrom-Json -InputObject $Text.TrimStart([char]0xFEFF)
    foreach ($source in @(Get-WinToolNote -Object $data -Name "Sources" -Default @())) {
        foreach ($package in @(Get-WinToolNote -Object $source -Name "Packages" -Default @())) {
            $id = [string](Get-WinToolNote -Object $package -Name "PackageIdentifier" -Default "")
            if (-not [string]::IsNullOrWhiteSpace($id)) {
                $ids.Add($id)
            }
        }
    }
    return $ids.ToArray()
}

function Get-WinToolWingetArgument {
    param(
        [string]$Id,
        [string]$Scope,
        [ValidateSet("install", "upgrade", "uninstall", "upgrade-all")][string]$Action = "install"
    )
    $arguments = New-Object System.Collections.Generic.List[string]
    if ($Action -eq "upgrade-all") {
        $arguments.Add("upgrade")
        $arguments.Add("--all")
        $arguments.Add("--source")
        $arguments.Add("winget")
        $arguments.Add("--accept-package-agreements")
        $arguments.Add("--accept-source-agreements")
        $arguments.Add("--disable-interactivity")
        return $arguments.ToArray()
    }
    if ([string]::IsNullOrWhiteSpace($Id)) {
        throw "A winget id is needed for $Action."
    }
    $arguments.Add($Action)
    $arguments.Add("--id")
    $arguments.Add($Id)
    $arguments.Add("--exact")
    $arguments.Add("--source")
    $arguments.Add("winget")
    if ($Action -ne "uninstall") {
        $arguments.Add("--accept-package-agreements")
    }
    $arguments.Add("--accept-source-agreements")
    $arguments.Add("--disable-interactivity")
    if ($Action -eq "install" -and -not [string]::IsNullOrWhiteSpace($Scope)) {
        $arguments.Add("--scope")
        $arguments.Add($Scope)
    }
    return $arguments.ToArray()
}

function Get-WinToolWingetActionLabel {
    param(
        [string]$Action,
        [string]$Name
    )
    switch ($Action) {
        "upgrade" { return "Update $Name" }
        "uninstall" { return "Uninstall $Name" }
        "upgrade-all" { return "Update every app winget can update" }
        default { return "Install $Name" }
    }
}

function Get-WinToolWingetOutcomeText {
    param(
        [string]$Action,
        [string]$Status
    )
    if ($Status -eq "AlreadyInstalled") {
        if ($Action -eq "upgrade" -or $Action -eq "upgrade-all") {
            return "already up to date"
        }
        return "already installed"
    }
    return "done"
}

# Detecting installed apps runs in a background runspace so the window stays
# responsive. "winget export" gives exact package ids. The upgrade table is
# read by matching known catalog ids, because its column widths vary.
function Get-WinToolAppDetectionScript {
    # Runs in a background runspace on Windows PowerShell 5.1. It does not use
    # ErrorActionPreference Stop around winget: on 5.1 any line winget writes
    # to stderr would then abort the whole check. Every step is written to
    # $Sync.Log so the window can put it in the log files.
    $scriptText = @'
param($Sync, $Candidates, $ExportPath)
$ErrorActionPreference = "Continue"
$log = New-Object System.Collections.Generic.List[string]
$Sync.Log = $log
try {
    try {
        [Console]::OutputEncoding = [System.Text.Encoding]::UTF8
    }
    catch {
        $log.Add("Could not switch the console to UTF-8: " + $_.Exception.Message)
    }
    $winget = $null
    foreach ($candidate in @($Candidates)) {
        try {
            $version = (& $candidate --version 2>&1 | ForEach-Object { [string]$_ }) -join " "
            if ($LASTEXITCODE -eq 0) {
                $winget = $candidate
                $log.Add(("Using {0} ({1})" -f $candidate, $version.Trim()))
                break
            }
            $log.Add(("{0} exited with {1}: {2}" -f $candidate, $LASTEXITCODE, $version.Trim()))
        }
        catch {
            $log.Add(("{0} did not start: {1}" -f $candidate, $_.Exception.Message))
        }
    }
    if ($null -eq $winget) {
        throw "No winget.exe could be started."
    }
    $Sync.Winget = $winget
    $common = @("--source", "winget", "--accept-source-agreements", "--disable-interactivity")

    if (Test-Path -LiteralPath $ExportPath) {
        Remove-Item -LiteralPath $ExportPath -Force -ErrorAction SilentlyContinue
    }
    $exportArgs = @("export", "--output", $ExportPath) + $common
    $exportOut = (& $winget @exportArgs 2>&1 | ForEach-Object { [string]$_ }) -join "`n"
    $log.Add(("winget export exited with {0}." -f $LASTEXITCODE))
    $Sync.ExportText = ""
    if (Test-Path -LiteralPath $ExportPath) {
        $Sync.ExportText = [System.IO.File]::ReadAllText($ExportPath)
        Remove-Item -LiteralPath $ExportPath -Force -ErrorAction SilentlyContinue
    }
    else {
        $log.Add("winget export wrote no file. Output: " + $exportOut.Trim())
    }

    $listArgs = @("list") + $common
    $Sync.ListText = (& $winget @listArgs 2>&1 | ForEach-Object { [string]$_ }) -join "`n"
    $log.Add(("winget list exited with {0}." -f $LASTEXITCODE))

    # Names of everything in Apps and features plus Store packages, for apps
    # winget cannot match to its source.
    $names = New-Object System.Collections.Generic.List[string]
    $keys = @(
        "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*",
        "HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*",
        "HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*"
    )
    foreach ($key in $keys) {
        foreach ($entry in @(Get-ItemProperty -Path $key -ErrorAction SilentlyContinue)) {
            $displayName = [string]$entry.DisplayName
            if (-not [string]::IsNullOrWhiteSpace($displayName)) {
                $names.Add($displayName)
            }
        }
    }
    try {
        foreach ($package in @(Get-AppxPackage -ErrorAction Stop)) {
            $names.Add([string]$package.Name)
        }
    }
    catch {
        $log.Add("Could not list Store apps: " + $_.Exception.Message)
    }
    $Sync.DisplayNames = $names.ToArray()
    $log.Add(("Read {0} names from Apps and features and the Store." -f $names.Count))

    # Start menu entries, so an installed app can be opened from its card.
    try {
        $startApps = New-Object System.Collections.Generic.List[string]
        foreach ($entry in @(Get-StartApps -ErrorAction Stop)) {
            $startApps.Add(([string]$entry.Name + "`t" + [string]$entry.AppID))
        }
        $Sync.StartApps = $startApps.ToArray()
        $log.Add(("Read {0} Start menu entries." -f $startApps.Count))
    }
    catch {
        $log.Add("Could not list Start menu apps: " + $_.Exception.Message)
    }

    $upgradeArgs = @("upgrade") + $common
    $Sync.UpgradeText = (& $winget @upgradeArgs 2>&1 | ForEach-Object { [string]$_ }) -join "`n"
    $log.Add(("winget upgrade exited with {0}." -f $LASTEXITCODE))
    $Sync.Ok = $true
}
catch {
    $Sync.Error = $_.Exception.Message
}
finally {
    $Sync.Done = $true
}
'@
    return $scriptText
}

function Get-WinToolTruncatedIdPrefix {
    param(
        [AllowEmptyString()][string]$Token
    )
    # Returns the id part of a token that winget cut short, or $null when the
    # token does not look cut. Plain character checks, no patterns built from ids.
    $allowed = "abcdefghijklmnopqrstuvwxyz0123456789._+-"
    $end = 0
    while ($end -lt $Token.Length -and $allowed.IndexOf([char]::ToLowerInvariant($Token[$end])) -ge 0) {
        $end++
    }
    $head = $Token.Substring(0, $end).TrimEnd(".")
    $tail = $Token.Substring($end)
    $cut = $false
    if ($tail.Length -gt 0) {
        $cut = $true
    }
    elseif ($Token.EndsWith("...", [System.StringComparison]::Ordinal)) {
        $cut = $true
    }
    if (-not $cut -or $head.Length -lt 6 -or $head.IndexOf(".") -lt 1) {
        return $null
    }
    return $head.ToLowerInvariant()
}

function Find-WinToolWingetIdInText {
    param(
        [AllowEmptyString()][string]$Text,
        [string[]]$KnownId
    )
    $found = New-Object System.Collections.Generic.List[string]
    if ([string]::IsNullOrWhiteSpace($Text)) {
        return $found.ToArray()
    }
    $lookup = @{}
    foreach ($id in @($KnownId)) {
        if (-not [string]::IsNullOrWhiteSpace($id)) {
            $lookup[$id.ToLowerInvariant()] = $id
        }
    }
    $seen = @{}
    foreach ($line in ($Text -split '\r?\n')) {
        foreach ($token in ($line -split '\s+')) {
            if ([string]::IsNullOrWhiteSpace($token)) {
                continue
            }
            $key = $token.ToLowerInvariant()
            $match = $null
            if ($lookup.ContainsKey($key)) {
                $match = $lookup[$key]
            }
            else {
                # winget shortens long ids with an ellipsis. Depending on the
                # console code page the ellipsis can arrive as "...", "?", or
                # mojibake, so take the id characters before it and accept a
                # unique catalog id that starts with them. Ids always have a dot.
                $prefix = Get-WinToolTruncatedIdPrefix -Token $key
                if ($null -ne $prefix) {
                    $candidates = New-Object System.Collections.Generic.List[string]
                    foreach ($candidate in $lookup.Keys) {
                        if ($candidate.StartsWith($prefix, [System.StringComparison]::Ordinal)) {
                            $candidates.Add($candidate)
                        }
                    }
                    if ($candidates.Count -eq 1) {
                        $match = $lookup[$candidates[0]]
                    }
                }
            }
            if ($null -ne $match -and -not $seen.ContainsKey($match)) {
                $seen[$match] = $true
                $found.Add($match)
            }
        }
    }
    return $found.ToArray()
}

$script:WinToolNameNoise = @("x64", "x86", "arm64", "amd64", "win64", "win32", "64", "32", "bit", "64bit", "32bit", "user", "machine", "version", "v")

function ConvertTo-WinToolAppNameKey {
    param(
        [AllowEmptyString()][string]$Text
    )
    # "WinRAR 7.01 (64-bit)" and "WinRAR" give the same key: lower-case words
    # with version numbers and architecture words dropped from the end.
    $tokens = New-Object System.Collections.Generic.List[string]
    foreach ($token in ([regex]::Split(([string]$Text).ToLowerInvariant(), '[^\p{L}\p{N}]+'))) {
        if (-not [string]::IsNullOrWhiteSpace($token)) {
            $tokens.Add($token)
        }
    }
    while ($tokens.Count -gt 1) {
        $last = $tokens[$tokens.Count - 1]
        if ($last -match '^\d+$' -or $script:WinToolNameNoise -contains $last) {
            $tokens.RemoveAt($tokens.Count - 1)
            continue
        }
        break
    }
    return ($tokens.ToArray() -join " ")
}

function Find-WinToolAppByName {
    param(
        [string[]]$DisplayName,
        $App
    )
    # Apps installed outside winget (a vendor installer or the Store) are
    # missing from winget export. Match them by the name Windows lists in
    # Apps and features, or by the Store package name, against the catalog
    # name and its detectNames. Names must match as whole words.
    $seen = @{}
    foreach ($name in @($DisplayName)) {
        $key = ConvertTo-WinToolAppNameKey -Text $name
        if (-not [string]::IsNullOrWhiteSpace($key)) {
            $seen[$key] = $true
        }
    }
    $found = New-Object System.Collections.Generic.List[string]
    foreach ($item in @($App)) {
        $names = @([string]$item.Name) + @($item.DetectNames)
        foreach ($name in $names) {
            $key = ConvertTo-WinToolAppNameKey -Text ([string]$name)
            if (-not [string]::IsNullOrWhiteSpace($key) -and $seen.ContainsKey($key)) {
                $found.Add([string]$item.WingetId)
                break
            }
        }
    }
    return $found.ToArray()
}

function Resolve-WinToolAppState {
    param(
        [string[]]$CatalogId,
        [string[]]$InstalledId,
        [AllowEmptyString()][string]$UpgradeText,
        [AllowEmptyString()][string]$ListText
    )
    $installed = @{}
    $known = @{}
    foreach ($id in @($CatalogId)) {
        if (-not [string]::IsNullOrWhiteSpace($id)) {
            $known[$id.ToLowerInvariant()] = $id
        }
    }
    foreach ($id in @($InstalledId)) {
        if ([string]::IsNullOrWhiteSpace($id)) {
            continue
        }
        $key = $id.ToLowerInvariant()
        if ($known.ContainsKey($key)) {
            $installed[$known[$key]] = $true
        }
    }
    # winget list catches packages that export leaves out.
    foreach ($id in @(Find-WinToolWingetIdInText -Text $ListText -KnownId $CatalogId)) {
        $installed[$id] = $true
    }
    $updates = @{}
    foreach ($id in @(Find-WinToolWingetIdInText -Text $UpgradeText -KnownId $CatalogId)) {
        $updates[$id] = $true
        $installed[$id] = $true
    }
    return [pscustomobject]@{
        Installed = $installed
        Updates = $updates
    }
}

function ConvertTo-WinToolWingetResult {
    param(
        [int]$ExitCode,
        [string]$Output
    )
    $status = "Failed"
    if ($ExitCode -eq 0) {
        $status = "Installed"
    }
    $already = $false
    if ($ExitCode -eq $script:WinToolWingetAlreadyInstalled) {
        $already = $true
    }
    if (-not [string]::IsNullOrWhiteSpace($Output) -and $Output -match '(?i)already installed|no available upgrade|no newer package version') {
        $already = $true
    }
    if ($already) {
        $status = "AlreadyInstalled"
    }
    return [pscustomobject]@{
        Status = $status
        ExitCode = $ExitCode
        Output = $Output
    }
}

function Get-WinToolAppPlan {
    param(
        $App,
        [ValidateSet("install", "upgrade", "uninstall")][string]$Action = "install"
    )
    $steps = New-Object System.Collections.Generic.List[object]
    foreach ($item in @($App)) {
        $name = Get-WinToolNote -Object $item -Name "Name"
        if ($null -eq $name) {
            $name = Get-WinToolNote -Object $item -Name "name" -Default "App"
        }
        $wingetId = Get-WinToolNote -Object $item -Name "WingetId"
        if ($null -eq $wingetId) {
            $wingetId = Get-WinToolNote -Object $item -Name "wingetId" -Default ""
        }
        $scope = Get-WinToolNote -Object $item -Name "Scope"
        if ($null -eq $scope) {
            $scope = Get-WinToolNote -Object $item -Name "scope" -Default ""
        }
        $steps.Add([pscustomobject]@{
            Type = "winget"
            Action = $Action
            Label = (Get-WinToolWingetActionLabel -Action $Action -Name ([string]$name))
            WingetId = [string]$wingetId
            Scope = [string]$scope
        })
    }
    return $steps.ToArray()
}

function Get-WinToolUpgradeAllPlan {
    return @([pscustomobject]@{
            Type = "winget"
            Action = "upgrade-all"
            Label = (Get-WinToolWingetActionLabel -Action "upgrade-all" -Name "")
            WingetId = ""
            Scope = ""
        })
}

function Resolve-WinToolAppLaunchId {
    # Finds the Start menu entry (shell:AppsFolder id) for a catalog app.
    # StartApp lines are "Name<TAB>AppID". Returns $null when nothing fits.
    param(
        [string]$Name,
        [string[]]$DetectName = @(),
        [string[]]$StartApp = @()
    )
    $wanted = New-Object System.Collections.Generic.List[string]
    foreach ($item in @(@($Name) + @($DetectName))) {
        if (-not [string]::IsNullOrWhiteSpace($item)) {
            $wanted.Add(([string]$item).Trim().ToLowerInvariant())
        }
    }
    if ($wanted.Count -eq 0) {
        return $null
    }
    $entries = New-Object System.Collections.Generic.List[object]
    foreach ($line in @($StartApp)) {
        $text = [string]$line
        $tab = $text.IndexOf("`t")
        if ($tab -lt 1) { continue }
        $entryName = $text.Substring(0, $tab).Trim()
        $appId = $text.Substring($tab + 1).Trim()
        if ([string]::IsNullOrWhiteSpace($appId)) { continue }
        $lower = $entryName.ToLowerInvariant()
        if ($lower.Contains("uninstall") -or $lower.Contains("readme") -or $lower.Contains("help")) { continue }
        $entries.Add([pscustomobject]@{ Name = $lower; AppId = $appId })
    }
    foreach ($candidate in $wanted.ToArray()) {
        foreach ($entry in $entries.ToArray()) {
            if ($entry.Name -eq $candidate) { return $entry.AppId }
        }
    }
    foreach ($candidate in $wanted.ToArray()) {
        if ($candidate.Length -lt 4) { continue }
        foreach ($entry in $entries.ToArray()) {
            if ($entry.Name.StartsWith($candidate + " ") -or $entry.Name.StartsWith($candidate + "-")) { return $entry.AppId }
        }
    }
    return $null
}

$script:WinToolIconPalette = @("#E66000", "#4285F4", "#FB542B", "#EF3939", "#00ACFF", "#FF1B2D", "#5865F2", "#2AABEE", "#1DB954", "#0078D4", "#7B5CD6", "#0F9D58", "#D83B01", "#00A4A6", "#C2185B", "#6D4C41")

function Get-WinToolAppIconColor {
    # A steady color per app id, so the icon tile looks the same every run.
    param(
        [string]$Id
    )
    $hash = 17
    foreach ($character in ([string]$Id).ToCharArray()) {
        $hash = (($hash * 31) + [int]$character) % 1000003
    }
    return $script:WinToolIconPalette[$hash % $script:WinToolIconPalette.Count]
}

function Get-WinToolAppInitial {
    param(
        [string]$Name
    )
    foreach ($character in ([string]$Name).ToCharArray()) {
        if ([char]::IsLetterOrDigit($character)) {
            return ([string]$character).ToUpperInvariant()
        }
    }
    return "?"
}
