function Test-WinToolAdministrator {
    if (-not (Test-WinToolWindows)) {
        return $false
    }
    $identity = [System.Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = New-Object System.Security.Principal.WindowsPrincipal($identity)
    return $principal.IsInRole([System.Security.Principal.WindowsBuiltInRole]::Administrator)
}

function ConvertTo-WinToolLiteral {
    param(
        [AllowEmptyString()][string]$Text
    )
    if ($null -eq $Text) {
        $Text = ""
    }
    return "'" + ($Text.Replace("'", "''")) + "'"
}

function Resolve-WinToolEntryPath {
    param(
        [string]$EntryPath,
        [string]$CommandPath
    )
    if (-not [string]::IsNullOrWhiteSpace($EntryPath)) {
        return $EntryPath
    }
    if (-not [string]::IsNullOrWhiteSpace($CommandPath)) {
        return $CommandPath
    }
    return $null
}

function Get-WinToolPublishedLaunchUrl {
    if (-not [string]::IsNullOrWhiteSpace($env:WINTOOL_URL)) {
        return $env:WINTOOL_URL
    }
    if (-not [string]::IsNullOrWhiteSpace($script:WinToolPublishedUrl)) {
        return $script:WinToolPublishedUrl
    }
    return "https://raw.githubusercontent.com/Hinrikao/WinTool/main/wintool.ps1"
}

function New-WinToolRelaunchScript {
    param(
        [string]$WorkingDirectory,
        [string]$EntryPath,
        [string]$ApplyProfile,
        [bool]$Unattended,
        [string]$LaunchUrl,
        [bool]$Hidden,
        [bool]$ShowConsole
    )
    $lines = New-Object System.Collections.Generic.List[string]
    [void]$lines.Add('$ErrorActionPreference = "Stop"')
    [void]$lines.Add('$env:WINTOOL_PAUSE_ON_ERROR = "1"')
    if ($Hidden) {
        [void]$lines.Add('$env:WINTOOL_HIDDEN = "1"')
    }
    else {
        [void]$lines.Add('$env:WINTOOL_HIDDEN = $null')
    }
    if ($ShowConsole) {
        [void]$lines.Add('$env:WINTOOL_SHOW_CONSOLE = "1"')
    }
    if (-not [string]::IsNullOrWhiteSpace($WorkingDirectory)) {
        [void]$lines.Add("Set-Location -LiteralPath " + (ConvertTo-WinToolLiteral -Text $WorkingDirectory))
    }
    [void]$lines.Add("try {")
    if (-not [string]::IsNullOrWhiteSpace($EntryPath)) {
        $call = "    & " + (ConvertTo-WinToolLiteral -Text $EntryPath)
        if (-not [string]::IsNullOrWhiteSpace($ApplyProfile)) {
            $call += " -ApplyProfile " + (ConvertTo-WinToolLiteral -Text $ApplyProfile)
        }
        if ($Unattended) {
            $call += " -Unattended"
        }
        if ($ShowConsole) {
            $call += " -ShowConsole"
        }
        [void]$lines.Add($call)
    }
    else {
        if ([string]::IsNullOrWhiteSpace($LaunchUrl)) {
            $LaunchUrl = Get-WinToolPublishedLaunchUrl
        }
        $download = "    Invoke-Expression (Invoke-RestMethod -Uri " + (ConvertTo-WinToolLiteral -Text $LaunchUrl) + ")"
        [void]$lines.Add($download)
    }
    [void]$lines.Add("}")
    [void]$lines.Add("catch {")
    [void]$lines.Add('    $text = ($_ | Out-String)')
    if ($Hidden) {
        # Bring the hidden console back so the error and the Enter prompt are visible.
        [void]$lines.Add('    try {')
        [void]$lines.Add('        if ($null -eq ("WinToolConsoleApi" -as [type])) {')
        [void]$lines.Add("            Add-Type -TypeDefinition @'")
        foreach ($sourceLine in ((Get-WinToolConsoleApiSource) -split "`r?`n")) {
            [void]$lines.Add($sourceLine)
        }
        [void]$lines.Add("'@")
        [void]$lines.Add('        }')
        [void]$lines.Add('        $null = [WinToolConsoleApi]::ShowWindow([WinToolConsoleApi]::GetConsoleWindow(), 5)')
        [void]$lines.Add('    }')
        [void]$lines.Add('    catch {')
        [void]$lines.Add('        $null = $_.Exception.Message')
        [void]$lines.Add('    }')
    }
    [void]$lines.Add('    $logDir = Join-Path $env:TEMP "WinTool"')
    [void]$lines.Add('    if (-not (Test-Path -LiteralPath $logDir)) { New-Item -ItemType Directory -Path $logDir -Force | Out-Null }')
    [void]$lines.Add('    $logPath = Join-Path $logDir "wintool.log"')
    [void]$lines.Add('    Add-Content -LiteralPath $logPath -Value ("==== " + (Get-Date).ToString("o") + " ====") -Encoding UTF8')
    [void]$lines.Add('    Add-Content -LiteralPath $logPath -Value $text -Encoding UTF8')
    [void]$lines.Add('    Write-Host $text')
    [void]$lines.Add('    Write-Host ("Log: " + $logPath)')
    [void]$lines.Add("    try {")
    [void]$lines.Add("        Add-Type -AssemblyName PresentationFramework -ErrorAction Stop")
    [void]$lines.Add('        [System.Windows.MessageBox]::Show($text, "WinTool") | Out-Null')
    [void]$lines.Add("    }")
    [void]$lines.Add("    catch {")
    [void]$lines.Add('        Write-Host $_.Exception.Message')
    [void]$lines.Add("    }")
    [void]$lines.Add('    Write-Host "Press Enter to close this window."')
    [void]$lines.Add("    Read-Host | Out-Null")
    [void]$lines.Add("    exit 1")
    [void]$lines.Add("}")
    return ($lines.ToArray() -join "`r`n") + "`r`n"
}

function Get-WinToolHostArgument {
    param(
        [Parameter(Mandatory = $true)][string]$LauncherPath,
        [bool]$Hidden
    )
    $arguments = @("-STA", "-NoProfile", "-ExecutionPolicy", "Bypass")
    if ($Hidden) {
        $arguments += @("-WindowStyle", "Hidden")
    }
    return $arguments + @("-File", $LauncherPath)
}

function Get-WinToolWorkingDirectory {
    try {
        $current = Get-Location
        $path = [string]$current.ProviderPath
        if (-not [string]::IsNullOrWhiteSpace($path) -and (Test-Path -LiteralPath $path -PathType Container)) {
            return $path
        }
    }
    catch {
        $null = $_.Exception.Message
    }
    if (-not [string]::IsNullOrWhiteSpace($env:USERPROFILE) -and (Test-Path -LiteralPath $env:USERPROFILE)) {
        return $env:USERPROFILE
    }
    return [string]$env:SystemRoot
}

function Remove-WinToolStaleTempLauncher {
    param(
        [Parameter(Mandatory = $true)][string]$Directory
    )
    if (-not (Test-Path -LiteralPath $Directory)) {
        return
    }
    $cutoff = [DateTime]::UtcNow.AddHours(-2)
    foreach ($pattern in @("relaunch-*.ps1", "wintool-self-*.ps1")) {
        foreach ($item in @(Get-ChildItem -Path (Join-Path $Directory $pattern) -File -ErrorAction SilentlyContinue)) {
            if ($item.LastWriteTimeUtc -lt $cutoff) {
                Remove-Item -LiteralPath $item.FullName -Force -ErrorAction SilentlyContinue
            }
        }
    }
}

function Start-WinToolRelaunch {
    param(
        [switch]$Elevate
    )
    $executable = Join-Path $env:SystemRoot "System32\WindowsPowerShell\v1.0\powershell.exe"
    $launcherDirectory = Join-Path $env:TEMP "WinTool"
    if (-not (Test-Path -LiteralPath $launcherDirectory)) {
        New-Item -ItemType Directory -Path $launcherDirectory -Force | Out-Null
    }
    Remove-WinToolStaleTempLauncher -Directory $launcherDirectory
    $encoding = New-Object System.Text.UTF8Encoding $true
    $entry = Resolve-WinToolEntryPath -EntryPath $script:WinToolEntryPath -CommandPath ""
    if (-not [string]::IsNullOrWhiteSpace($entry) -and -not (Test-Path -LiteralPath $entry)) {
        $entry = $null
    }
    if ([string]::IsNullOrWhiteSpace($entry) -and -not [string]::IsNullOrWhiteSpace($script:WinToolSelfText)) {
        $selfPath = Join-Path $launcherDirectory ("wintool-self-" + [guid]::NewGuid().ToString("N") + ".ps1")
        [System.IO.File]::WriteAllText($selfPath, $script:WinToolSelfText, $encoding)
        $entry = $selfPath
    }
    $directory = Get-WinToolWorkingDirectory
    $showConsole = Test-WinToolShowConsole
    $hidden = -not ($showConsole -or [bool]$script:WinToolUnattended)
    $scriptText = New-WinToolRelaunchScript -WorkingDirectory $directory -EntryPath $entry -ApplyProfile $script:WinToolApplyProfile -Unattended ([bool]$script:WinToolUnattended) -LaunchUrl (Get-WinToolPublishedLaunchUrl) -Hidden $hidden -ShowConsole $showConsole
    $launcherPath = Join-Path $launcherDirectory ("relaunch-" + [guid]::NewGuid().ToString("N") + ".ps1")
    [System.IO.File]::WriteAllText($launcherPath, $scriptText, $encoding)
    $line = ConvertTo-WinToolArgumentLine -ArgumentList @(Get-WinToolHostArgument -LauncherPath $launcherPath -Hidden $hidden)
    $style = "Normal"
    if ($hidden) {
        $style = "Hidden"
    }
    if ($Elevate) {
        Write-Host "WinTool needs administrator approval. Accept the Windows prompt to continue."
        try {
            Start-Process -FilePath $executable -ArgumentList $line -Verb RunAs -WindowStyle $style | Out-Null
        }
        catch {
            Write-Host "WinTool was not started. Administrator approval was declined."
        }
        Exit-WinToolOwnedHost
        return
    }
    Write-Host "WinTool is opening in its own window. You can close this terminal."
    Start-Process -FilePath $executable -ArgumentList $line -WindowStyle $style | Out-Null
    Exit-WinToolOwnedHost
}

function Test-WinToolOwnedHost {
    # True when this powershell.exe was started by WinTool itself (the hidden
    # relaunch). The user's own console is never closed by WinTool.
    return ($env:WINTOOL_HIDDEN -eq "1")
}

function Exit-WinToolOwnedHost {
    param([int]$Code = 0)
    if (Test-WinToolOwnedHost) {
        [Environment]::Exit($Code)
    }
}

function Request-WinToolAdministrator {
    Start-WinToolRelaunch -Elevate
}

function Request-WinToolStaHost {
    Start-WinToolRelaunch
}
# endregion

# region src/Private/Fixes.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

# Fixes are listed in data/fixes.json. A step is either a program under
# %SystemRoot% with fixed arguments, or one of the named scripts below. The
# catalog cannot carry its own script text.

function Get-WinToolFixCatalog {
    return (ConvertFrom-WinToolJsonText -Text (Get-WinToolPayloadText -Name "Fixes"))
}

function Get-WinToolSystemRoot {
    if (-not [string]::IsNullOrWhiteSpace($env:SystemRoot)) {
        return $env:SystemRoot
    }
    return "C:\Windows"
}

function Get-WinToolSystemFile {
    param(
        [Parameter(Mandatory = $true)][string]$RelativePath
    )
    return ((Get-WinToolSystemRoot).TrimEnd('\') + "\" + $RelativePath.TrimStart('\'))
}

function Get-WinToolFixScriptName {
    return @("windows-update-reset", "winget-repair")
}

function Get-WinToolFixScript {
    param(
        [Parameter(Mandatory = $true)][string]$Name
    )
    switch ($Name) {
        "windows-update-reset" {
            return @'
$ErrorActionPreference = "Continue"
$services = @("wuauserv", "usosvc", "bits", "cryptsvc", "msiserver")
foreach ($name in $services) {
    $service = Get-Service -Name $name -ErrorAction SilentlyContinue
    if ($null -ne $service -and $service.Status -ne "Stopped") {
        Write-Output ("Stopping " + $name)
        Stop-Service -Name $name -Force -ErrorAction SilentlyContinue
    }
}
$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$folders = @(
    (Join-Path $env:SystemRoot "SoftwareDistribution"),
    (Join-Path $env:SystemRoot "System32\catroot2")
)
foreach ($folder in $folders) {
    if (-not (Test-Path -LiteralPath $folder)) {
        continue
    }
    $newName = (Split-Path -Leaf $folder) + ".wintool-" + $stamp
    try {
        Rename-Item -LiteralPath $folder -NewName $newName -ErrorAction Stop
        Write-Output ("Renamed " + $folder + " to " + $newName)
    }
    catch {
        Write-Output ("Could not rename " + $folder + ": " + $_.Exception.Message)
    }
}
foreach ($name in @("cryptsvc", "bits", "wuauserv")) {
    Write-Output ("Starting " + $name)
    Start-Service -Name $name -ErrorAction SilentlyContinue
}
Write-Output "Windows Update components were reset. Restart the PC, then check for updates."
'@
        }
        "winget-repair" {
            return @'
$ErrorActionPreference = "Stop"
[Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
try {
    $nuget = Get-PackageProvider -Name NuGet -ListAvailable -ErrorAction SilentlyContinue
    if ($null -eq $nuget) {
        Write-Output "Installing the NuGet package provider."
        Install-PackageProvider -Name NuGet -MinimumVersion 2.8.5.201 -Force | Out-Null
    }
    $gallery = Get-PSRepository -Name PSGallery -ErrorAction SilentlyContinue
    if ($null -eq $gallery) {
        Register-PSRepository -Default
    }
    Set-PSRepository -Name PSGallery -InstallationPolicy Trusted
    Write-Output "Installing the Microsoft.WinGet.Client module."
    $options = @{ Name = "Microsoft.WinGet.Client"; Scope = "AllUsers"; Repository = "PSGallery"; Force = $true }
    $installer = Get-Command -Name Install-Module
    if ($installer.Parameters.ContainsKey("AllowClobber")) { $options["AllowClobber"] = $true }
    if ($installer.Parameters.ContainsKey("SkipPublisherCheck")) { $options["SkipPublisherCheck"] = $true }
    Install-Module @options
    Import-Module Microsoft.WinGet.Client
    Write-Output "Repairing winget. This downloads App Installer and its dependencies."
    Repair-WinGetPackageManager -AllUsers -Force -Latest
    Write-Output "winget was repaired."
}
catch {
    Write-Output ("The module repair did not work: " + $_.Exception.Message)
    Write-Output "Registering App Installer again from the copy Windows has."
    Add-AppxPackage -RegisterByFamilyName -MainPackage "Microsoft.DesktopAppInstaller_8wekyb3d8bbwe"
    Write-Output "App Installer was registered again. Open a new window and try winget."
}
'@
        }
        default {
            throw "Unknown fix script '$Name'."
        }
    }
}

function Get-WinToolFixPlan {
    param(
        [Parameter(Mandatory = $true)]$Fix
    )
    $steps = New-Object System.Collections.Generic.List[object]
    foreach ($step in @(Get-WinToolNote -Object $Fix -Name "steps" -Default @())) {
        $type = [string](Get-WinToolNote -Object $step -Name "type" -Default "")
        $label = [string](Get-WinToolNote -Object $step -Name "label" -Default ([string]$Fix.name))
        if ($type -eq "process") {
            $steps.Add([pscustomobject]@{
                Type = "process"
                Label = $label
                FilePath = (Get-WinToolSystemFile -RelativePath ([string]$step.file))
                Arguments = @(Get-WinToolNote -Object $step -Name "args" -Default @())
            })
        }
        elseif ($type -eq "script") {
            $steps.Add([pscustomobject]@{
                Type = "fix-script"
                Label = $label
                Script = [string]$step.script
            })
        }
        else {
            throw "Fix '$([string]$Fix.id)' has an unknown step type '$type'."
        }
    }
    return $steps.ToArray()
}

function Test-WinToolFixCatalog {
    param(
        $Catalog,
        $Errors
    )
    if ([int](Get-WinToolNote -Object $Catalog -Name "schemaVersion" -Default 0) -ne 1) {
        $Errors.Add("fixes.json schemaVersion must be 1.")
    }
    $ids = @{}
    $known = Get-WinToolFixScriptName
    foreach ($fix in @(Get-WinToolNote -Object $Catalog -Name "fixes" -Default @())) {
        $id = [string](Get-WinToolNote -Object $fix -Name "id" -Default "")
        if ([string]::IsNullOrWhiteSpace($id) -or $ids.ContainsKey($id)) {
            $Errors.Add("A fix is missing an id or uses one twice: '$id'.")
        }
        $ids[$id] = $true
        foreach ($field in @("name", "description")) {
            if ([string]::IsNullOrWhiteSpace([string](Get-WinToolNote -Object $fix -Name $field -Default ""))) {
                $Errors.Add("Fix '$id' needs a $field.")
            }
        }
        $steps = @(Get-WinToolNote -Object $fix -Name "steps" -Default @())
        if ($steps.Count -eq 0) {
            $Errors.Add("Fix '$id' has no steps.")
        }
        foreach ($step in $steps) {
            $type = [string](Get-WinToolNote -Object $step -Name "type" -Default "")
            if ($type -eq "process") {
                $file = [string](Get-WinToolNote -Object $step -Name "file" -Default "")
                if ($file -notmatch '^System32\\[A-Za-z0-9]+\.exe$') {
                    $Errors.Add("Fix '$id' runs '$file'. Use a program under System32.")
                }
            }
            elseif ($type -eq "script") {
                if ($known -notcontains [string](Get-WinToolNote -Object $step -Name "script" -Default "")) {
                    $Errors.Add("Fix '$id' names a script WinTool does not have.")
                }
            }
            else {
                $Errors.Add("Fix '$id' has an unknown step type '$type'.")
            }
        }
    }
    if ($ids.Count -lt 4) {
        $Errors.Add("fixes.json should list the four built-in fixes.")
    }
}
# endregion

# region src/Private/Features.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

# Optional Windows features from data/features.json. State is read with
# Get-WindowsOptionalFeature in a background runspace; changes go through
# Dism.exe so each one shows its own progress in the log.

$script:WinToolDismRestartCode = 3010

function Get-WinToolFeatureCatalog {
    return (ConvertFrom-WinToolJsonText -Text (Get-WinToolPayloadText -Name "Features"))
}

function Get-WinToolFeatureStateScript {
    $scriptText = @'
param($Sync, $Names)
$ErrorActionPreference = "Stop"
try {
    $states = @{}
    foreach ($name in @($Names)) {
        try {
            $item = Get-WindowsOptionalFeature -Online -FeatureName $name -ErrorAction Stop
            if ($null -eq $item) {
                $states[$name] = "Missing"
            }
            else {
                $states[$name] = [string]$item.State
            }
        }
        catch {
            $states[$name] = "Missing"
        }
    }
    $Sync.States = $states
    $Sync.Ok = $true
}
catch {
    $Sync.Error = $_.Exception.Message
}
finally {
    $Sync.Done = $true
}
'@
    return $scriptText
}

function Get-WinToolFeatureStatus {
    param(
        [Parameter(Mandatory = $true)]$Feature,
        [hashtable]$State
    )
    # A feature counts as on only when every underlying name is enabled.
    $names = @($Feature.names)
    $enabled = 0
    $missing = 0
    foreach ($name in $names) {
        $value = ""
        if ($null -ne $State -and $State.ContainsKey([string]$name)) {
            $value = [string]$State[[string]$name]
        }
        if ($value -eq "Enabled" -or $value -eq "EnablePending") {
            $enabled++
        }
        elseif ($value -eq "Missing" -or [string]::IsNullOrWhiteSpace($value)) {
            $missing++
        }
    }
    if ($missing -gt 0) {
        return "Unavailable"
    }
    if ($enabled -eq $names.Count) {
        return "On"
    }
    if ($enabled -gt 0) {
        return "Partial"
    }
    return "Off"
}

function Get-WinToolFeaturePlan {
    param(
        $Enable,
        $Disable
    )
    $steps = New-Object System.Collections.Generic.List[object]
    $dism = Get-WinToolSystemFile -RelativePath "System32\Dism.exe"
    foreach ($feature in @($Enable)) {
        if ($null -eq $feature) { continue }
        foreach ($name in @($feature.names)) {
            $steps.Add([pscustomobject]@{
                Type = "process"
                Label = ("Turn on {0} ({1})" -f [string]$feature.name, [string]$name)
                FilePath = $dism
                Arguments = @("/Online", "/Enable-Feature", ("/FeatureName:" + [string]$name), "/All", "/NoRestart")
                SuccessCodes = @(0, $script:WinToolDismRestartCode)
            })
        }
    }
    foreach ($feature in @($Disable)) {
        if ($null -eq $feature) { continue }
        $names = @($feature.names)
        # Turn off the parent last, so dependent parts go first.
        [array]::Reverse($names)
        foreach ($name in $names) {
            $steps.Add([pscustomobject]@{
                Type = "process"
                Label = ("Turn off {0} ({1})" -f [string]$feature.name, [string]$name)
                FilePath = $dism
                Arguments = @("/Online", "/Disable-Feature", ("/FeatureName:" + [string]$name), "/NoRestart")
                SuccessCodes = @(0, $script:WinToolDismRestartCode)
            })
        }
    }
    return $steps.ToArray()
}

function Test-WinToolFeatureCatalog {
    param(
        $Catalog,
        $Errors
    )
    if ([int](Get-WinToolNote -Object $Catalog -Name "schemaVersion" -Default 0) -ne 1) {
        $Errors.Add("features.json schemaVersion must be 1.")
    }
    $ids = @{}
    foreach ($feature in @(Get-WinToolNote -Object $Catalog -Name "features" -Default @())) {
        $id = [string](Get-WinToolNote -Object $feature -Name "id" -Default "")
        if ([string]::IsNullOrWhiteSpace($id) -or $ids.ContainsKey($id)) {
            $Errors.Add("A Windows feature is missing an id or uses one twice: '$id'.")
        }
        $ids[$id] = $true
        if ([string]::IsNullOrWhiteSpace([string](Get-WinToolNote -Object $feature -Name "name" -Default "")) -or [string]::IsNullOrWhiteSpace([string](Get-WinToolNote -Object $feature -Name "description" -Default ""))) {
            $Errors.Add("Windows feature '$id' needs a name and description.")
        }
        $names = @(Get-WinToolNote -Object $feature -Name "names" -Default @())
        if ($names.Count -eq 0) {
            $Errors.Add("Windows feature '$id' has no DISM feature names.")
        }
        foreach ($name in $names) {
            if ([string]$name -notmatch '^[A-Za-z0-9][A-Za-z0-9.-]*$') {
                $Errors.Add("Windows feature '$id' has an invalid DISM name '$name'.")
            }
        }
    }
    if ($ids.Count -lt 8) {
        $Errors.Add("features.json should list the common optional features.")
    }
}
# endregion

# region src/Private/Home.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

# Home: a quick local health check. The collectors run in background
# runspaces and return plain data; the ConvertTo-WinToolHome* functions turn
# that data into a result row and are pure, so tests can feed them stubs.

function Get-WinToolHomeCheckList {
    # The fixed order of the checks on the Home page.
    return @(
        [pscustomobject]@{ Id = "junk"; Name = "Junk files" },
        [pscustomobject]@{ Id = "tweaks"; Name = "Recommended tweaks" },
        [pscustomobject]@{ Id = "startup"; Name = "Startup programs" },
        [pscustomobject]@{ Id = "drivers"; Name = "Drivers" },
        [pscustomobject]@{ Id = "disk"; Name = "Disk health" }
    )
}

function Format-WinToolByteSize {
    param([double]$Bytes)
    $culture = [System.Globalization.CultureInfo]::InvariantCulture
    if ($Bytes -ge 1TB) { return ([string]::Format($culture, "{0:0.0} TB", $Bytes / 1TB)) }
    if ($Bytes -ge 100GB) { return ([string]::Format($culture, "{0:0} GB", $Bytes / 1GB)) }
    if ($Bytes -ge 1GB) { return ([string]::Format($culture, "{0:0.0} GB", $Bytes / 1GB)) }
    if ($Bytes -ge 1MB) { return ([string]::Format($culture, "{0:0} MB", $Bytes / 1MB)) }
    if ($Bytes -ge 1KB) { return ([string]::Format($culture, "{0:0} KB", $Bytes / 1KB)) }
    return ("{0:0} bytes" -f $Bytes)
}

function New-WinToolHomeResult {
    param(
        [Parameter(Mandatory = $true)][string]$Id,
        [Parameter(Mandatory = $true)][ValidateSet("ok", "warn", "bad", "unknown")][string]$Status,
        [Parameter(Mandatory = $true)][string]$Text,
        [ValidateSet("fix", "review", "none")][string]$Action = "none",
        [int]$Penalty = 0,
        [string[]]$Detail = @(),
        [double]$Amount = 0
    )
    $name = [string](@(Get-WinToolHomeCheckList | Where-Object { $_.Id -eq $Id })[0].Name)
    return [pscustomobject]@{
        Id = $Id
        Name = $name
        Status = $Status
        Text = $Text
        Action = $Action
        Fixable = ($Action -eq "fix")
        Penalty = $Penalty
        Detail = @($Detail)
        Amount = $Amount
    }
}

function ConvertTo-WinToolHomeErrorResult {
    param(
        [Parameter(Mandatory = $true)][string]$Id,
        [string]$Message
    )
    $text = "Could not check"
    if (-not [string]::IsNullOrWhiteSpace($Message)) {
        $detail = @($Message)
    }
    else {
        $detail = @()
    }
    return (New-WinToolHomeResult -Id $Id -Status "unknown" -Text $text -Detail $detail)
}

function ConvertTo-WinToolHomeJunkResult {
    # Data: one item per location with Name and Bytes (what can be deleted).
    param([object[]]$Data)
    $total = [double]0
    $detail = New-Object System.Collections.Generic.List[string]
    foreach ($item in @($Data)) {
        if ($null -eq $item) { continue }
        $bytes = [double]$item.Bytes
        if ($bytes -lt 0) { $bytes = 0 }
        $total += $bytes
        $detail.Add(("{0}: {1}" -f [string]$item.Name, (Format-WinToolByteSize -Bytes $bytes)))
    }
    if ($total -lt 50MB) {
        return (New-WinToolHomeResult -Id "junk" -Status "ok" -Text "Nothing worth cleaning" -Detail $detail.ToArray() -Amount $total)
    }
    $text = "{0} can be deleted" -f (Format-WinToolByteSize -Bytes $total)
    if ($total -lt 200MB) {
        # Too little to be worth a Fix.
        return (New-WinToolHomeResult -Id "junk" -Status "ok" -Text $text -Detail $detail.ToArray() -Amount $total)
    }
    $status = "warn"
    $penalty = 4
    if ($total -ge 1GB) { $status = "bad"; $penalty = 12 }
    return (New-WinToolHomeResult -Id "junk" -Status $status -Text $text -Action "fix" -Penalty $penalty -Detail $detail.ToArray() -Amount $total)
}

function ConvertTo-WinToolHomeTweakResult {
    # Data: one item per Recommended tweak with Id, Name and State (on/off/unknown).
    param([object[]]$Data)
    $off = @(@($Data) | Where-Object { $null -ne $_ -and [string]$_.State -eq "off" })
    $read = @(@($Data) | Where-Object { $null -ne $_ -and [string]$_.State -ne "unknown" })
    if (@($Data).Count -gt 0 -and $read.Count -eq 0) {
        return (New-WinToolHomeResult -Id "tweaks" -Status "unknown" -Text "Could not read the tweaks")
    }
    $names = @($off | ForEach-Object { [string]$_.Name })
    if ($off.Count -eq 0) {
        return (New-WinToolHomeResult -Id "tweaks" -Status "ok" -Text "All recommended tweaks are on")
    }
    $text = "{0} tweaks not applied yet" -f $off.Count
    if ($off.Count -eq 1) { $text = "1 tweak not applied yet" }
    $penalty = [Math]::Min(16, 2 * $off.Count)
    return (New-WinToolHomeResult -Id "tweaks" -Status "warn" -Text $text -Action "fix" -Penalty $penalty -Detail $names -Amount $off.Count)
}

function Test-WinToolStartupApproved {
    # StartupApproved stores a binary value; an odd first byte (0x03, 0x07)
    # means the user turned the entry off. No value means it is on.
    param($FirstByte)
    if ($null -eq $FirstByte) { return $true }
    $value = [int]$FirstByte
    if ($value -lt 0) { return $true }
    return (($value % 2) -eq 0)
}

function ConvertTo-WinToolHomeStartupResult {
    # Data: one item per Run value or Startup-folder shortcut with Name,
    # Source and Approved (first StartupApproved byte, or -1 when missing).
    param([object[]]$Data)
    $enabled = New-Object System.Collections.Generic.List[string]
    $seen = @{}
    foreach ($item in @($Data)) {
        if ($null -eq $item) { continue }
        $name = [string]$item.Name
        if ([string]::IsNullOrWhiteSpace($name)) { continue }
        if (-not (Test-WinToolStartupApproved -FirstByte $item.Approved)) { continue }
        $key = ([string]$item.Source + "|" + $name).ToLowerInvariant()
        if ($seen.ContainsKey($key)) { continue }
        $seen[$key] = $true
        $enabled.Add(("{0} ({1})" -f $name, [string]$item.Source))
    }
    $count = $enabled.Count
    if ($count -eq 0) {
        return (New-WinToolHomeResult -Id "startup" -Status "ok" -Text "No programs start with Windows")
    }
    $text = "{0} programs start with Windows" -f $count
    if ($count -eq 1) { $text = "1 program starts with Windows" }
    $status = "ok"
    $penalty = 0
    if ($count -gt 8) { $status = "warn"; $penalty = 6 }
    if ($count -gt 12) { $penalty = 10 }
    return (New-WinToolHomeResult -Id "startup" -Status $status -Text $text -Action "review" -Penalty $penalty -Detail $enabled.ToArray() -Amount $count)
}

function Get-WinToolDriverProblemText {
    param([int]$Code)
    switch ($Code) {
        1 { return "not configured" }
        10 { return "cannot start" }
        12 { return "not enough resources" }
        14 { return "restart required" }
        18 { return "reinstall driver" }
        19 { return "registry entry damaged" }
        24 { return "missing or not working" }
        28 { return "driver not installed" }
        31 { return "driver could not load" }
        32 { return "driver service disabled" }
        37 { return "driver failed to initialize" }
        39 { return "driver missing or corrupted" }
        43 { return "reported a problem" }
        48 { return "driver blocked" }
        52 { return "driver signature invalid" }
    }
    if ($Code -gt 0) { return ("code " + $Code) }
    return ""
}

function ConvertTo-WinToolHomeDriverResult {
    # Data: devices that report a problem, with Name, Class, Status and optional Problem code.
    # Devices manually disabled by the user (Problem 22) or disconnected (Problem 45) are ignored.
    param([object[]]$Data)
    $bad = @(@($Data) | Where-Object {
            if ($null -eq $_ -or [string]$_.Status -eq "OK") { return $false }
            $code = -1
            if ($null -ne $_.PSObject.Properties["Problem"] -and $null -ne $_.Problem) { $code = [int]$_.Problem }
            return ($code -ne 22 -and $code -ne 45)
        })
    if ($bad.Count -eq 0) {
        return (New-WinToolHomeResult -Id "drivers" -Status "ok" -Text "No device with problems")
    }
    $detail = @($bad | ForEach-Object {
            $label = [string]$_.Name
            if ([string]::IsNullOrWhiteSpace($label) -and $null -ne $_.PSObject.Properties["InstanceId"]) {
                $label = [string]$_.InstanceId
            }
            if ([string]::IsNullOrWhiteSpace($label)) { $label = "Unknown device" }
            if (-not [string]::IsNullOrWhiteSpace([string]$_.Class)) { $label += " (" + [string]$_.Class + ")" }
            $code = -1
            if ($null -ne $_.PSObject.Properties["Problem"] -and $null -ne $_.Problem) { $code = [int]$_.Problem }
            $reason = Get-WinToolDriverProblemText -Code $code
            if (-not [string]::IsNullOrWhiteSpace($reason)) {
                if ($reason.StartsWith("code ")) { $label += " - " + $reason }
                else { $label += " - {0} (code {1})" -f $reason, $code }
            }
            $label
        })
    $text = "{0} devices have problems" -f $bad.Count
    if ($bad.Count -eq 1) { $text = "1 device has a problem" }
    $penalty = [Math]::Min(20, 10 * $bad.Count)
    return (New-WinToolHomeResult -Id "drivers" -Status "bad" -Text $text -Action "review" -Penalty $penalty -Detail $detail -Amount $bad.Count)
}

function ConvertTo-WinToolHomeDiskResult {
    # Data: one item per physical disk with Name, MediaType and Health.
    param([object[]]$Data)
    $disks = @(@($Data) | Where-Object { $null -ne $_ })
    if ($disks.Count -eq 0) {
        return (New-WinToolHomeResult -Id "disk" -Status "unknown" -Text "No drive reported its health")
    }
    $detail = @($disks | ForEach-Object { "{0}: {1}" -f [string]$_.Name, [string]$_.Health })
    $bad = @($disks | Where-Object { [string]$_.Health -ne "Healthy" })
    if ($bad.Count -eq 0) {
        $text = "All drives report healthy"
        if ($disks.Count -eq 1) { $text = "The drive reports healthy" }
        return (New-WinToolHomeResult -Id "disk" -Status "ok" -Text $text -Detail $detail)
    }
    $text = "{0} drives need attention" -f $bad.Count
    if ($bad.Count -eq 1) { $text = "{0} reports {1}" -f [string]$bad[0].Name, ([string]$bad[0].Health).ToLowerInvariant() }
    return (New-WinToolHomeResult -Id "disk" -Status "bad" -Text $text -Action "review" -Penalty 30 -Detail $detail -Amount $bad.Count)
}

function ConvertTo-WinToolHomeResult {
    # Turns one finished check into its row. A failed check shows "Could not check".
    param(
        [Parameter(Mandatory = $true)][string]$Id,
        $Data,
        [string]$ErrorMessage
    )
    if (-not [string]::IsNullOrWhiteSpace($ErrorMessage)) {
        return (ConvertTo-WinToolHomeErrorResult -Id $Id -Message $ErrorMessage)
    }
    try {
        switch ($Id) {
            "junk" { return (ConvertTo-WinToolHomeJunkResult -Data @($Data)) }
            "tweaks" { return (ConvertTo-WinToolHomeTweakResult -Data @($Data)) }
            "startup" { return (ConvertTo-WinToolHomeStartupResult -Data @($Data)) }
            "drivers" { return (ConvertTo-WinToolHomeDriverResult -Data @($Data)) }
            "disk" { return (ConvertTo-WinToolHomeDiskResult -Data @($Data)) }
        }
    }
    catch {
        return (ConvertTo-WinToolHomeErrorResult -Id $Id -Message $_.Exception.Message)
    }
    throw "Unknown Home check: $Id"
}

function Get-WinToolHomeScore {
    param([object[]]$Result)
    $score = 100
    foreach ($item in @($Result)) {
        if ($null -ne $item) { $score -= [int]$item.Penalty }
    }
    return [Math]::Max(0, [Math]::Min(100, $score))
}

function Get-WinToolHomeVerdict {
    param([int]$Score)
    if ($Score -ge 90) { return [pscustomobject]@{ Text = "Healthy"; Tone = "ok" } }
    if ($Score -ge 60) { return [pscustomobject]@{ Text = "Needs attention"; Tone = "warn" } }
    return [pscustomobject]@{ Text = "Needs care"; Tone = "bad" }
}

function Get-WinToolHomeLead {
    param([object[]]$Result)
    $fixable = @(@($Result) | Where-Object { $null -ne $_ -and $_.Fixable }).Count
    $words = @("No", "One", "Two", "Three", "Four", "Five")
    if ($fixable -eq 0) {
        return "Nothing needs fixing. Nothing was changed during the analysis."
    }
    $word = [string]$fixable
    if ($fixable -lt $words.Count) { $word = $words[$fixable] }
    $noun = "items"
    if ($fixable -eq 1) { $noun = "item" }
    return ("{0} {1} can be fixed. Nothing was changed during the analysis." -f $word, $noun)
}

function Format-WinToolHomeWhen {
    param(
        [Parameter(Mandatory = $true)][datetime]$Time,
        [datetime]$Now = (Get-Date)
    )
    $clock = $Time.ToString("HH:mm", [System.Globalization.CultureInfo]::InvariantCulture)
    if ($Time.Date -eq $Now.Date) { return ("today " + $clock) }
    if ($Time.Date -eq $Now.Date.AddDays(-1)) { return ("yesterday " + $clock) }
    return ($Time.ToString("MMM d", [System.Globalization.CultureInfo]::InvariantCulture) + " " + $clock)
}

function Format-WinToolHomeMeta {
    param(
        $Last,
        [datetime]$Now = (Get-Date)
    )
    if ($null -eq $Last) {
        return "No earlier analysis on this PC"
    }
    $when = Format-WinToolHomeWhen -Time ([datetime]$Last.Time) -Now $Now
    return ("Last analysis: {0} {2} Score {1}" -f $when, [int]$Last.Score, [char]0x00B7)
}

function Get-WinToolMemoryTypeName {
    # SMBIOS memory type codes from Win32_PhysicalMemory.
    param([int]$Code)
    switch ($Code) {
        20 { return "DDR" }
        21 { return "DDR2" }
        24 { return "DDR3" }
        26 { return "DDR4" }
        27 { return "LPDDR" }
        28 { return "LPDDR2" }
        29 { return "LPDDR3" }
        30 { return "LPDDR4" }
        34 { return "DDR5" }
        35 { return "LPDDR5" }
    }
    return ""
}

function Format-WinToolCpuName {
    param([string]$Name)
    $text = [string]$Name
    $text = $text -replace '\((R|TM|tm|r)\)', '' -replace '\s+CPU\s+@.*$', '' -replace '\s+\d+-Core Processor.*$', '' -replace '\s+with Radeon.*$', '' -replace '\s+Processor$', ''
    return (($text -replace '\s+', ' ').Trim())
}

function Get-WinToolHomeDiskTone {
    param([double]$FreePercent)
    if ($FreePercent -lt 15) { return "bad" }
    if ($FreePercent -lt 30) { return "warn" }
    return "ok"
}

function Get-WinToolHomeHistoryPath {
    $base = $env:LOCALAPPDATA
    if ([string]::IsNullOrWhiteSpace($base)) { $base = [System.IO.Path]::GetTempPath() }
    return (Join-Path $base "WinTool\home-history.json")
}

function Read-WinToolHomeHistory {
    param([string]$Path = (Get-WinToolHomeHistoryPath))
    if (-not (Test-Path -LiteralPath $Path)) { return @() }
    try {
        $items = @((Get-Content -LiteralPath $Path -Raw -ErrorAction Stop) | ConvertFrom-Json)
        $list = foreach ($item in $items) {
            if ($null -eq $item) { continue }
            [pscustomobject]@{
                Time = [datetime]::Parse([string]$item.Time, [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::RoundtripKind)
                Score = [int]$item.Score
                Seconds = [int]$item.Seconds
            }
        }
        return @($list)
    }
    catch {
        return @()
    }
}

function Write-WinToolHomeHistoryList {
    param(
        [object[]]$Item,
        [string]$Path = (Get-WinToolHomeHistoryPath)
    )
    $keep = @(@($Item) | Select-Object -Last 20 | ForEach-Object {
            [pscustomobject]@{ Time = ([datetime]$_.Time).ToString("o"); Score = [int]$_.Score; Seconds = [int]$_.Seconds }
        })
    try {
        $folder = Split-Path -Parent $Path
        if (-not (Test-Path -LiteralPath $folder)) { New-Item -ItemType Directory -Path $folder -Force | Out-Null }
        [System.IO.File]::WriteAllText($Path, (ConvertTo-Json -InputObject $keep -Depth 3))
    }
    catch {
        $null = $_.Exception.Message
    }
}

function Add-WinToolHomeHistory {
    # Keeps the last 20 analyses in %LOCALAPPDATA%\WinTool\home-history.json.
    param(
        [Parameter(Mandatory = $true)][datetime]$Time,
        [Parameter(Mandatory = $true)][int]$Score,
        [int]$Seconds,
        [string]$Path = (Get-WinToolHomeHistoryPath)
    )
    $items = New-Object System.Collections.Generic.List[object]
    foreach ($item in @(Read-WinToolHomeHistory -Path $Path)) { $items.Add($item) }
    $items.Add([pscustomobject]@{ Time = $Time; Score = $Score; Seconds = $Seconds })
    Write-WinToolHomeHistoryList -Item $items.ToArray() -Path $Path
}

function Set-WinToolHomeLatestHistory {
    # Updates the latest saved analysis score after a Home fix completes, so
    # the ring, the meta line and the history dialog stay consistent.
    param(
        [Parameter(Mandatory = $true)][int]$Score,
        [string]$Path = (Get-WinToolHomeHistoryPath)
    )
    $items = @(Read-WinToolHomeHistory -Path $Path)
    if ($items.Count -eq 0) { return }
    $items[-1].Score = $Score
    Write-WinToolHomeHistoryList -Item $items -Path $Path
}

function Get-WinToolHomeJunkLocation {
    # The places the junk check measures and the Fix cleans. Temp folders keep
    # anything touched in the last day, so running programs are left alone.
    $windows = $env:SystemRoot
    if ([string]::IsNullOrWhiteSpace($windows)) { $windows = "C:\Windows" }
    $list = New-Object System.Collections.Generic.List[object]
    if (-not [string]::IsNullOrWhiteSpace($env:TEMP)) {
        $list.Add([pscustomobject]@{ Id = "temp"; Name = "Your temporary files"; Path = $env:TEMP; Filter = "*"; Recurse = $true; MinAgeHours = 24 })
    }
    $list.Add([pscustomobject]@{ Id = "wintemp"; Name = "Windows temporary files"; Path = (Join-Path $windows "Temp"); Filter = "*"; Recurse = $true; MinAgeHours = 24 })
    $list.Add([pscustomobject]@{ Id = "delivery"; Name = "Delivery Optimization cache"; Path = (Join-Path $windows "ServiceProfiles\NetworkService\AppData\Local\Microsoft\Windows\DeliveryOptimization\Cache"); Filter = "*"; Recurse = $true; MinAgeHours = 0 })
    $list.Add([pscustomobject]@{ Id = "recycle"; Name = "Recycle Bin"; Path = ""; Filter = "*"; Recurse = $true; MinAgeHours = 0 })
    if (-not [string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
        $list.Add([pscustomobject]@{ Id = "thumbs"; Name = "Thumbnail cache"; Path = (Join-Path $env:LOCALAPPDATA "Microsoft\Windows\Explorer"); Filter = "thumbcache_*.db"; Recurse = $false; MinAgeHours = 0 })
    }
    return $list.ToArray()
}

function Get-WinToolHomeCheckScript {
    # The runspace script for one check. Each script gets the shared sync
    # hashtable first, sets Data or Error, and always sets Done.
    param([Parameter(Mandatory = $true)][string]$Id)
    $common = @'
function Test-HomeReparsePoint {
    param($Item)
    if ($null -eq $Item) { return $false }
    try { return (($Item.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) } catch { return $true }
}

function Test-HomeFileDeletable {
    param($File)
    if ($null -eq $File) { return $false }
    if (Test-HomeReparsePoint -Item $File) { return $false }
    try {
        $access = [System.IO.FileAccess]::ReadWrite
        if (($File.Attributes -band [System.IO.FileAttributes]::ReadOnly) -ne 0) {
            $access = [System.IO.FileAccess]::Read
        }
        $stream = [System.IO.File]::Open($File.FullName, [System.IO.FileMode]::Open, $access, [System.IO.FileShare]::None)
        $stream.Dispose()
        return $true
    }
    catch {
        return $false
    }
}

function Get-HomeJunkFile {
    param($Location)
    $roots = @()
    if ($Location.Id -eq "recycle") {
        $sid = $null
        try { $sid = [System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value } catch { $sid = $null }
        foreach ($drive in [System.IO.DriveInfo]::GetDrives()) {
            if ($drive.DriveType -eq "Fixed" -and $drive.IsReady) {
                $bin = Join-Path $drive.RootDirectory.FullName '$Recycle.Bin'
                if (-not [string]::IsNullOrWhiteSpace($sid)) {
                    $userBin = Join-Path $bin $sid
                    if (Test-Path -LiteralPath $userBin) { $roots += $userBin }
                }
                elseif (Test-Path -LiteralPath $bin) {
                    $roots += $bin
                }
            }
        }
    }
    elseif (-not [string]::IsNullOrWhiteSpace([string]$Location.Path)) {
        $roots += [string]$Location.Path
    }
    $cutoff = (Get-Date).AddHours(-1 * [double]$Location.MinAgeHours)
    $filter = [string]$Location.Filter
    if ([string]::IsNullOrWhiteSpace($filter)) { $filter = "*" }
    foreach ($root in $roots) {
        if (-not (Test-Path -LiteralPath $root)) { continue }
        $stack = New-Object System.Collections.Generic.Stack[string]
        $stack.Push($root)
        while ($stack.Count -gt 0) {
            $current = $stack.Pop()
            foreach ($file in @(Get-ChildItem -LiteralPath $current -Filter $filter -Force -File -ErrorAction SilentlyContinue)) {
                if (Test-HomeReparsePoint -Item $file) { continue }
                if ($file.Name -eq "desktop.ini") { continue }
                if ($Location.MinAgeHours -gt 0 -and $file.LastWriteTime -gt $cutoff) { continue }
                if (-not (Test-HomeFileDeletable -File $file)) { continue }
                $file
            }
            if ($Location.Recurse) {
                foreach ($dir in @(Get-ChildItem -LiteralPath $current -Force -Directory -ErrorAction SilentlyContinue)) {
                    if (Test-HomeReparsePoint -Item $dir) { continue }
                    $stack.Push($dir.FullName)
                }
            }
        }
    }
}
'@
    $body = switch ($Id) {
        "junk" {
            @'
param($sync, $locations)
try {
    $list = foreach ($location in @($locations)) {
        $sum = [double]0
        foreach ($file in @(Get-HomeJunkFile -Location $location)) { $sum += [double]$file.Length }
        [pscustomobject]@{ Id = [string]$location.Id; Name = [string]$location.Name; Bytes = $sum }
    }
    $sync.Data = @($list)
    $sync.Ok = $true
}
catch { $sync.Error = $_.Exception.Message }
finally { $sync.Done = $true }
'@
        }
        "clean" {
            @'
param($sync, $locations)
try {
    $freed = [double]0
    foreach ($location in @($locations)) {
        if ($location.Id -eq "recycle") {
            $before = [double]0
            $files = @(Get-HomeJunkFile -Location $location)
            foreach ($file in $files) { $before += [double]$file.Length }
            try { Clear-RecycleBin -Force -ErrorAction Stop } catch { $null = $_ }
            foreach ($file in @(Get-HomeJunkFile -Location $location)) {
                try { Remove-Item -LiteralPath $file.FullName -Force -ErrorAction Stop } catch { $null = $_ }
            }
            $after = [double]0
            foreach ($file in @(Get-HomeJunkFile -Location $location)) { $after += [double]$file.Length }
            if ($before -gt $after) { $freed += ($before - $after) }
            continue
        }
        if ($location.Id -eq "delivery") {
            $before = [double]0
            foreach ($file in @(Get-HomeJunkFile -Location $location)) { $before += [double]$file.Length }
            if ($null -ne (Get-Command -Name Delete-DeliveryOptimizationCache -ErrorAction SilentlyContinue)) {
                try { Delete-DeliveryOptimizationCache -Force -ErrorAction Stop } catch { $null = $_ }
            }
            foreach ($file in @(Get-HomeJunkFile -Location $location)) {
                try { Remove-Item -LiteralPath $file.FullName -Force -ErrorAction Stop } catch { $null = $_ }
            }
            $after = [double]0
            foreach ($file in @(Get-HomeJunkFile -Location $location)) { $after += [double]$file.Length }
            if ($before -gt $after) { $freed += ($before - $after) }
            continue
        }
        foreach ($file in @(Get-HomeJunkFile -Location $location)) {
            $size = [double]$file.Length
            try {
                Remove-Item -LiteralPath $file.FullName -Force -ErrorAction Stop
                if (-not (Test-Path -LiteralPath $file.FullName)) { $freed += $size }
            }
            catch { $null = $_ }
        }
        if ($location.Recurse -and $location.MinAgeHours -gt 0 -and (Test-Path -LiteralPath $location.Path)) {
            # Empty non-reparse folders left behind in the temp folders.
            $visited = New-Object System.Collections.Generic.List[System.IO.DirectoryInfo]
            $dirStack = New-Object System.Collections.Generic.Stack[string]
            $dirStack.Push([string]$location.Path)
            while ($dirStack.Count -gt 0) {
                $currentDir = $dirStack.Pop()
                foreach ($sub in @(Get-ChildItem -LiteralPath $currentDir -Force -Directory -ErrorAction SilentlyContinue)) {
                    if (Test-HomeReparsePoint -Item $sub) { continue }
                    $visited.Add($sub)
                    $dirStack.Push($sub.FullName)
                }
            }
            foreach ($folder in @($visited.ToArray() | Sort-Object { $_.FullName.Length } -Descending)) {
                try {
                    if (@(Get-ChildItem -LiteralPath $folder.FullName -Force -ErrorAction Stop).Count -eq 0) {
                        Remove-Item -LiteralPath $folder.FullName -Force -ErrorAction Stop
                    }
                }
                catch { $null = $_ }
            }
        }
    }
    $sync.Data = $freed
    $sync.Ok = $true
}
catch { $sync.Error = $_.Exception.Message }
finally { $sync.Done = $true }
'@
        }
        "tweaks" {
            @'
param($sync, $tweaks)
try {
    $probe = Get-WinToolTweakProbe
    $list = foreach ($tweak in @($tweaks)) {
        $state = "unknown"
        try { $state = Get-WinToolTweakState -Tweak $tweak -Probe $probe } catch { $state = "unknown" }
        [pscustomobject]@{ Id = [string]$tweak.id; Name = [string]$tweak.name; State = [string]$state }
    }
    $sync.Data = @($list)
    $sync.Ok = $true
}
catch { $sync.Error = $_.Exception.Message }
finally { $sync.Done = $true }
'@
        }
        "startup" {
            @'
param($sync)
try {
    $approvedRoot = "\Software\Microsoft\Windows\CurrentVersion\Explorer\StartupApproved\"
    function Get-Approved($hive, $kind, $name) {
        $path = $hive + ":" + $approvedRoot + $kind
        try {
            $value = (Get-ItemProperty -LiteralPath $path -Name $name -ErrorAction Stop).$name
            if ($value -is [byte[]] -and $value.Length -gt 0) { return [int]$value[0] }
        } catch { $null = $_ }
        return -1
    }
    $list = New-Object System.Collections.Generic.List[object]
    $runKeys = @(
        @{ Hive = "HKCU"; Path = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Run"; Kind = "Run"; Source = "Run, this user" },
        @{ Hive = "HKLM"; Path = "HKLM:\Software\Microsoft\Windows\CurrentVersion\Run"; Kind = "Run"; Source = "Run, all users" },
        @{ Hive = "HKLM"; Path = "HKLM:\Software\WOW6432Node\Microsoft\Windows\CurrentVersion\Run"; Kind = "Run32"; Source = "Run, all users (32-bit)" }
    )
    foreach ($key in $runKeys) {
        if (-not (Test-Path -LiteralPath $key.Path)) { continue }
        $item = Get-Item -LiteralPath $key.Path -ErrorAction SilentlyContinue
        if ($null -eq $item) { continue }
        foreach ($name in @($item.GetValueNames())) {
            if ([string]::IsNullOrWhiteSpace($name)) { continue }
            $list.Add([pscustomobject]@{ Name = $name; Source = $key.Source; Approved = (Get-Approved $key.Hive $key.Kind $name) })
        }
    }
    $folders = @(
        @{ Hive = "HKCU"; Path = [Environment]::GetFolderPath("Startup"); Source = "Startup folder" },
        @{ Hive = "HKLM"; Path = [Environment]::GetFolderPath("CommonStartup"); Source = "Startup folder, all users" }
    )
    foreach ($folder in $folders) {
        if ([string]::IsNullOrWhiteSpace($folder.Path) -or -not (Test-Path -LiteralPath $folder.Path)) { continue }
        foreach ($file in @(Get-ChildItem -LiteralPath $folder.Path -File -Force -ErrorAction SilentlyContinue)) {
            if ($file.Name -eq "desktop.ini") { continue }
            $list.Add([pscustomobject]@{ Name = [System.IO.Path]::GetFileNameWithoutExtension($file.Name); Source = $folder.Source; Approved = (Get-Approved $folder.Hive "StartupFolder" $file.Name) })
        }
    }
    $sync.Data = $list.ToArray()
    $sync.Ok = $true
}
catch { $sync.Error = $_.Exception.Message }
finally { $sync.Done = $true }
'@
        }
        "drivers" {
            @'
param($sync)
try {
    $list = @()
    $queried = $false
    try {
        $entities = @(Get-CimInstance -ClassName Win32_PnPEntity -Filter "ConfigManagerErrorCode <> 0 AND ConfigManagerErrorCode <> 22 AND ConfigManagerErrorCode <> 45" -ErrorAction Stop)
        $queried = $true
        $list = @($entities | ForEach-Object {
                $devName = [string]$_.Name
                if ([string]::IsNullOrWhiteSpace($devName)) { $devName = [string]$_.Caption }
                if ([string]::IsNullOrWhiteSpace($devName)) { $devName = [string]$_.DeviceID }
                [pscustomobject]@{
                    Name = $devName
                    Class = [string]$_.PNPClass
                    Status = "Error"
                    Problem = [int]$_.ConfigManagerErrorCode
                    InstanceId = [string]$_.DeviceID
                }
            })
    }
    catch {
        $queried = $false
    }
    if (-not $queried -and $null -ne (Get-Command -Name Get-PnpDevice -ErrorAction SilentlyContinue)) {
        $list = @(Get-PnpDevice -PresentOnly -ErrorAction Stop | Where-Object { [string]$_.Status -eq "Error" -or [string]$_.Status -eq "Degraded" } | ForEach-Object {
                $devName = [string]$_.FriendlyName
                if ([string]::IsNullOrWhiteSpace($devName)) { $devName = [string]$_.Name }
                if ([string]::IsNullOrWhiteSpace($devName)) { $devName = [string]$_.InstanceId }
                $prob = -1
                if ($null -ne $_.PSObject.Properties["Problem"] -and $null -ne $_.Problem) { $prob = [int]$_.Problem }
                [pscustomobject]@{
                    Name = $devName
                    Class = [string]$_.Class
                    Status = [string]$_.Status
                    Problem = $prob
                    InstanceId = [string]$_.InstanceId
                }
            } | Where-Object { $_.Problem -ne 22 -and $_.Problem -ne 45 })
    }
    $sync.Data = @($list)
    $sync.Ok = $true
}
catch { $sync.Error = $_.Exception.Message }
finally { $sync.Done = $true }
'@
        }
        "disk" {
            @'
param($sync)
try {
    $list = @(Get-PhysicalDisk -ErrorAction Stop | ForEach-Object {
            [pscustomobject]@{ Name = [string]$_.FriendlyName; MediaType = [string]$_.MediaType; Health = [string]$_.HealthStatus }
        })
    $sync.Data = @($list)
    $sync.Ok = $true
}
catch { $sync.Error = $_.Exception.Message }
finally { $sync.Done = $true }
'@
        }
        "info" {
            @'
param($sync)
$info = @{ Os = ""; Version = ""; Cpu = ""; MemoryTotal = [double]0; MemoryType = 0; DiskSize = [double]0; DiskMedia = "" }
try {
    try {
        $os = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop
        $info.Os = ([string]$os.Caption -replace '^Microsoft\s+', '').Trim()
        $info.MemoryTotal = [double]$os.TotalVisibleMemorySize * 1KB
    } catch { $null = $_ }
    try { $info.Version = [string](Get-ItemProperty -LiteralPath "HKLM:\Software\Microsoft\Windows NT\CurrentVersion" -ErrorAction Stop).DisplayVersion } catch { $null = $_ }
    try { $info.Cpu = [string](@(Get-CimInstance -ClassName Win32_Processor -ErrorAction Stop)[0].Name) } catch { $null = $_ }
    try {
        $modules = @(Get-CimInstance -ClassName Win32_PhysicalMemory -ErrorAction Stop)
        $total = [double]0
        foreach ($module in $modules) { $total += [double]$module.Capacity }
        if ($total -gt 0) { $info.MemoryTotal = $total }
        if ($modules.Count -gt 0) { $info.MemoryType = [int]$modules[0].SMBIOSMemoryType }
    } catch { $null = $_ }
    try {
        $letter = ([string]$env:SystemDrive).TrimEnd(':')
        $info.DiskSize = [double](New-Object System.IO.DriveInfo($letter)).TotalSize
        $number = (Get-Partition -DriveLetter $letter -ErrorAction Stop | Select-Object -First 1).DiskNumber
        $physical = @(Get-PhysicalDisk -ErrorAction Stop | Where-Object { [string]$_.DeviceId -eq [string]$number })
        if ($physical.Count -gt 0) {
            $info.DiskMedia = [string]$physical[0].MediaType
            $info.DiskSize = [double]$physical[0].Size
        }
    } catch { $null = $_ }
    $sync.Data = [pscustomobject]$info
    $sync.Ok = $true
}
catch { $sync.Error = $_.Exception.Message }
finally { $sync.Done = $true }
'@
        }
        "sampler" {
            @'
param($sync)
# Samples memory, the Windows drive and processor load for the Home cards.
$letter = ([string]$env:SystemDrive).TrimEnd(':')
while (-not $sync.Stop) {
    if (-not $sync.Paused) {
        $sample = @{ Time = Get-Date; MemoryUsed = -1.0; MemoryTotal = -1.0; DiskFree = -1.0; DiskTotal = -1.0; DiskBusy = -1.0; Cpu = -1.0 }
        try {
            $os = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop
            $sample.MemoryTotal = [double]$os.TotalVisibleMemorySize * 1KB
            $sample.MemoryUsed = ([double]$os.TotalVisibleMemorySize - [double]$os.FreePhysicalMemory) * 1KB
        } catch { $null = $_ }
        try {
            $drive = New-Object System.IO.DriveInfo($letter)
            $sample.DiskFree = [double]$drive.AvailableFreeSpace
            $sample.DiskTotal = [double]$drive.TotalSize
        } catch { $null = $_ }
        try { $sample.DiskBusy = [Math]::Min(100.0, [double](Get-CimInstance -ClassName Win32_PerfFormattedData_PerfDisk_PhysicalDisk -Filter "Name='_Total'" -ErrorAction Stop).PercentDiskTime) } catch { $null = $_ }
        try { $sample.Cpu = [double](Get-CimInstance -ClassName Win32_PerfFormattedData_PerfOS_Processor -Filter "Name='_Total'" -ErrorAction Stop).PercentProcessorTime } catch { $null = $_ }
        $sync.Queue.Enqueue([pscustomobject]$sample)
    }
    Start-Sleep -Milliseconds 2500
}
$sync.Done = $true
'@
        }
        default { throw "Unknown Home check: $Id" }
    }
    # param() has to stay first; the shared helper goes right after it.
    $text = ([string]$body).Trim()
    $split = $text.IndexOf("`n")
    return ($text.Substring(0, $split).TrimEnd() + "`n" + $common + "`n" + $text.Substring($split + 1))
}

function Start-WinToolHomeJob {
    # A background runspace for one check. With -WithWinTool the runspace gets
    # the WinTool functions, so the tweak check reads state the same way as
    # the Tweaks page.
    param(
        [Parameter(Mandatory = $true)][string]$ScriptText,
        [object[]]$Argument,
        [switch]$WithWinTool
    )
    $sync = [hashtable]::Synchronized(@{
            Done = $false
            Ok = $false
            Error = $null
            Data = $null
            Stop = $false
            Paused = $false
            Queue = (New-Object System.Collections.Concurrent.ConcurrentQueue[object])
        })
    $state = [System.Management.Automation.Runspaces.InitialSessionState]::CreateDefault()
    if ($WithWinTool) {
        foreach ($function in @(Get-ChildItem -Path Function:\ | Where-Object { $_.Name -like "*-WinTool*" })) {
            $entry = New-Object System.Management.Automation.Runspaces.SessionStateFunctionEntry -ArgumentList $function.Name, $function.Definition
            $state.Commands.Add($entry)
        }
    }
    $runspace = [runspacefactory]::CreateRunspace($state)
    $runspace.ApartmentState = "STA"
    $runspace.Open()
    $powershell = [powershell]::Create()
    $powershell.Runspace = $runspace
    [void]$powershell.AddScript($ScriptText)
    [void]$powershell.AddArgument($sync)
    foreach ($item in @($Argument)) {
        [void]$powershell.AddArgument($item)
    }
    [void]$powershell.BeginInvoke()
    return [pscustomobject]@{
        PowerShell = $powershell
        Handle = $null
        Sync = $sync
        Runspace = $runspace
    }
}
# endregion

