function Get-WinToolActiveFont {
    $rows = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    foreach ($item in @(Get-WinToolNote -Object (Get-WinToolFontDocument) -Name "fonts" -Default @())) {
        $rows.Add($item)
        $seen[[string]$item.id] = $true
    }
    foreach ($item in @($script:WinToolExtraFont)) {
        if (-not $seen.ContainsKey([string]$item.id)) {
            $rows.Add($item)
        }
    }
    return $rows.ToArray()
}

function Get-WinToolActiveOhMyPoshTheme {
    $rows = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    foreach ($item in @(Get-WinToolNote -Object (Get-WinToolOhMyPoshDocument) -Name "themes" -Default @())) {
        $rows.Add($item)
        $seen[[string]$item.id] = $true
    }
    foreach ($item in @($script:WinToolExtraOhMyPoshTheme)) {
        if (-not $seen.ContainsKey([string]$item.id)) {
            $rows.Add($item)
        }
    }
    return $rows.ToArray()
}

function Build-WinToolSimpleTerminalCard {
    $hostPanel = Get-WinToolUi -Name "TerminalSimpleHost"
    $hostPanel.Children.Clear()
    $card = New-WinToolCard
    $stack = New-Object System.Windows.Controls.StackPanel
    [void]$stack.Children.Add((New-WinToolText -Text "Recommended setup" -Weight "Bold"))
    [void]$stack.Children.Add((New-WinToolText -Text "Windows Terminal, PowerShell 7, Oh My Posh with the Jan De Dobbeleer theme, a Nerd Font, file icons, and history suggestions. You can change any of this in Advanced." -Brush "BrushMuted" -Wrap -Margin ([System.Windows.Thickness]::new(0, 6, 0, 8))))
    [void]$stack.Children.Add((New-WinToolTerminalPreview -Segments @(
        [pscustomobject]@{ text = "~/src "; color = "#6C9BFF" },
        [pscustomobject]@{ text = "main "; color = "#3DDC97" },
        [pscustomobject]@{ text = ">"; color = "#E8EDF7" }
    )))
    $card.Child = $stack
    [void]$hostPanel.Children.Add($card)
}

function New-WinToolTerminalTile {
    $tile = New-Object System.Windows.Controls.Border
    $tile.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, "BrushNavHover")
    $tile.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, "BrushLine")
    $tile.BorderThickness = [System.Windows.Thickness]::new(1)
    $tile.CornerRadius = [System.Windows.CornerRadius]::new(8)
    $tile.Padding = [System.Windows.Thickness]::new(9, 0, 9, 0)
    $tile.Margin = [System.Windows.Thickness]::new(0, 0, 8, 6)
    $tile.Cursor = [System.Windows.Input.Cursors]::Hand
    return $tile
}

function Set-WinToolTerminalChoiceValue {
    param(
        [Parameter(Mandatory = $true)][string]$Name,
        $Value
    )
    if ($null -eq $script:WinToolTerminalChoice) {
        $script:WinToolTerminalChoice = Get-WinToolSimpleTerminalChoice
    }
    $script:WinToolTerminalChoice.$Name = $Value
}

function Update-WinToolSchemeSelection {
    $selected = [string]$script:WinToolTerminalChoice.schemeId
    $hostPanel = Get-WinToolUi -Name "TerminalSchemeHost"
    for ($index = 0; $index -lt $hostPanel.Children.Count; $index++) {
        $card = $hostPanel.Children[$index]
        if ([string]$card.Tag -eq $selected) {
            $card.BorderThickness = [System.Windows.Thickness]::new(2)
            $card.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, "BrushAccent")
        }
        else {
            $card.BorderThickness = [System.Windows.Thickness]::new(1)
            $card.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, "BrushLine")
        }
    }
}

function Update-WinToolFontSample {
    $list = Get-WinToolUi -Name "TerminalFontList"
    if ($null -ne $list.SelectedItem) {
        $script:WinToolTerminalChoice.fontId = [string]$list.SelectedItem.Tag
    }
    Update-WinToolTerminalPreview
}

function Find-WinToolChildScrollViewer {
    param(
        $Element
    )
    if ($null -eq $Element) {
        return $null
    }
    $count = [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($Element)
    for ($index = 0; $index -lt $count; $index++) {
        $child = [System.Windows.Media.VisualTreeHelper]::GetChild($Element, $index)
        if ($child -is [System.Windows.Controls.ScrollViewer]) {
            return $child
        }
        $found = Find-WinToolChildScrollViewer -Element $child
        if ($null -ne $found) {
            return $found
        }
    }
    return $null
}

function ConvertTo-WinToolPreviewBrush {
    param(
        [string]$Color
    )
    if ([string]::IsNullOrWhiteSpace($Color)) {
        return $null
    }
    try {
        $value = [System.Windows.Media.Color]([System.Windows.Media.ColorConverter]::ConvertFromString($Color))
        $brush = [System.Windows.Media.SolidColorBrush]::new($value)
        $brush.Freeze()
        return $brush
    }
    catch {
        return $null
    }
}

function Get-WinToolPreviewTheme {
    # Returns the Oh My Posh theme JSON from memory or disk; when it is not
    # there yet, starts one background download and returns $null.
    param(
        [string]$ThemeId
    )
    $file = Get-WinToolOmpThemeFileName -ThemeId $ThemeId -Themes @(Get-WinToolActiveOhMyPoshTheme)
    $theme = Read-WinToolCachedOmpTheme -File $file
    if ($null -ne $theme) {
        return $theme
    }
    if ($null -eq $script:WinToolOmpPreviewFailed) {
        $script:WinToolOmpPreviewFailed = @{}
    }
    if ($script:WinToolOmpPreviewFailed.ContainsKey($file) -or $null -ne $script:WinToolState.PreviewJob) {
        return $null
    }
    if ([string]::IsNullOrWhiteSpace($env:LOCALAPPDATA) -or $file -notmatch '^[A-Za-z0-9._-]+$') {
        $script:WinToolOmpPreviewFailed[$file] = $true
        return $null
    }
    $path = Join-Path $env:LOCALAPPDATA ("WinTool\themes\" + $file)
    $url = "https://raw.githubusercontent.com/JanDeDobbeleer/oh-my-posh/main/themes/" + [uri]::EscapeDataString($file)
    $scriptText = @'
param($sync, $url, $path)
$part = $path + ".part"
try {
    [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
    $folder = Split-Path -Parent $path
    if (-not (Test-Path -LiteralPath $folder)) { New-Item -ItemType Directory -Path $folder -Force | Out-Null }
    Invoke-WebRequest -Uri $url -OutFile $part -UseBasicParsing -TimeoutSec 10
    if (-not (Test-Path -LiteralPath $part) -or (Get-Item -LiteralPath $part).Length -le 2) {
        throw "Downloaded preview theme was empty."
    }
    Move-Item -LiteralPath $part -Destination $path -Force
    $sync.Ok = $true
}
catch {
    Remove-Item -LiteralPath $part -Force -ErrorAction SilentlyContinue
    $sync.Error = $_.Exception.Message
}
finally {
    $sync.Done = $true
}
'@
    try {
        $job = Start-WinToolScriptJob -ScriptText $scriptText -Argument @($url, $path)
        $script:WinToolState.PreviewJob = [pscustomobject]@{ Job = $job; File = $file; Started = [datetime]::UtcNow }
    }
    catch {
        $script:WinToolOmpPreviewFailed[$file] = $true
    }
    return $null
}

function Complete-WinToolPreviewThemeDownload {
    $preview = $script:WinToolState.PreviewJob
    $script:WinToolState.PreviewJob = $null
    if ($null -eq $preview) {
        return
    }
    $ok = [bool]$preview.Job.Sync.Ok
    Stop-WinToolThread -Job $preview.Job
    if (-not $ok) {
        if ($null -eq $script:WinToolOmpPreviewFailed) { $script:WinToolOmpPreviewFailed = @{} }
        $script:WinToolOmpPreviewFailed[[string]$preview.File] = $true
    }
    try {
        Update-WinToolTerminalPreview
    }
    catch {
        $null = $_.Exception.Message
    }
}

function New-WinToolTerminalPreview {
    param($Segments)
    $border = New-Object System.Windows.Controls.Border
    $border.CornerRadius = [System.Windows.CornerRadius]::new(8)
    $border.Padding = [System.Windows.Thickness]::new(12)
    $border.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, "BrushLog")
    $text = New-Object System.Windows.Controls.TextBlock
    $text.FontFamily = "Consolas"
    $text.SetResourceReference([System.Windows.Controls.TextBlock]::FontSizeProperty, "FontSizeBody")
    $text.TextWrapping = "Wrap"
    foreach ($segment in @($Segments)) {
        $run = New-Object System.Windows.Documents.Run
        $run.Text = [string]$segment.text
        $runColor = [System.Windows.Media.Color]([System.Windows.Media.ColorConverter]::ConvertFromString([string]$segment.color))
        $run.Foreground = [System.Windows.Media.SolidColorBrush]::new($runColor)
        [void]$text.Inlines.Add($run)
    }
    $border.Child = $text
    return $border
}

function Update-WinToolTerminalCatalogOnline {
    if ($null -ne $script:WinToolState.CatalogJob) {
        return
    }
    Write-WinToolLog -Message "Refreshing Nerd Fonts and Oh My Posh themes from GitHub." -Level "info"
    $refreshButton = Get-WinToolUi -Name "TerminalRefresh"
    if ($null -ne $refreshButton) {
        $refreshButton.IsEnabled = $false
    }
    $scriptText = @'
param($sync)
try {
    [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
    $headers = @{ "User-Agent" = "WinTool"; "Accept" = "application/vnd.github+json" }
    $release = Invoke-RestMethod -Uri "https://api.github.com/repos/ryanoasis/nerd-fonts/releases/latest" -Headers $headers -TimeoutSec 15
    $themes = Invoke-RestMethod -Uri "https://api.github.com/repos/JanDeDobbeleer/oh-my-posh/contents/themes?ref=main" -Headers $headers -TimeoutSec 15
    $sync.Release = $release
    $sync.Themes = $themes
    $sync.Ok = $true
}
catch {
    $sync.Error = $_.Exception.Message
}
finally {
    $sync.Done = $true
}
'@
    try {
        $job = Start-WinToolScriptJob -ScriptText $scriptText -Argument @()
        $script:WinToolState.CatalogJob = [pscustomobject]@{ Job = $job; Started = [datetime]::UtcNow }
    }
    catch {
        if ($null -ne $refreshButton -and -not $script:WinToolState.Busy) {
            $refreshButton.IsEnabled = $true
        }
        Write-WinToolLog -Message ("Could not refresh the catalogs. The built-in lists are still available. " + $_.Exception.Message) -Level "warn"
    }
}

function Complete-WinToolTerminalCatalogOnline {
    $catalogJob = $script:WinToolState.CatalogJob
    $script:WinToolState.CatalogJob = $null
    if ($null -eq $catalogJob) {
        return
    }
    $ok = [bool]$catalogJob.Job.Sync.Ok
    $errText = [string]$catalogJob.Job.Sync.Error
    $release = $catalogJob.Job.Sync.Release
    $themes = $catalogJob.Job.Sync.Themes
    Stop-WinToolThread -Job $catalogJob.Job
    $refreshButton = Get-WinToolUi -Name "TerminalRefresh"
    if ($null -ne $refreshButton -and -not $script:WinToolState.Busy) {
        $refreshButton.IsEnabled = $true
    }
    if (-not $ok) {
        Write-WinToolLog -Message ("Could not refresh the catalogs. The built-in lists are still available. " + $errText) -Level "warn"
        return
    }
    try {
        $known = @{}
        foreach ($font in @(Get-WinToolActiveFont)) {
            $asset = [string](Get-WinToolNote -Object $font -Name "asset" -Default "")
            if (-not [string]::IsNullOrWhiteSpace($asset)) { $known[$asset] = $true }
        }
        $added = New-Object System.Collections.Generic.List[object]
        foreach ($asset in @($release.assets)) {
            $name = [string]$asset.name
            if (-not $name.EndsWith(".zip")) { continue }
            if ($name -eq "FontPatcher.zip" -or $name -eq "NerdFontsSymbolsOnly.zip") { continue }
            if ($known.ContainsKey($name)) { continue }
            $stem = [IO.Path]::GetFileNameWithoutExtension($name)
            $added.Add([pscustomobject]@{
                id = ($stem.ToLower() + "-nf")
                name = ($stem + " Nerd Font")
                face = ($stem + " Nerd Font")
                match = $stem
                nerd = $true
                source = "nerd-fonts"
                release = [string]$release.tag_name
                asset = $name
                sample = "agnoster ~/src main"
            })
        }
        $script:WinToolExtraFont = @($script:WinToolExtraFont) + @($added.ToArray())
        $knownThemes = @{}
        foreach ($theme in @(Get-WinToolActiveOhMyPoshTheme)) { $knownThemes[[string]$theme.file] = $true }
        $extraThemes = New-Object System.Collections.Generic.List[object]
        foreach ($theme in @($themes)) {
            $file = [string]$theme.name
            if (-not $file.EndsWith(".omp.json")) { continue }
            if ($knownThemes.ContainsKey($file)) { continue }
            $id = $file.Substring(0, $file.Length - 9)
            $extraThemes.Add([pscustomobject]@{ id = $id; file = $file; name = $id })
        }
        $script:WinToolExtraOhMyPoshTheme = @($script:WinToolExtraOhMyPoshTheme) + @($extraThemes.ToArray())
        Build-WinToolPromptCard
        Update-WinToolPromptSelection
        Update-WinToolFontList
        Update-WinToolPromptStyleList
        Write-WinToolLog -Message ("Catalog refresh added " + @($added.ToArray()).Count + " fonts and " + @($extraThemes.ToArray()).Count + " themes.") -Level "ok"
    }
    catch {
        Write-WinToolLog -Message ("Could not apply the refreshed catalogs. " + $_.Exception.Message) -Level "warn"
    }
}

function Invoke-WinToolTerminalClick {
    $choice = Get-WinToolTerminalChoice
    $summary = @(Get-WinToolTerminalSummary -Selection $choice)
    $preview = ($summary -join "`n")
    $ok = Request-WinToolConfirmation -Message ("Apply this terminal setup?`n`n" + $preview) -Title "Terminal"
    if (-not $ok) { return }
    $steps = @(Get-WinToolTerminalPlan -Selection $choice)
    Invoke-WinToolPlanAsync -Step $steps -DoneMessage "Terminal setup finished. Open a new terminal window to see the prompt."
}

function Initialize-WinToolTerminalView {
    $script:WinToolTerminalChoice = Get-WinToolSimpleTerminalChoice
    $script:WinToolTerminalMode = "simple"
    $script:WinToolTerminalFilter = "all"
    $script:WinToolTerminalSyncing = $false
    $script:WinToolExtraFont = @()
    $script:WinToolExtraOhMyPoshTheme = @()
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TerminalModeSimple") -EventName "Checked" -Name "Terminal: Simple mode" -Action {
        $script:WinToolTerminalMode = "simple"
        Set-WinToolTerminalModeView
        $script:WinToolTerminalChoice = Get-WinToolSimpleTerminalChoice
        Update-WinToolTerminalSummary
        Update-WinToolTerminalPreview
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TerminalModeAdvanced") -EventName "Checked" -Name "Terminal: Advanced mode" -Action {
        $script:WinToolTerminalMode = "advanced"
        Set-WinToolTerminalModeView
        Update-WinToolExtraToggle
        # Simple resets the choice to the recommended setup, so the theme list,
        # fonts, and sizes are rebuilt for that choice here, before anything
        # reads them. Without this the theme list kept the last engine's rows.
        Update-WinToolFontSizeSelection
        Update-WinToolFontList
        Update-WinToolPromptStyleList
        Update-WinToolTerminalSummary
        Update-WinToolPromptSelection
        Update-WinToolSchemeSelection
        Update-WinToolTerminalPreview
        Show-WinToolTerminalSelection
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TerminalFontNerdOnly") -EventName "Click" -Name "Terminal: Nerd Fonts only" -Action { Update-WinToolFontList }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TerminalThemeSearch") -EventName "TextChanged" -Name "Terminal: theme search" -Action {
        Sync-WinToolSearchHint -BoxName "TerminalThemeSearch" -HintName "TerminalThemeSearchHint"
        Update-WinToolPromptStyleList
        Update-WinToolTerminalSummary
        Update-WinToolTerminalPreview
    }
    foreach ($filterName in @("TerminalFilterAll", "TerminalFilterPowerline", "TerminalFilterMinimal", "TerminalFilterNoNerd")) {
        Register-WinToolUiEvent -Control (Get-WinToolUi -Name $filterName) -EventName "Checked" -Name "Terminal: theme filter" -Action {
            param($source, $eventData)
            $null = $eventData
            $script:WinToolTerminalFilter = [string]$source.Tag
            Update-WinToolPromptStyleList
            Update-WinToolTerminalSummary
            Update-WinToolTerminalPreview
        }
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TerminalRefresh") -EventName "Click" -Name "Terminal: refresh lists" -Action { Update-WinToolTerminalCatalogOnline }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TerminalSetup") -EventName "Click" -Name "Terminal: apply setup" -Action { Invoke-WinToolTerminalClick }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TerminalFontList") -EventName "SelectionChanged" -Name "Terminal: choose font" -Action {
        Update-WinToolFontSample
        Update-WinToolTerminalSummary
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TerminalFontSize") -EventName "SelectionChanged" -Name "Terminal: choose font size" -Action {
        $sizeBox = Get-WinToolUi -Name "TerminalFontSize"
        if ($null -ne $sizeBox.SelectedItem -and -not $script:WinToolTerminalSyncing) {
            Set-WinToolTerminalChoiceValue -Name "fontSize" -Value ([int]$sizeBox.SelectedItem.Tag)
            Update-WinToolTerminalSummary
            Update-WinToolTerminalPreview
        }
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TerminalStyleList") -EventName "SelectionChanged" -Name "Terminal: choose prompt style" -Action {
        # While the list is rebuilt for another engine, its selection changes
        # are not clicks: they must not copy other controls into the choice.
        if ($script:WinToolTerminalSyncing) { return }
        Update-WinToolTerminalSummary
        Update-WinToolTerminalPreview
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TerminalPromptList") -EventName "SelectionChanged" -Name "Terminal: choose prompt" -Action {
        $list = Get-WinToolUi -Name "TerminalPromptList"
        if ($script:WinToolTerminalSyncing -or $null -eq $list.SelectedItem) { return }
        $promptId = [string]$list.SelectedItem.Tag
        if ([string]::IsNullOrWhiteSpace($promptId) -or $promptId -eq [string]$script:WinToolTerminalChoice.prompt) { return }
        Select-WinToolTerminalPrompt -PromptId $promptId
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TerminalBodyScroll") -EventName "SizeChanged" -Name "Terminal: layout" -Action {
        $bodyScroll = Get-WinToolUi -Name "TerminalBodyScroll"
        Update-WinToolTerminalLayout -Width $bodyScroll.ActualWidth -Height $bodyScroll.ActualHeight
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "TerminalSummaryScroll") -EventName "PreviewMouseWheel" -Name "Terminal: scroll the summary" -Action {
        param($source, $eventData)
        # One line of chips; the wheel moves it sideways when it is longer than the bar.
        if ($null -ne $eventData -and $source.ScrollableWidth -gt 0) {
            $source.ScrollToHorizontalOffset($source.HorizontalOffset - [double]$eventData.Delta / 2.0)
            $eventData.Handled = $true
        }
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "NavTerminal") -EventName "Checked" -Name "Terminal: show the selection" -Action {
        Show-WinToolTerminalSelection
    }
    Build-WinToolSimpleTerminalCard
    Build-WinToolPromptCard
    Build-WinToolExtraToggle
    Build-WinToolSchemeCard
    Build-WinToolFontSizeList
    Update-WinToolFontList
    Update-WinToolPromptStyleList
    Update-WinToolTerminalSummary
    Update-WinToolTerminalPreview
}

function Set-WinToolTerminalModeView {
    $advanced = ($script:WinToolTerminalMode -eq "advanced")
    $body = Get-WinToolUi -Name "TerminalBodyScroll"
    $simple = Get-WinToolUi -Name "TerminalSimpleScroll"
    $subtitle = Get-WinToolUi -Name "TerminalSubtitle"
    if ($advanced) {
        $simple.Visibility = "Collapsed"
        $body.Visibility = "Visible"
        $subtitle.Text = "Pick a prompt, a theme, a font and a color scheme. The preview updates as you click."
    }
    else {
        $body.Visibility = "Collapsed"
        $simple.Visibility = "Visible"
        $subtitle.Text = "A recommended setup in one click. Switch to Advanced to choose each part."
    }
}

function Select-WinToolTerminalPrompt {
    param(
        [Parameter(Mandatory = $true)][string]$PromptId
    )
    Set-WinToolTerminalChoiceValue -Name "prompt" -Value $PromptId
    # A new engine starts on All, so a filter never leaves its list empty.
    $script:WinToolTerminalFilter = "all"
    $allChip = Get-WinToolUi -Name "TerminalFilterAll"
    if ($null -ne $allChip -and $allChip.IsChecked -ne $true) { $allChip.IsChecked = $true }
    Update-WinToolPromptStyleList
    Update-WinToolTerminalSummary
    Update-WinToolPromptSelection
    Update-WinToolTerminalPreview
    Show-WinToolTerminalSelection
}

function New-WinToolTerminalLabel {
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Text,
        [string]$Brush = "BrushInk",
        [string]$Weight = "Normal"
    )
    # Every label uses the shared FontSizeBody (14 px) text size.
    $block = New-WinToolText -Text $Text -Brush $Brush -Weight $Weight
    $block.TextTrimming = "CharacterEllipsis"
    return $block
}

function Build-WinToolPromptCard {
    # The engines as one list, grouped by the shell they run in.
    $list = Get-WinToolUi -Name "TerminalPromptList"
    $rowStyle = $list.FindResource("TerminalRow")
    $script:WinToolPromptCheck = @{}
    $script:WinToolTerminalSyncing = $true
    try {
        $list.Items.Clear()
        $prompts = @(Get-WinToolNote -Object (Get-WinToolTerminalCatalog) -Name "prompts" -Default @())
        $ompCount = @(Get-WinToolActiveOhMyPoshTheme).Count
        $infos = @($prompts | ForEach-Object { Get-WinToolPromptEngineInfo -Prompt $_ -OhMyPoshCount $ompCount })
        foreach ($group in @("PowerShell", "WSL Ubuntu")) {
            $header = New-Object System.Windows.Controls.ListBoxItem
            $header.Style = $rowStyle
            $header.IsEnabled = $false
            $header.Focusable = $false
            $header.Padding = [System.Windows.Thickness]::new(8, 6, 8, 2)
            $header.Content = New-WinToolTerminalLabel -Text $group.ToUpperInvariant() -Brush "BrushHint" -Weight "SemiBold"
            [void]$list.Items.Add($header)
            for ($index = 0; $index -lt $prompts.Count; $index++) {
                $prompt = $prompts[$index]
                $info = $infos[$index]
                if ($info.Group -ne $group) { continue }
                [void]$list.Items.Add((New-WinToolPromptRow -Prompt $prompt -Info $info -Style $rowStyle))
            }
        }
        (Get-WinToolUi -Name "TerminalPromptCount").Text = ([string]$prompts.Count + " engines")
    }
    finally {
        $script:WinToolTerminalSyncing = $false
    }
    Update-WinToolPromptSelection
}

function New-WinToolPromptRow {
    param($Prompt, $Info, $Style)
    $item = New-Object System.Windows.Controls.ListBoxItem
    $item.Style = $Style
    $item.Tag = [string]$Prompt.id
    $item.BorderThickness = [System.Windows.Thickness]::new(1)
    $item.Margin = [System.Windows.Thickness]::new(0, 0, 0, 1)
    $item.ToolTip = ([string]$Prompt.name + " (" + [string]$Info.Sub + ")`n" + [string]$Prompt.summary)
    [System.Windows.Automation.AutomationProperties]::SetName($item, [string]$Prompt.name)
    $grid = New-Object System.Windows.Controls.Grid
    foreach ($width in @(34, -1, 22)) {
        $column = New-Object System.Windows.Controls.ColumnDefinition
        if ($width -lt 0) { $column.Width = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star) }
        else { $column.Width = [System.Windows.GridLength]::new($width) }
        $grid.ColumnDefinitions.Add($column)
    }
    $icon = New-Object System.Windows.Controls.Border
    $icon.Width = 24
    $icon.Height = 24
    $icon.CornerRadius = [System.Windows.CornerRadius]::new(6)
    $icon.HorizontalAlignment = "Left"
    $fill = ConvertTo-WinToolPreviewBrush -Color ([string]$Info.Color)
    if ($null -ne $fill) { $icon.Background = $fill }
    $glyph = New-Object System.Windows.Controls.TextBlock
    $glyph.Text = [string][char]0xE756
    $glyph.FontFamily = [System.Windows.Media.FontFamily]::new("Segoe MDL2 Assets")
    $glyph.SetResourceReference([System.Windows.Controls.TextBlock]::FontSizeProperty, "FontSizeBody")
    $glyph.Foreground = [System.Windows.Media.Brushes]::White
    $glyph.HorizontalAlignment = "Center"
    $glyph.VerticalAlignment = "Center"
    $icon.Child = $glyph
    [void]$grid.Children.Add($icon)
    $names = New-Object System.Windows.Controls.StackPanel
    $names.VerticalAlignment = "Center"
    [void]$names.Children.Add((New-WinToolTerminalLabel -Text ([string]$Prompt.name)))
    [System.Windows.Controls.Grid]::SetColumn($names, 1)
    [void]$grid.Children.Add($names)
    $check = New-WinToolTerminalLabel -Text ([string][char]0xE73E) -Brush "BrushAccent"
    $check.FontFamily = [System.Windows.Media.FontFamily]::new("Segoe MDL2 Assets")
    $check.VerticalAlignment = "Center"
    $check.HorizontalAlignment = "Right"
    $check.Visibility = "Collapsed"
    [System.Windows.Controls.Grid]::SetColumn($check, 2)
    [void]$grid.Children.Add($check)
    $script:WinToolPromptCheck[[string]$Prompt.id] = $check
    $item.Content = $grid
    return $item
}

function Update-WinToolPromptSelection {
    $selected = [string]$script:WinToolTerminalChoice.prompt
    $list = Get-WinToolUi -Name "TerminalPromptList"
    $script:WinToolTerminalSyncing = $true
    try {
        for ($index = 0; $index -lt $list.Items.Count; $index++) {
            $item = $list.Items[$index]
            if ([string]$item.Tag -eq $selected -and -not [string]::IsNullOrWhiteSpace($selected)) {
                if (-not [object]::ReferenceEquals($list.SelectedItem, $item)) { $list.SelectedItem = $item }
            }
        }
    }
    finally {
        $script:WinToolTerminalSyncing = $false
    }
    # Card 2 always shows the list of the checked engine.
    $styleList = Get-WinToolUi -Name "TerminalStyleList"
    if ($null -ne $styleList -and [string]$styleList.Tag -ne $selected -and -not [string]::IsNullOrWhiteSpace($selected)) {
        Update-WinToolPromptStyleList
    }
    if ($null -ne $script:WinToolPromptCheck) {
        foreach ($key in $script:WinToolPromptCheck.Keys) {
            if ($key -eq $selected) { $script:WinToolPromptCheck[$key].Visibility = "Visible" }
            else { $script:WinToolPromptCheck[$key].Visibility = "Collapsed" }
        }
    }
    # The short note under the list: what the engine is and what it installs.
    $prompt = $null
    foreach ($item in @(Get-WinToolNote -Object (Get-WinToolTerminalCatalog) -Name "prompts" -Default @())) {
        if ([string]$item.id -eq $selected) { $prompt = $item; break }
    }
    $nameBlock = Get-WinToolUi -Name "TerminalPromptName"
    $aboutBlock = Get-WinToolUi -Name "TerminalPromptAbout"
    if ($null -eq $nameBlock -or $null -eq $aboutBlock) { return }
    if ($null -eq $prompt) {
        $nameBlock.Text = ""
        $aboutBlock.Text = ""
        return
    }
    $info = Get-WinToolPromptEngineInfo -Prompt $prompt -OhMyPoshCount (@(Get-WinToolActiveOhMyPoshTheme).Count)
    $nameBlock.Text = [string]$prompt.name
    # What it installs is listed in the action bar, so the note stays short.
    $aboutBlock.Text = ([string]$info.Sub + ". " + [string]$prompt.summary).Trim()
    $aboutBlock.ToolTip = ($aboutBlock.Text + "`n`nInstalls: " + (@($prompt.installs) -join ", ") + "`n" + [string]$info.Runs).Trim()
}

function New-WinToolTerminalChip {
    param(
        [Parameter(Mandatory = $true)][string]$Text,
        [string]$Background = "BrushNavHover",
        [string]$Foreground = "BrushInk"
    )
    # A 32 px pill, like the shared chips.
    $chip = New-Object System.Windows.Controls.Border
    $chip.CornerRadius = [System.Windows.CornerRadius]::new(16)
    $chip.Height = 32
    $chip.Padding = [System.Windows.Thickness]::new(12, 0, 12, 0)
    $chip.Margin = [System.Windows.Thickness]::new(0, 0, 6, 0)
    $chip.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, $Background)
    $label = New-WinToolTerminalLabel -Text $Text -Brush $Foreground
    $label.TextTrimming = "None"
    $label.VerticalAlignment = "Center"
    $chip.Child = $label
    return $chip
}

function Update-WinToolPromptStyleList {
    $list = Get-WinToolUi -Name "TerminalStyleList"
    $prompt = [string]$script:WinToolTerminalChoice.prompt
    # The list remembers which prompt it was built for, so an old selection
    # never overwrites the style of a newly picked prompt.
    $wasSyncing = [bool]$script:WinToolTerminalSyncing
    $script:WinToolTerminalSyncing = $true
    try {
        $list.Tag = $null
        $list.Items.Clear()
        $query = [string](Get-WinToolUi -Name "TerminalThemeSearch").Text
        $note = Get-WinToolUi -Name "TerminalStyleNote"
        $filter = [string]$script:WinToolTerminalFilter
        if ([string]::IsNullOrWhiteSpace($filter)) { $filter = "all" }
        $titles = Get-WinToolThemeTitle -PromptId $prompt
        (Get-WinToolUi -Name "TerminalThemeTitle").Text = [string]$titles.Title
        (Get-WinToolUi -Name "TerminalThemeSearchHint").Text = ([string]$titles.Hint + [string][char]0x2026)
        $rows = @(Get-WinToolThemeRow -PromptId $prompt -OhMyPoshTheme @(Get-WinToolActiveOhMyPoshTheme))
        $script:WinToolTerminalRows = $rows
        $shown = @(Select-WinToolThemeRow -Row $rows -Query $query -Filter $filter)
        $rowStyle = $list.FindResource("TerminalRow")
        foreach ($row in $shown) {
            $item = New-WinToolThemeItem -Row $row -Style $rowStyle
            [void]$list.Items.Add($item)
            if ([string]$row.Id -eq [string]$script:WinToolTerminalChoice.promptStyle) {
                $list.SelectedItem = $item
            }
        }
        (Get-WinToolUi -Name "TerminalThemeCount").Text = ([string]$shown.Count + " of " + [string]$rows.Count)
        if ($null -eq $list.SelectedItem -and $list.Items.Count -gt 0) {
            $list.SelectedIndex = 0
        }
        if ($list.Items.Count -eq 0) {
            $note.Visibility = "Visible"
            if ($rows.Count -eq 0) { $note.Text = "This prompt has its own default look. The font and extras still apply." }
            else { $note.Text = "No " + [string]$titles.Noun + " match the search or filter." }
        }
        else {
            $note.Visibility = "Collapsed"
        }
        $list.Tag = $prompt
        if ($null -ne $list.SelectedItem) {
            $script:WinToolTerminalChoice.promptStyle = [string]$list.SelectedItem.Tag
        }
    }
    finally {
        $script:WinToolTerminalSyncing = $wasSyncing
    }
    Show-WinToolTerminalSelection
}

function New-WinToolThemeItem {
    param($Row, $Style)
    # Name, a "Nerd Font" tag when the theme needs one, the id, and a sample
    # prompt line in the theme colors.
    $item = New-Object System.Windows.Controls.ListBoxItem
    $item.Style = $Style
    $item.Tag = [string]$Row.Id
    $item.BorderThickness = [System.Windows.Thickness]::new(3, 0, 0, 0)
    $item.Padding = [System.Windows.Thickness]::new(8, 6, 8, 7)
    $item.Margin = [System.Windows.Thickness]::new(0, 0, 0, 1)
    $tip = [string]$Row.Id
    if (-not [string]::IsNullOrWhiteSpace([string]$Row.Description)) { $tip = [string]$Row.Description + "`n" + $tip }
    $item.ToolTip = $tip
    [System.Windows.Automation.AutomationProperties]::SetName($item, [string]$Row.Name)
    $stack = New-Object System.Windows.Controls.StackPanel
    $top = New-Object System.Windows.Controls.DockPanel
    if ($Row.NerdFont -eq $true) {
        $tag = New-WinToolTerminalLabel -Text "Nerd Font" -Brush "BrushWarn"
        $tag.TextTrimming = "None"
        $tag.Margin = [System.Windows.Thickness]::new(8, 0, 0, 0)
        $tag.VerticalAlignment = "Center"
        [System.Windows.Controls.DockPanel]::SetDock($tag, "Right")
        [void]$top.Children.Add($tag)
    }
    $nameLabel = New-WinToolTerminalLabel -Text ([string]$Row.Name)
    $nameLabel.TextTrimming = "None"
    $nameLabel.TextWrapping = "Wrap"
    [void]$top.Children.Add($nameLabel)
    [void]$stack.Children.Add($top)
    $segments = @($Row.Preview)
    if ($segments.Count -gt 0) {
        $sample = New-Object System.Windows.Controls.Border
        $sample.CornerRadius = [System.Windows.CornerRadius]::new(4)
        $sample.Padding = [System.Windows.Thickness]::new(6, 3, 6, 3)
        $sample.Margin = [System.Windows.Thickness]::new(0, 4, 0, 0)
        $sample.ClipToBounds = $true
        $sample.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, "BrushLog")
        $line = New-Object System.Windows.Controls.TextBlock
        # A sample prompt in the theme colors; it may run past the edge like a real terminal line.
        $line.Tag = "preview-content"
        $line.SetResourceReference([System.Windows.Controls.TextBlock]::FontSizeProperty, "FontSizeBody")
        $line.TextWrapping = "NoWrap"
        $line.SetResourceReference([System.Windows.Controls.TextBlock]::FontFamilyProperty, "TerminalPreviewFont")
        Set-WinToolLigatureTypography -Element $line
        $line.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, "BrushLogText")
        foreach ($segment in $segments) {
            [void]$line.Inlines.Add((New-WinToolPreviewRun -Segment $segment))
        }
        $sample.Child = $line
        [void]$stack.Children.Add($sample)
    }
    $item.Content = $stack
    return $item
}

function Set-WinToolLigatureTypography {
    param($Element)
    # Windows Terminal setup always turns ligatures on, so previews draw them too.
    if ($null -eq $Element) { return }
    [System.Windows.Documents.Typography]::SetStandardLigatures($Element, $true)
    [System.Windows.Documents.Typography]::SetContextualAlternates($Element, $true)
}

function New-WinToolPreviewRun {
    param($Segment)
    $run = New-Object System.Windows.Documents.Run -ArgumentList ([string]$Segment.Text)
    $brush = ConvertTo-WinToolPreviewBrush -Color ([string]$Segment.Foreground)
    if ($null -ne $brush) { $run.Foreground = $brush }
    $fill = ConvertTo-WinToolPreviewBrush -Color ([string]$Segment.Background)
    if ($null -ne $fill) { $run.Background = $fill }
    return $run
}

function Build-WinToolExtraToggle {
    # Each extra as the shared rounded checkbox with its name and a
    # description that wraps, in two columns.
    $hostPanel = Get-WinToolUi -Name "TerminalExtrasHost"
    $hostPanel.Children.Clear()
    $script:WinToolTerminalExtraBox = @()
    $extras = @(Get-WinToolNote -Object (Get-WinToolTerminalCatalog) -Name "extras" -Default @())
    for ($index = 0; $index -lt $extras.Count; $index++) {
        $extra = $extras[$index]
        $cell = New-Object System.Windows.Controls.Border
        $cell.Margin = [System.Windows.Thickness]::new(0, 0, 16, 0)
        $cell.Padding = [System.Windows.Thickness]::new(0, 8, 0, 8)
        $cell.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, "BrushLine")
        if ($index -ge 2) { $cell.BorderThickness = [System.Windows.Thickness]::new(0, 1, 0, 0) }
        $grid = New-Object System.Windows.Controls.Grid
        $auto = New-Object System.Windows.Controls.ColumnDefinition
        $auto.Width = [System.Windows.GridLength]::Auto
        $grid.ColumnDefinitions.Add($auto)
        $grid.ColumnDefinitions.Add((New-Object System.Windows.Controls.ColumnDefinition))
        $box = New-Object System.Windows.Controls.CheckBox
        $box.Tag = [string]$extra.id
        $box.Margin = [System.Windows.Thickness]::new(0, 0, 10, 0)
        $box.VerticalAlignment = "Top"
        [System.Windows.Automation.AutomationProperties]::SetName($box, [string]$extra.name)
        [void]$grid.Children.Add($box)
        $text = New-Object System.Windows.Controls.StackPanel
        $name = New-WinToolTerminalLabel -Text ([string]$extra.name) -Weight "SemiBold"
        $name.TextTrimming = "None"
        $name.TextWrapping = "Wrap"
        [void]$text.Children.Add($name)
        $about = New-WinToolTerminalLabel -Text ([string]$extra.description) -Brush "BrushMuted"
        $about.TextTrimming = "None"
        $about.TextWrapping = "Wrap"
        [void]$text.Children.Add($about)
        [System.Windows.Controls.Grid]::SetColumn($text, 1)
        [void]$grid.Children.Add($text)
        Register-WinToolUiEvent -Control $box -EventName "Click" -Name "Terminal: extras" -Action {
            Update-WinToolTerminalSummary
            Update-WinToolTerminalPreview
        }
        $cell.Child = $grid
        [void]$hostPanel.Children.Add($cell)
        $script:WinToolTerminalExtraBox += $box
    }
    Update-WinToolExtraToggle
}

function Get-WinToolExtraChoiceName {
    param([string]$ExtraId)
    if ($ExtraId -eq "terminal-icons") { return "terminalIcons" }
    if ($ExtraId -eq "psreadline") { return "psReadLine" }
    return $ExtraId
}

function Update-WinToolExtraToggle {
    # The switches follow the current choice (Simple turns on the recommended ones).
    $boxes = $script:WinToolTerminalExtraBox
    if ($null -eq $boxes) { return }
    for ($index = 0; $index -lt $boxes.Count; $index++) {
        $toggle = $boxes[$index]
        if ($null -eq $toggle) { continue }
        $choiceName = Get-WinToolExtraChoiceName -ExtraId ([string]$toggle.Tag)
        $choiceValue = Get-WinToolNote -Object $script:WinToolTerminalChoice -Name $choiceName
        $toggle.IsChecked = [bool]($null -ne $choiceValue -and [bool]$choiceValue)
    }
}

function Build-WinToolSchemeCard {
    $hostPanel = Get-WinToolUi -Name "TerminalSchemeHost"
    $hostPanel.Children.Clear()
    foreach ($scheme in @(Get-WinToolNote -Object (Get-WinToolTerminalCatalog) -Name "schemes" -Default @())) {
        $card = New-WinToolTerminalTile
        # Each tile is drawn in its own colors: the scheme background with
        # the name in its text color, so no extra swatch or hex line is needed.
        $card.Padding = [System.Windows.Thickness]::new(4, 0, 4, 0)
        $card.Margin = [System.Windows.Thickness]::new(0, 0, 6, 0)
        $card.Height = 36
        $card.CornerRadius = [System.Windows.CornerRadius]::new(6)
        $card.Tag = [string]$scheme.id
        $card.ToolTip = [string]$scheme.name + " " + [string]$scheme.background
        [System.Windows.Automation.AutomationProperties]::SetName($card, [string]$scheme.name)
        $tileFill = ConvertTo-WinToolPreviewBrush -Color ([string]$scheme.background)
        if ($null -ne $tileFill) { $card.Background = $tileFill }
        $palette = Get-WinToolNote -Object $scheme -Name "palette"
        $mark = New-Object System.Windows.Controls.TextBlock
        $mark.SetResourceReference([System.Windows.Controls.TextBlock]::FontSizeProperty, "FontSizeBody")
        $mark.VerticalAlignment = "Center"
        $mark.HorizontalAlignment = "Center"
        $mark.Inlines.Add((New-WinToolPreviewRun -Segment ([pscustomobject]@{ Text = ([string][char]0x276F + " "); Foreground = [string](Get-WinToolNote -Object $palette -Name "green" -Default ([string]$scheme.cursor)); Background = $null })))
        $mark.Inlines.Add((New-WinToolPreviewRun -Segment ([pscustomobject]@{ Text = [string]$scheme.name; Foreground = [string]$scheme.foreground; Background = $null })))
        $grid = $mark
        $card.Child = $grid
        Register-WinToolUiEvent -Control $card -EventName "MouseLeftButtonUp" -Name "Terminal: choose color scheme" -Data ([string]$scheme.id) -Action {
            param($source, $eventData, $schemeId)
            $null = $source, $eventData
            Set-WinToolTerminalChoiceValue -Name "schemeId" -Value $schemeId
            Update-WinToolTerminalSummary
            Update-WinToolSchemeSelection
            Update-WinToolTerminalPreview
        }
        [void]$hostPanel.Children.Add($card)
    }
    Update-WinToolSchemeSelection
}

function Build-WinToolFontSizeList {
    $box = Get-WinToolUi -Name "TerminalFontSize"
    $script:WinToolTerminalSyncing = $true
    try {
        $box.Items.Clear()
        foreach ($size in @(9, 10, 11, 12, 13, 14, 15, 16, 18, 20)) {
            $item = New-Object System.Windows.Controls.ComboBoxItem
            $item.Content = ([string]$size + " pt")
            $item.Tag = $size
            [void]$box.Items.Add($item)
        }
    }
    finally {
        $script:WinToolTerminalSyncing = $false
    }
    Update-WinToolFontSizeSelection
}

function Update-WinToolFontSizeSelection {
    $box = Get-WinToolUi -Name "TerminalFontSize"
    if ($null -eq $box) { return }
    $wanted = 12
    $value = Get-WinToolNote -Object $script:WinToolTerminalChoice -Name "fontSize"
    if ($null -ne $value) { $wanted = [int]$value }
    $script:WinToolTerminalSyncing = $true
    try {
        for ($index = 0; $index -lt $box.Items.Count; $index++) {
            $item = $box.Items[$index]
            if ([int]$item.Tag -eq $wanted) { $box.SelectedItem = $item }
        }
    }
    finally {
        $script:WinToolTerminalSyncing = $false
    }
}

function Update-WinToolTerminalLayout {
    param(
        [double]$Width,
        [double]$Height = -1
    )
    # Wide: prompt engines | themes | preview with font and colors, and the
    # extras under the last two. Below 760 px of content (a window under
    # about 1050 px) the preview, font, and extras move under the lists.
    # When the body is shorter than the cards need at 14 px text, it gets a
    # fixed height and scrolls instead of squeezing or clipping the cards.
    $grid = Get-WinToolUi -Name "TerminalAdvancedHost"
    $scroll = Get-WinToolUi -Name "TerminalBodyScroll"
    if ($null -eq $grid -or $null -eq $scroll) {
        return
    }
    if ($Width -le 0) { $Width = $scroll.ActualWidth }
    if ($Height -lt 0) { $Height = $scroll.ActualHeight }
    if ($Width -le 0) { return }
    $narrow = ($Width -lt 760)
    $side = Get-WinToolUi -Name "TerminalSideColumn"
    $prompt = Get-WinToolUi -Name "TerminalCardPrompt"
    $extras = Get-WinToolUi -Name "TerminalCardExtras"
    $right = Get-WinToolUi -Name "TerminalColumnRight"
    $gap = Get-WinToolUi -Name "TerminalColumnGap"
    $mainRow = Get-WinToolUi -Name "TerminalRowMain"
    $previewRow = Get-WinToolUi -Name "TerminalRowPreview"
    if ($narrow -ne [bool]$script:WinToolTerminalNarrow -or $null -eq $script:WinToolTerminalNarrow) {
        $script:WinToolTerminalNarrow = $narrow
        if ($narrow) {
            [System.Windows.Controls.Grid]::SetRow($side, 1)
            [System.Windows.Controls.Grid]::SetColumn($side, 0)
            [System.Windows.Controls.Grid]::SetColumnSpan($side, 5)
            $side.Margin = [System.Windows.Thickness]::new(0, 12, 0, 0)
            [System.Windows.Controls.Grid]::SetRowSpan($prompt, 1)
            [System.Windows.Controls.Grid]::SetColumn($extras, 0)
            [System.Windows.Controls.Grid]::SetColumnSpan($extras, 5)
            $right.Width = [System.Windows.GridLength]::new(0)
            $gap.Width = [System.Windows.GridLength]::new(0)
            $mainRow.Height = [System.Windows.GridLength]::new(520)
            $previewRow.Height = [System.Windows.GridLength]::new(300)
        }
        else {
            [System.Windows.Controls.Grid]::SetRow($side, 0)
            [System.Windows.Controls.Grid]::SetColumn($side, 4)
            [System.Windows.Controls.Grid]::SetColumnSpan($side, 1)
            $side.Margin = [System.Windows.Thickness]::new(0)
            [System.Windows.Controls.Grid]::SetRowSpan($prompt, 3)
            [System.Windows.Controls.Grid]::SetColumn($extras, 2)
            [System.Windows.Controls.Grid]::SetColumnSpan($extras, 3)
            $right.Width = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star)
            $gap.Width = [System.Windows.GridLength]::new(12)
            $mainRow.Height = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star)
            $previewRow.Height = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star)
        }
    }
    if ($narrow) {
        # The lists get a row tall enough for every engine; the body scrolls.
        $promptCard = Get-WinToolUi -Name "TerminalCardPrompt"
        $promptCard.Measure([System.Windows.Size]::new(230.0, [double]::PositiveInfinity))
        $mainRow.Height = [System.Windows.GridLength]::new([Math]::Max(520.0, [Math]::Ceiling($promptCard.DesiredSize.Height)))
        $grid.Height = [double]::NaN
        return
    }
    # Wide: fill the body, but never go below what the cards need.
    $need = Get-WinToolTerminalBodyMinHeight -Width $Width
    if ($Height -gt 0 -and $Height -ge $need) {
        $grid.Height = $Height
    }
    else {
        $grid.Height = $need
    }
}

function Get-WinToolTerminalBodyMinHeight {
    param([double]$Width)
    # The tallest of: the whole prompt card (all engines and the note), and
    # the theme card or the preview with font card, plus the extras below.
    $prompt = Get-WinToolUi -Name "TerminalCardPrompt"
    $font = Get-WinToolUi -Name "TerminalCardFont"
    $extras = Get-WinToolUi -Name "TerminalCardExtras"
    $infinite = [double]::PositiveInfinity
    $promptWidth = 230.0
    $restWidth = [Math]::Max(200.0, ($Width - $promptWidth - 24.0) / 2.0)
    $prompt.Measure([System.Windows.Size]::new($promptWidth, $infinite))
    $font.Measure([System.Windows.Size]::new($restWidth, $infinite))
    $extras.Measure([System.Windows.Size]::new(($restWidth * 2.0) + 12.0, $infinite))
    $promptNeed = $prompt.DesiredSize.Height
    $previewMin = [double](Get-WinToolUi -Name "TerminalRowPreview").MinHeight
    $sideNeed = $previewMin + 12.0 + $font.DesiredSize.Height
    $themeNeed = 260.0
    $restNeed = [Math]::Max($sideNeed, $themeNeed) + $extras.DesiredSize.Height
    return [Math]::Ceiling([Math]::Max([Math]::Max($promptNeed, $restNeed), 420.0))
}

function Update-WinToolFontList {
    $list = Get-WinToolUi -Name "TerminalFontList"
    $nerdOnly = ((Get-WinToolUi -Name "TerminalFontNerdOnly").IsChecked -eq $true)
    $allFonts = @(Get-WinToolActiveFont)
    $fonts = @(Select-WinToolFont -Font $allFonts -Query "" -NerdOnly $nerdOnly)
    $script:WinToolTerminalSyncing = $true
    try {
        $list.Items.Clear()
        foreach ($font in $fonts) {
            $item = New-Object System.Windows.Controls.ComboBoxItem
            $badge = "Programming font"
            if ($font.nerd) { $badge = "Nerd Font" }
            $item.Content = [string]$font.name
            $item.ToolTip = $badge
            $item.Tag = [string]$font.id
            [void]$list.Items.Add($item)
            if ([string]$font.id -eq [string]$script:WinToolTerminalChoice.fontId) {
                $list.SelectedItem = $item
            }
        }
    }
    finally {
        $script:WinToolTerminalSyncing = $false
    }
    if ($null -eq $list.SelectedItem -and $list.Items.Count -gt 0) {
        $list.SelectedIndex = 0
    }
    $nerdCount = @($allFonts | Where-Object { $_.nerd }).Count
    $schemeCount = @(Get-WinToolNote -Object (Get-WinToolTerminalCatalog) -Name "schemes" -Default @()).Count
    $dot = " " + [string][char]0x00B7 + " "
    $countBlock = Get-WinToolUi -Name "TerminalFontCount"
    if ($null -ne $countBlock) {
        $countBlock.Text = ([string]$allFonts.Count + " fonts" + $dot + $nerdCount + " Nerd Fonts" + $dot + $schemeCount + " schemes")
    }
    Update-WinToolFontSizeSelection
    Update-WinToolFontSample
}

function Show-WinToolTerminalSelection {
    # Brings the chosen engine and theme into view in their lists. When a list
    # is not laid out yet, the log pump calls this again a moment later.
    $script:WinToolTerminalScrollPending = $false
    foreach ($name in @("TerminalPromptList", "TerminalStyleList")) {
        $list = Get-WinToolUi -Name $name
        if ($null -eq $list -or $null -eq $list.SelectedItem) { continue }
        try {
            $list.UpdateLayout()
            $list.ScrollIntoView($list.SelectedItem)
            # ScrollIntoView needs a later layout pass; moving the list's own
            # scroll viewer (item based) works right away.
            $viewer = Find-WinToolChildScrollViewer -Element $list
            if ($null -ne $viewer -and $list.SelectedIndex -ge 0 -and $viewer.ViewportHeight -gt 0) {
                $target = [Math]::Max(0, $list.SelectedIndex - 1)
                if ($list.SelectedIndex -lt $viewer.VerticalOffset -or $list.SelectedIndex -ge ($viewer.VerticalOffset + $viewer.ViewportHeight)) {
                    $viewer.ScrollToVerticalOffset($target)
                    $list.UpdateLayout()
                }
            }
            if ($list.ActualHeight -le 0 -and $script:WinToolTerminalMode -eq "advanced") {
                # Not laid out yet (hidden tab or mode); the log pump retries.
                $script:WinToolTerminalScrollPending = $true
            }
        }
        catch {
            $null = $_.Exception.Message
        }
    }
}

function Get-WinToolTerminalScheme {
    $fallback = [pscustomobject]@{ id = ""; name = "Default"; background = "#0F131C"; foreground = "#D5DEEE"; cursor = "#6C9BFF"; palette = $null }
    if ($null -eq $script:WinToolTerminalChoice) { return $fallback }
    foreach ($scheme in @(Get-WinToolNote -Object (Get-WinToolTerminalCatalog) -Name "schemes" -Default @())) {
        if ([string]$scheme.id -eq [string]$script:WinToolTerminalChoice.schemeId) { return $scheme }
    }
    return $fallback
}

function Update-WinToolTerminalPreview {
    # Draws a short terminal session with the chosen prompt and theme, in the
    # chosen font and size, on the chosen color scheme. Never throws: a
    # failure keeps the last preview.
    $sample = Get-WinToolUi -Name "TerminalFontSample"
    $border = Get-WinToolUi -Name "TerminalFontPreview"
    if ($null -eq $sample -or $null -eq $border -or $null -eq $script:WinToolTerminalChoice) {
        return
    }
    try {
        $choice = $script:WinToolTerminalChoice
        $promptId = [string]$choice.prompt
        $style = [string]$choice.promptStyle
        $theme = $null
        $waiting = $false
        if ($promptId -eq "oh-my-posh") {
            $theme = Get-WinToolPreviewTheme -ThemeId $style
            $waiting = ($null -eq $theme -and $null -ne $script:WinToolState.PreviewJob)
        }
        $segments = @(Get-WinToolPromptPreview -PromptId $promptId -PromptStyle $style -Theme $theme)

        $scheme = Get-WinToolTerminalScheme
        $palette = Get-WinToolNote -Object $scheme -Name "palette"
        $background = ConvertTo-WinToolPreviewBrush -Color ([string]$scheme.background)
        $foreground = ConvertTo-WinToolPreviewBrush -Color ([string]$scheme.foreground)
        if ($null -ne $background) {
            $border.Background = $background
            $tab = Get-WinToolUi -Name "TerminalPreviewTab"
            if ($null -ne $tab) { $tab.Background = $background }
        }
        if ($null -ne $foreground) { $sample.Foreground = $foreground }

        $face = ""
        $fontName = ""
        foreach ($font in @(Get-WinToolActiveFont)) {
            if ([string]$font.id -eq [string]$choice.fontId) { $face = [string]$font.face; $fontName = [string]$font.name; break }
        }
        $families = "Cascadia Mono, Consolas"
        if (-not [string]::IsNullOrWhiteSpace($face)) { $families = $face + ", " + $families }
        $family = [System.Windows.Media.FontFamily]::new($families)
        $sample.FontFamily = $family
        Set-WinToolLigatureTypography -Element $sample
        $styleList = Get-WinToolUi -Name "TerminalStyleList"
        if ($null -ne $styleList) { $styleList.Resources["TerminalPreviewFont"] = $family }
        $size = 12
        $sizeValue = Get-WinToolNote -Object $choice -Name "fontSize"
        if ($null -ne $sizeValue -and [int]$sizeValue -gt 0) { $size = [int]$sizeValue }
        $sample.FontSize = [Math]::Round($size * 1.1, 1)
        $sample.LineHeight = [Math]::Round($sample.FontSize * 1.5)

        $info = $null
        $promptName = $promptId
        foreach ($item in @(Get-WinToolNote -Object (Get-WinToolTerminalCatalog) -Name "prompts" -Default @())) {
            if ([string]$item.id -eq $promptId) { $info = Get-WinToolPromptEngineInfo -Prompt $item -OhMyPoshCount 0; $promptName = [string]$item.name; break }
        }
        $wsl = ($null -ne $info -and $info.Wsl)
        $tabText = Get-WinToolUi -Name "TerminalPreviewTabText"
        if ($null -ne $tabText) {
            if ($wsl) { $tabText.Text = "Ubuntu" } else { $tabText.Text = "PowerShell" }
        }

        $red = ConvertTo-WinToolPreviewColor -Value ([string](Get-WinToolNote -Object $palette -Name "red" -Default "#F07178")) -Palette $null
        $yellow = ConvertTo-WinToolPreviewColor -Value ([string](Get-WinToolNote -Object $palette -Name "yellow" -Default "#EED49F")) -Palette $null
        $blue = ConvertTo-WinToolPreviewColor -Value ([string](Get-WinToolNote -Object $palette -Name "blue" -Default "#6C9BFF")) -Palette $null
        $dim = ConvertTo-WinToolPreviewColor -Value ([string](Get-WinToolNote -Object $palette -Name "brightBlack" -Default "#5B6680")) -Palette $null

        $sample.Inlines.Clear()
        $addLine = {
            param([object[]]$Parts)
            if ($sample.Inlines.Count -gt 0) { $sample.Inlines.Add((New-Object System.Windows.Documents.LineBreak)) }
            foreach ($part in @($Parts)) { $sample.Inlines.Add((New-WinToolPreviewRun -Segment $part)) }
        }
        $text = { param([string]$Value, [string]$Color) New-WinToolPreviewSegment -Text $Value -Foreground $Color }
        $header = "PowerShell 7"
        if ($wsl) {
            $header = "Ubuntu on WSL " + [string][char]0x00B7 + " zsh"
            if ($promptId -eq "tide") { $header = "Ubuntu on WSL " + [string][char]0x00B7 + " fish" }
        }
        & $addLine @((& $text $header $dim))
        & $addLine @((& $text " " ""))
        & $addLine (@($segments) + @((& $text " git status" "")))
        & $addLine @((& $text "On branch main" ""))
        & $addLine @((& $text "Changes not staged for commit:" ""))
        & $addLine @((& $text "        modified:   src/app.ts" $red))
        & $addLine @((& $text " " ""))
        & $addLine (@($segments) + @((& $text " head -1 src/app.ts" "")))
        & $addLine @((& $text "const same = (a, b) => a === b || a >= b;" ""))
        & $addLine @((& $text " " ""))
        $jump = " cd wintool"
        if ([bool]$choice.zoxide) { $jump = " z wintool" }
        & $addLine (@($segments) + @((& $text $jump "")))
        & $addLine (@($segments) + @((& $text " ls" "")))
        $folder = ""
        $file = ""
        if ([bool]$choice.terminalIcons -and -not $wsl) {
            $folder = [string][char]0xF07B + " "
            $file = [string][char]0xF489 + " "
        }
        $listing = ""
        foreach ($name in @("assets", "build", "data", "src")) { $listing += $folder + $name + "   " }
        & $addLine @((& $text $listing $blue), (& $text ($file + "wintool.ps1") $yellow))
        $last = @($segments) + @((& $text " git s" ""), (New-WinToolPreviewSegment -Text " " -Background ([string]$scheme.cursor)))
        if ([bool]$choice.psReadLine -and -not $wsl) { $last += (& $text "tatus" $dim) }
        & $addLine $last

        $themeName = $style
        foreach ($row in @($script:WinToolTerminalRows)) {
            if ($null -ne $row -and [string]$row.Id -eq $style) { $themeName = [string]$row.Name; break }
        }
        $dot = " " + [string][char]0x00B7 + " "
        $infoBlock = Get-WinToolUi -Name "TerminalPreviewInfo"
        if ($null -ne $infoBlock) {
            $parts = @($promptName, $themeName, ($fontName + " " + $size), [string]$scheme.name) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) }
            $infoBlock.Text = ($parts -join $dot)
            $infoBlock.ToolTip = $infoBlock.Text
        }
        $tip = "Font: " + $face
        if ($waiting) { $tip += "`nLoading the theme colors from GitHub..." }
        elseif ($promptId -eq "oh-my-posh" -and $null -eq $theme) { $tip += "`nTheme colors come from the WinTool catalog sample." }
        $border.ToolTip = $tip
    }
    catch {
        $null = $_.Exception.Message
    }
}

function Read-WinToolExtraSelection {
    $flags = @{ "terminal-icons" = $false; psreadline = $false; zoxide = $false; fzf = $false }
    $boxes = $script:WinToolTerminalExtraBox
    if ($null -eq $boxes) { return $flags }
    for ($index = 0; $index -lt $boxes.Count; $index++) {
        $toggle = $boxes[$index]
        if ($null -eq $toggle) { continue }
        $flags[[string]$toggle.Tag] = ($toggle.IsChecked -eq $true)
    }
    return $flags
}

function Update-WinToolTerminalSummary {
    if ($script:WinToolTerminalMode -eq "advanced") {
        $list = Get-WinToolUi -Name "TerminalStyleList"
        if ($null -ne $list.SelectedItem -and [string]$list.Tag -eq [string]$script:WinToolTerminalChoice.prompt) {
            $script:WinToolTerminalChoice.promptStyle = [string]$list.SelectedItem.Tag
        }
        $fonts = Get-WinToolUi -Name "TerminalFontList"
        if ($null -ne $fonts.SelectedItem) {
            $script:WinToolTerminalChoice.fontId = [string]$fonts.SelectedItem.Tag
        }
        if ($null -ne $script:WinToolTerminalExtraBox -and $script:WinToolTerminalExtraBox.Count -gt 0) {
            $flags = Read-WinToolExtraSelection
            $script:WinToolTerminalChoice.terminalIcons = [bool]$flags["terminal-icons"]
            $script:WinToolTerminalChoice.psReadLine = [bool]$flags["psreadline"]
            $script:WinToolTerminalChoice.zoxide = [bool]$flags["zoxide"]
            $script:WinToolTerminalChoice.fzf = [bool]$flags["fzf"]
        }
    }
    $steps = @(Get-WinToolTerminalPlan -Selection $script:WinToolTerminalChoice)
    $lines = @($steps | ForEach-Object { [string]$_.Label })
    (Get-WinToolUi -Name "TerminalSummary").Text = ($lines -join "`n")
    $extrasCount = Get-WinToolUi -Name "TerminalExtrasCount"
    if ($null -ne $extrasCount) {
        $flags = Read-WinToolExtraSelection
        $on = 0
        foreach ($flagKey in $flags.Keys) { if ($flags[$flagKey]) { $on++ } }
        $extrasCount.Text = ([string]$on + " of " + [string]$flags.Count + " on")
    }
    $summaryHost = Get-WinToolUi -Name "TerminalSummaryHost"
    if ($null -eq $summaryHost) { return }
    # One wrapping row of chips: what gets installed (+), then what gets changed (~).
    $summaryHost.Children.Clear()
    $summaryHost.ToolTip = ($lines -join "`n")
    $chips = @(Get-WinToolSummaryChip -Step $steps)
    foreach ($kind in @("add", "change")) {
        foreach ($chip in @($chips | Where-Object { $_.Kind -eq $kind })) {
            if ($kind -eq "add") {
                $element = New-WinToolTerminalChip -Text ("+ " + [string]$chip.Text) -Background "BrushOkSoft" -Foreground "BrushOk"
            }
            else {
                $element = New-WinToolTerminalChip -Text ([string][char]0x007E + " " + [string]$chip.Text) -Background "BrushWarnSoft" -Foreground "BrushWarn"
            }
            $element.Tag = [string]$kind
            [void]$summaryHost.Children.Add($element)
        }
    }
}

function Get-WinToolTerminalChoice {
    if ($null -eq $script:WinToolTerminalChoice) {
        $script:WinToolTerminalChoice = Get-WinToolSimpleTerminalChoice
    }
    $enabled = $true
    $enabledBox = $script:WinToolWindow.FindName("TerminalEnabled")
    if ($null -ne $enabledBox) {
        $enabled = ($enabledBox.IsChecked -eq $true)
    }
    $choice = $script:WinToolTerminalChoice
    $fontSize = 12
    $sizeValue = Get-WinToolNote -Object $choice -Name "fontSize"
    if ($null -ne $sizeValue) { $fontSize = [int]$sizeValue }
    return [pscustomobject]@{
        enabled = $enabled
        prompt = [string]$choice.prompt
        promptStyle = [string]$choice.promptStyle
        fontId = [string]$choice.fontId
        fontSize = $fontSize
        schemeId = [string]$choice.schemeId
        terminalIcons = [bool]$choice.terminalIcons
        psReadLine = [bool]$choice.psReadLine
        zoxide = [bool]$choice.zoxide
        fzf = [bool]$choice.fzf
    }
}

function Sync-WinToolTerminalChoice {
    param($Selection)
    if ($null -eq $Selection) { return }
    if ($null -eq $script:WinToolTerminalChoice) {
        $script:WinToolTerminalChoice = Get-WinToolSimpleTerminalChoice
    }
    foreach ($name in @("prompt", "promptStyle", "fontId", "schemeId")) {
        $text = [string](Get-WinToolNote -Object $Selection -Name $name -Default "")
        if (-not [string]::IsNullOrWhiteSpace($text)) { $script:WinToolTerminalChoice.$name = $text }
    }
    $size = Get-WinToolNote -Object $Selection -Name "fontSize"
    if ($null -ne $size -and [int]$size -ge 6 -and [int]$size -le 48) { $script:WinToolTerminalChoice.fontSize = [int]$size }
    foreach ($name in @("terminalIcons", "psReadLine", "zoxide", "fzf")) {
        $flag = Get-WinToolNote -Object $Selection -Name $name
        if ($null -ne $flag) { $script:WinToolTerminalChoice.$name = [bool]$flag }
    }
    $enabledFlag = Get-WinToolNote -Object $Selection -Name "enabled"
    $enabledBox = Get-WinToolUi -Name "TerminalEnabled"
    if ($null -ne $enabledFlag -and $null -ne $enabledBox) {
        $enabledBox.IsChecked = [bool]$enabledFlag
    }
    (Get-WinToolUi -Name "TerminalModeAdvanced").IsChecked = $true
    Update-WinToolExtraToggle
    Update-WinToolFontSizeSelection
    Update-WinToolFontList
    Update-WinToolPromptStyleList
    Update-WinToolPromptSelection
    Update-WinToolSchemeSelection
    Update-WinToolTerminalSummary
    Update-WinToolTerminalPreview
}
# endregion

# region src/UI/UpdatesView.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function Initialize-WinToolUpdateView {
    $catalog = Get-WinToolUpdateCatalog
    $gpus = @(Get-WinToolGpuInfo)
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($gpu in $gpus) {
        $vendor = Resolve-WinToolGpuVendor -Name ([string]$gpu.Name) -Vendor @(Get-WinToolNote -Object $catalog -Name "vendors" -Default @())
        $text = [string]$gpu.Name
        if (-not [string]::IsNullOrWhiteSpace([string]$gpu.DriverVersion)) {
            $text = "{0}  (driver {1})" -f $text, $gpu.DriverVersion
        }
        if ($null -ne $vendor) {
            $text = "{0}  -  {1}" -f $text, [string]$vendor.name
        }
        $lines.Add($text)
    }
    $summary = "Windows did not report a graphics adapter."
    if ($lines.Count -gt 0) {
        $summary = $lines -join [Environment]::NewLine
    }
    (Get-WinToolUi -Name "GpuSummary").Text = $summary

    $panel = Get-WinToolUi -Name "VendorLinks"
    $panel.Children.Clear()
    foreach ($vendor in @(Get-WinToolNote -Object $catalog -Name "vendors" -Default @())) {
        $button = New-Object System.Windows.Controls.Button
        $button.Content = [string]$vendor.name + " downloads"
        $button.Style = $script:WinToolWindow.FindResource("SecondaryButton")
        $button.Margin = [System.Windows.Thickness]::new(0, 0, 8, 8)
        $button.Tag = [string]$vendor.url
        $button.ToolTip = [string](Get-WinToolNote -Object $vendor -Name "note" -Default "")
        Register-WinToolUiEvent -Control $button -EventName "Click" -Name "Updates: vendor downloads" -Data ([string]$vendor.url) -Action {
            param($source, $eventData, $url)
            $null = $source, $eventData
            Open-WinToolUri -Uri $url
        }
        [void]$panel.Children.Add($button)
    }

    Initialize-WinToolUpdateModeView

    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "ScanDrivers") -EventName "Click" -Name "Updates: scan" -Action { Invoke-WinToolScanClick }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "OpenWindowsUpdate") -EventName "Click" -Name "Updates: open Windows Update" -Action { Open-WinToolUri -Uri "ms-settings:windowsupdate" }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "OpenOptionalUpdates") -EventName "Click" -Name "Updates: open optional updates" -Action { Open-WinToolUri -Uri "ms-settings:windowsupdate-optionalupdates" }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "InstallScannedUpdates") -EventName "Click" -Name "Updates: install scanned updates" -Action { Invoke-WinToolInstallUpdatesClick }
}

function Invoke-WinToolScanClick {
    if ($script:WinToolState.Busy) {
        Write-WinToolLog -Message "Wait for the current task to finish." -Level "warn"
        return
    }
    $criteria = "IsInstalled=0 and Type='Driver'"
    if ((Get-WinToolUi -Name "IncludeSoftwareUpdates").IsChecked -eq $true) {
        $criteria = "IsInstalled=0"
    }
    $script:WinToolState.UpdateCriteria = $criteria
    Sync-WinToolBusyState -Busy $true
    Sync-WinToolProgress -Value 0 -Text "Scanning Windows Update" -Indeterminate $true
    Write-WinToolLog -Message "Scanning Windows Update. This can take a few minutes." -Level "info"
    $script:WinToolState.UpdateJob = Start-WinToolScriptJob -ScriptText (Get-WinToolUpdateSearchScript) -Argument @($criteria)
}

function Complete-WinToolUpdateScan {
    $job = $script:WinToolState.UpdateJob
    $ok = $false
    $errorMessage = ""
    $lines = @()
    if ($null -ne $job) {
        $ok = [bool]$job.Sync.Ok
        $errorMessage = [string]$job.Sync.Error
        $lines = @($job.Sync.Lines)
        Stop-WinToolThread -Job $job
    }
    $script:WinToolState.UpdateJob = $null
    if (-not $ok) {
        Sync-WinToolBusyState -Busy $false
        Sync-WinToolProgress -Value 0 -Text "Ready" -Indeterminate $false
        Write-WinToolLog -Message ("Windows Update scan failed. {0}" -f $errorMessage) -Level "error"
        return
    }

    $list = Get-WinToolUi -Name "UpdateList"
    $list.Items.Clear()
    $records = New-Object System.Collections.Generic.List[object]
    foreach ($line in $lines) {
        $text = [string]$line
        $index = $text.IndexOf("`t")
        if ($index -lt 1) {
            continue
        }
        $kind = $text.Substring(0, $index)
        $title = $text.Substring($index + 1)
        $records.Add([pscustomobject]@{
            Kind = $kind
            Title = $title
        })
        [void]$list.Items.Add(("{0}   {1}" -f $kind, $title))
    }
    $script:WinToolState.Updates = $records.ToArray()
    $empty = Get-WinToolUi -Name "UpdateEmpty"
    if ($records.Count -eq 0) {
        $empty.Text = "Windows Update did not offer anything for this scan."
        $empty.Visibility = "Visible"
        Write-WinToolLog -Message "Scan finished. No updates were offered." -Level "ok"
    }
    else {
        $empty.Visibility = "Collapsed"
        Write-WinToolLog -Message ("Scan finished. {0} update(s) listed." -f $records.Count) -Level "ok"
    }
    Sync-WinToolBusyState -Busy $false
    Sync-WinToolProgress -Value 100 -Text "Scan finished" -Indeterminate $false
}

function Invoke-WinToolInstallUpdatesClick {
    if ($script:WinToolState.Busy) {
        Write-WinToolLog -Message "Wait for the current task to finish." -Level "warn"
        return
    }
    $updates = @($script:WinToolState.Updates)
    if ($updates.Count -eq 0) {
        Write-WinToolLog -Message "Scan for updates before installing them." -Level "warn"
        return
    }
    $ok = Request-WinToolConfirmation -Message ("Download and install {0} Windows Update item(s)? The PC may need a restart." -f $updates.Count) -Title "Install updates"
    if (-not $ok) {
        return
    }
    $titles = New-Object System.Collections.Generic.List[string]
    foreach ($item in $updates) {
        $titles.Add([string]$item.Title)
    }
    $criteria = [string]$script:WinToolState.UpdateCriteria
    if ([string]::IsNullOrWhiteSpace($criteria)) {
        $criteria = "IsInstalled=0 and Type='Driver'"
        if ((Get-WinToolUi -Name "IncludeSoftwareUpdates").IsChecked -eq $true) {
            $criteria = "IsInstalled=0"
        }
    }
    Sync-WinToolBusyState -Busy $true
    Sync-WinToolProgress -Value 0 -Text "Installing Windows updates" -Indeterminate $true
    Write-WinToolLog -Message "Downloading and installing the scanned updates." -Level "info"
    $script:WinToolState.InstallJob = Start-WinToolScriptJob -ScriptText (Get-WinToolUpdateInstallScript) -Argument @($criteria, ($titles -join "`n"))
}

function Complete-WinToolUpdateInstall {
    $job = $script:WinToolState.InstallJob
    $ok = $false
    $errorMessage = ""
    $count = 0
    $reboot = $false
    if ($null -ne $job) {
        $ok = [bool]$job.Sync.Ok
        $errorMessage = [string]$job.Sync.Error
        if ($null -ne $job.Sync.Count) { $count = [int]$job.Sync.Count }
        if ($null -ne $job.Sync.Reboot) { $reboot = [bool]$job.Sync.Reboot }
        Stop-WinToolThread -Job $job
    }
    $script:WinToolState.InstallJob = $null
    Sync-WinToolBusyState -Busy $false
    Sync-WinToolProgress -Value 0 -Text "Ready" -Indeterminate $false
    if (-not $ok) {
        Write-WinToolLog -Message ("Update install failed. {0}" -f $errorMessage) -Level "error"
        return
    }
    if ($count -eq 0) {
        Write-WinToolLog -Message "Those updates were no longer offered when the install started." -Level "warn"
        return
    }
    $script:WinToolState.Updates = @()
    (Get-WinToolUi -Name "UpdateList").Items.Clear()
    (Get-WinToolUi -Name "InstallScannedUpdates").IsEnabled = $false
    $empty = Get-WinToolUi -Name "UpdateEmpty"
    $empty.Text = ("Installed {0} update(s). Scan again to check for more." -f $count)
    $empty.Visibility = "Visible"
    Write-WinToolLog -Message ("Finished installing {0} update(s)." -f $count) -Level "ok"
    if ($reboot) {
        Write-WinToolLog -Message "Windows asked for a restart to finish the updates." -Level "warn"
    }
}

function Initialize-WinToolUpdateModeView {
    $list = Get-WinToolUi -Name "UpdateModeList"
    $list.Children.Clear()
    $radios = New-Object System.Collections.Generic.List[object]
    foreach ($mode in (Get-WinToolUpdateMode)) {
        $radio = New-Object System.Windows.Controls.RadioButton
        $radio.GroupName = "WinToolUpdateMode"
        $radio.Tag = [string]$mode.id
        $radio.Margin = [System.Windows.Thickness]::new(0, 0, 0, 10)
        $content = New-Object System.Windows.Controls.StackPanel
        [void]$content.Children.Add((New-WinToolText -Text ([string]$mode.name) -Weight "SemiBold"))
        [void]$content.Children.Add((New-WinToolText -Text ([string]$mode.description) -Brush "BrushMuted" -Wrap -Margin ([System.Windows.Thickness]::new(0, 2, 0, 0))))
        $radio.Content = $content
        Register-WinToolUiEvent -Control $radio -EventName "Checked" -Name "Updates: pick mode" -Data ([string]$mode.id) -Action {
            param($source, $eventData, $modeId)
            $null = $source, $eventData
            $script:WinToolState.UpdateMode = $modeId
        }
        [void]$list.Children.Add($radio)
        $radios.Add($radio)
    }
    $script:WinToolState.UpdateModeRadios = $radios.ToArray()
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "ApplyUpdateMode") -EventName "Click" -Name "Updates: apply mode" -Action {
        Invoke-WinToolUpdateModeClick -ModeId ([string]$script:WinToolState.UpdateMode)
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "RevertUpdateMode") -EventName "Click" -Name "Updates: back to default" -Action {
        Invoke-WinToolUpdateModeClick -ModeId "default"
    }
    Sync-WinToolUpdateMode
}

function Sync-WinToolUpdateMode {
    $current = "default"
    if (Test-WinToolWindows) {
        $snapshot = Get-WinToolUpdateModeSnapshot
        $current = Resolve-WinToolUpdateMode -Values $snapshot.Values -Services $snapshot.Services
    }
    $label = "Custom (policies set outside WinTool)"
    $mode = Find-WinToolUpdateMode -Id $current
    if ($null -ne $mode) {
        $label = [string]$mode.name
    }
    (Get-WinToolUi -Name "UpdateModeCurrent").Text = "Current mode: " + $label
    $script:WinToolState.UpdateModeCurrent = $current
    $script:WinToolState.UpdateMode = $current
    foreach ($radio in @($script:WinToolState.UpdateModeRadios)) {
        $radio.IsChecked = ([string]$radio.Tag -eq $current)
    }
}

function Invoke-WinToolUpdateModeClick {
    param(
        [string]$ModeId
    )
    if ($script:WinToolState.Busy) {
        Write-WinToolLog -Message "Wait for the current task to finish." -Level "warn"
        return
    }
    $mode = $null
    if (-not [string]::IsNullOrWhiteSpace($ModeId)) {
        $mode = Find-WinToolUpdateMode -Id $ModeId
    }
    if ($null -eq $mode) {
        Write-WinToolLog -Message "Pick an update mode first." -Level "warn"
        return
    }
    $message = "Set Windows Update to: {0}?`n`n{1}" -f [string]$mode.name, [string]$mode.description
    if ($ModeId -eq "disabled") {
        $message += "`n`nThis is not recommended. Use Back to default to undo it."
    }
    $ok = Request-WinToolConfirmation -Message $message -Title "Update mode"
    if (-not $ok) {
        return
    }
    $steps = @(Get-WinToolUpdateModePlan -ModeId $ModeId)
    Invoke-WinToolPlanAsync -Step $steps -DoneMessage ("Windows Update mode set to " + [string]$mode.name + ".") -AfterDone "Sync-WinToolUpdateMode"
}
# endregion

# region src/UI/FixesView.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function Initialize-WinToolFixView {
    $hostPanel = Get-WinToolUi -Name "FixList"
    $hostPanel.Children.Clear()
    foreach ($fix in @(Get-WinToolNote -Object (Get-WinToolFixCatalog) -Name "fixes" -Default @())) {
        $card = New-WinToolCard
        $grid = New-Object System.Windows.Controls.Grid
        $grid.ColumnDefinitions.Add((New-WinToolColumn))
        $grid.ColumnDefinitions.Add((New-WinToolColumn -Auto))
        $text = New-Object System.Windows.Controls.StackPanel
        $title = New-Object System.Windows.Controls.StackPanel
        $title.Orientation = "Horizontal"
        [void]$title.Children.Add((New-WinToolText -Text ([string]$fix.name) -Weight "SemiBold"))
        if ([bool](Get-WinToolNote -Object $fix -Name "restart" -Default $false)) {
            [void]$title.Children.Add((New-WinToolBadge -Text "Restart needed" -Kind "caution"))
        }
        [void]$text.Children.Add($title)
        [void]$text.Children.Add((New-WinToolText -Text ([string]$fix.description) -Brush "BrushMuted" -Wrap -Margin ([System.Windows.Thickness]::new(0, 4, 16, 0))))
        [System.Windows.Controls.Grid]::SetColumn($text, 0)
        [void]$grid.Children.Add($text)
        $button = New-Object System.Windows.Controls.Button
        $button.Content = "Run"
        $button.Style = $script:WinToolWindow.FindResource("SecondaryButton")
        $button.VerticalAlignment = "Center"
        [System.Windows.Controls.Grid]::SetColumn($button, 1)
        [void]$grid.Children.Add($button)
        Register-WinToolUiEvent -Control $button -EventName "Click" -Name ("Fixes: " + [string]$fix.name) -Data $fix -Action {
            param($source, $eventData, $boundFix)
            $null = $source, $eventData
            Invoke-WinToolFixClick -Fix $boundFix
        }
        Add-WinToolBusyControl -Control $button
        $card.Child = $grid
        [void]$hostPanel.Children.Add($card)
    }
}

function Invoke-WinToolFixClick {
    param(
        [Parameter(Mandatory = $true)]$Fix
    )
    if ($script:WinToolState.Busy) {
        Write-WinToolLog -Message "Wait for the current task to finish." -Level "warn"
        return
    }
    $message = ([string]$Fix.name) + "?`n`n" + ([string]$Fix.description)
    $restart = [bool](Get-WinToolNote -Object $Fix -Name "restart" -Default $false)
    if ($restart) {
        $message += "`n`nRestart the PC when it finishes."
    }
    $ok = Request-WinToolConfirmation -Message $message -Title ([string]$Fix.name)
    if (-not $ok) {
        return
    }
    $done = ([string]$Fix.name) + " finished."
    if ($restart) {
        $done += " Restart the PC to complete it."
    }
    Invoke-WinToolPlanAsync -Step @(Get-WinToolFixPlan -Fix $Fix) -DoneMessage $done
}
# endregion

# region src/UI/FeaturesView.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function Initialize-WinToolFeatureView {
    $hostPanel = Get-WinToolUi -Name "FeatureList"
    $hostPanel.Children.Clear()
    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($feature in @(Get-WinToolNote -Object (Get-WinToolFeatureCatalog) -Name "features" -Default @())) {
        $panel = New-Object System.Windows.Controls.Grid
        $panel.Margin = [System.Windows.Thickness]::new(0, 0, 0, 12)
        $panel.ColumnDefinitions.Add((New-WinToolColumn -Auto))
        $panel.ColumnDefinitions.Add((New-WinToolColumn))
        $panel.ColumnDefinitions.Add((New-WinToolColumn -Auto))
        $checkbox = New-Object System.Windows.Controls.CheckBox
        $checkbox.VerticalAlignment = "Top"
        $checkbox.Margin = [System.Windows.Thickness]::new(0, 2, 10, 0)
        $checkbox.IsEnabled = $false
        [System.Windows.Controls.Grid]::SetColumn($checkbox, 0)
        [void]$panel.Children.Add($checkbox)
        $text = New-Object System.Windows.Controls.StackPanel
        [void]$text.Children.Add((New-WinToolText -Text ([string]$feature.name) -Weight "SemiBold"))
        [void]$text.Children.Add((New-WinToolText -Text ([string]$feature.description) -Brush "BrushMuted" -Wrap -Margin ([System.Windows.Thickness]::new(0, 2, 16, 0))))
        [System.Windows.Controls.Grid]::SetColumn($text, 1)
        [void]$panel.Children.Add($text)
        $state = New-WinToolText -Text "Checking..." -Brush "BrushMuted"
        $state.VerticalAlignment = "Top"
        # A fixed width: "Checking..." and the final state take the same room,
        # so the descriptions never re-wrap and the rows never move.
        $state.Width = 140
        $state.TextAlignment = "Right"
        [System.Windows.Controls.Grid]::SetColumn($state, 2)
        [void]$panel.Children.Add($state)
        [void]$hostPanel.Children.Add($panel)
        $rows.Add([pscustomobject]@{
            Feature = $feature
            Checkbox = $checkbox
            StateText = $state
            Status = "Unknown"
        })
    }
    $script:WinToolState.FeatureRows = $rows.ToArray()
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "FeatureRefresh") -EventName "Click" -Name "Features: refresh state" -Action {
        Start-WinToolFeatureDetection
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "FeatureApply") -EventName "Click" -Name "Features: apply changes" -Action {
        Invoke-WinToolFeatureApplyClick
    }
}

$script:WinToolFeatureTimeoutSeconds = 120

function Start-WinToolFeatureDetection {
    if ($null -ne $script:WinToolState.FeatureJob -or $script:WinToolState.Busy) {
        return
    }
    if (-not (Test-WinToolWindows)) {
        return
    }
    (Get-WinToolUi -Name "FeatureRefresh").IsEnabled = $false
    $names = New-Object System.Collections.Generic.List[string]
    foreach ($row in @($script:WinToolState.FeatureRows)) {
        $row.StateText.Text = "Checking..."
        $row.Checkbox.IsEnabled = $false
        foreach ($name in @($row.Feature.names)) {
            $names.Add([string]$name)
        }
    }
    (Get-WinToolUi -Name "FeatureStatus").Text = "Reading the current state..."
    $job = Start-WinToolScriptJob -ScriptText (Get-WinToolFeatureStateScript) -Argument @(, $names.ToArray())
    $job | Add-Member -NotePropertyName Started -NotePropertyValue ([DateTime]::UtcNow)
    $script:WinToolState.FeatureJob = $job
}

function Test-WinToolFeatureDetectionTimeout {
    $job = $script:WinToolState.FeatureJob
    if ($null -eq $job -or $job.Sync.Done) {
        return
    }
    if (([DateTime]::UtcNow - $job.Started).TotalSeconds -lt $script:WinToolFeatureTimeoutSeconds) {
        return
    }
    Stop-WinToolThread -Job $job
    $script:WinToolState.FeatureJob = $null
    (Get-WinToolUi -Name "FeatureRefresh").IsEnabled = (-not $script:WinToolState.Busy)
    (Get-WinToolUi -Name "FeatureStatus").Text = "Reading Windows features took too long. Press Refresh to try again."
    Write-WinToolLog -Message "Windows features check timed out. Press Refresh to try again." -Level "warn"
}

function Complete-WinToolFeatureDetection {
    $job = $script:WinToolState.FeatureJob
    if ($null -eq $job) {
        return
    }
    $ok = [bool]$job.Sync.Ok
    $errorMessage = [string]$job.Sync.Error
    $states = $job.Sync.States
    Stop-WinToolThread -Job $job
    $script:WinToolState.FeatureJob = $null
    (Get-WinToolUi -Name "FeatureRefresh").IsEnabled = (-not $script:WinToolState.Busy)
    if (-not $ok) {
        (Get-WinToolUi -Name "FeatureStatus").Text = "Could not read the Windows features."
        Write-WinToolLog -Message ("Could not read the Windows features. {0}" -f $errorMessage) -Level "warn"
        return
    }
    Set-WinToolFeatureState -State $states
}

function Set-WinToolFeatureState {
    param([hashtable]$State)
    $on = 0
    foreach ($row in @($script:WinToolState.FeatureRows)) {
        $status = Get-WinToolFeatureStatus -Feature $row.Feature -State $State
        $row.Status = $status
        switch ($status) {
            "On" { $row.StateText.Text = "On"; $on++ }
            "Off" { $row.StateText.Text = "Off" }
            "Partial" { $row.StateText.Text = "Partly on" }
            default { $row.StateText.Text = "Not available on this PC" }
        }
        $row.Checkbox.IsEnabled = ($status -ne "Unavailable")
        $row.Checkbox.IsChecked = ($status -eq "On")
    }
    (Get-WinToolUi -Name "FeatureStatus").Text = ("{0} of these features are on. Tick or untick, then apply." -f $on)
}

function Get-WinToolFeatureChange {
    $enable = New-Object System.Collections.Generic.List[object]
    $disable = New-Object System.Collections.Generic.List[object]
    foreach ($row in @($script:WinToolState.FeatureRows)) {
        if ($row.Status -eq "Unavailable" -or $row.Status -eq "Unknown") {
            continue
        }
        $wanted = ($row.Checkbox.IsChecked -eq $true)
        if ($wanted -and $row.Status -ne "On") {
            $enable.Add($row.Feature)
        }
        elseif (-not $wanted -and $row.Status -ne "Off") {
            $disable.Add($row.Feature)
        }
    }
    return [pscustomobject]@{
        Enable = $enable.ToArray()
        Disable = $disable.ToArray()
    }
}

function Invoke-WinToolFeatureApplyClick {
    if ($script:WinToolState.Busy) {
        Write-WinToolLog -Message "Wait for the current task to finish." -Level "warn"
        return
    }
    $change = Get-WinToolFeatureChange
    $total = @($change.Enable).Count + @($change.Disable).Count
    if ($total -eq 0) {
        Write-WinToolLog -Message "No Windows feature changes to apply." -Level "warn"
        return
    }
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($feature in @($change.Enable)) { $lines.Add("Turn on: " + [string]$feature.name) }
    foreach ($feature in @($change.Disable)) { $lines.Add("Turn off: " + [string]$feature.name) }
    $ok = Request-WinToolConfirmation -Message ("Change these Windows features?`n`n" + ($lines -join "`n") + "`n`nWindows needs a restart to finish.") -Title "Windows features"
    if (-not $ok) {
        return
    }
    $steps = @(Get-WinToolFeaturePlan -Enable $change.Enable -Disable $change.Disable)
    Invoke-WinToolPlanAsync -Step $steps -DoneMessage "Windows features changed. Restart the PC to finish." -AfterDone "Start-WinToolFeatureDetection"
}
# endregion

# region src/UI/ConfigView.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function Initialize-WinToolConfigView {
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "SaveProfile") -EventName "Click" -Name "Config: save profile" -Action { Invoke-WinToolSaveProfile }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "LoadProfile") -EventName "Click" -Name "Config: load profile" -Action { Invoke-WinToolLoadProfile }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "ExportWinget") -EventName "Click" -Name "Config: export winget list" -Action { Invoke-WinToolExportWinget }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "ImportWinget") -EventName "Click" -Name "Config: import winget list" -Action { Invoke-WinToolImportWinget }
    Initialize-WinToolSystemView
    Update-WinToolProfileSummary
}

function Update-WinToolProfileSummary {
    $apps = @(Get-WinToolCheckedApp)
    $tweaks = @(Get-WinToolCheckedTweak)
    $terminal = Get-WinToolTerminalChoice
    $prompt = "Oh My Posh"
    foreach ($entry in @(Get-WinToolNote -Object (Get-WinToolTerminalCatalog) -Name "prompts" -Default @())) {
        if ([string]$entry.id -eq [string]$terminal.prompt) {
            $prompt = [string]$entry.name
            break
        }
    }
    $replay = "Terminal setup is saved with the profile."
    if (-not $terminal.enabled) {
        $replay = "Terminal setup is not included when this profile is replayed."
    }
    $text = "{0} apps selected, {1} tweaks on. Prompt: {2}. {3}" -f $apps.Count, $tweaks.Count, $prompt, $replay
    (Get-WinToolUi -Name "ProfileSummary").Text = $text
}

function Get-WinToolProfileFromUi {
    if (-not $script:WinToolState.TweakStateRead) {
        Update-WinToolTweakState
    }
    $apps = @(Get-WinToolCheckedApp)
    $tweaks = @(Get-WinToolCheckedTweak)
    $appIds = New-Object System.Collections.Generic.List[string]
    foreach ($app in $apps) {
        $appIds.Add([string]$app.Id)
    }
    $tweakIds = New-Object System.Collections.Generic.List[string]
    foreach ($tweak in $tweaks) {
        $tweakIds.Add([string]$tweak.id)
    }
    return (ConvertTo-WinToolProfile -AppId $appIds.ToArray() -TweakId $tweakIds.ToArray() -Terminal (Get-WinToolTerminalChoice) -Name "My WinTool profile")
}

function Import-WinToolProfileToUi {
    param(
        [Parameter(Mandatory = $true)][string]$Path
    )
    $toolProfile = Read-WinToolProfile -Path $Path
    $resolved = Resolve-WinToolProfileSelection -Profile $toolProfile
    foreach ($id in @($resolved.UnknownApps)) {
        Write-WinToolLog -Message "Unknown app id '$id' in the profile." -Level "warn"
    }
    foreach ($id in @($resolved.UnknownTweaks)) {
        Write-WinToolLog -Message "Unknown tweak id '$id' in the profile." -Level "warn"
    }
    $appIds = New-Object System.Collections.Generic.List[string]
    foreach ($app in @($resolved.AppRecords)) {
        $appIds.Add([string]$app.id)
    }
    $tweakIds = New-Object System.Collections.Generic.List[string]
    foreach ($tweak in @($resolved.TweakRecords)) {
        $tweakIds.Add([string]$tweak.id)
    }
    Sync-WinToolAppCheck -Id $appIds.ToArray() -OnlyThese
    Sync-WinToolTweakCheck -Id $tweakIds.ToArray() -OnlyThese
    Sync-WinToolTerminalChoice -Selection (Get-WinToolNote -Object $toolProfile -Name "terminal")
    Update-WinToolProfileSummary
    Write-WinToolLog -Message ("Loaded {0}. Nothing was installed yet." -f $Path) -Level "ok"
}

function Invoke-WinToolSaveProfile {
    if ($script:WinToolState.Busy) {
        Write-WinToolLog -Message "Wait for the current task to finish." -Level "warn"
        return
    }
    $dialog = New-Object Microsoft.Win32.SaveFileDialog
    $dialog.Filter = "WinTool profile (*.json)|*.json"
    $dialog.FileName = "wintool-profile.json"
    $dialog.Title = "Save WinTool profile"
    $accepted = $dialog.ShowDialog($script:WinToolWindow)
    if ($accepted -ne $true) {
        return
    }
    try {
        $toolProfile = Get-WinToolProfileFromUi
        Write-WinToolProfile -Path $dialog.FileName -Profile $toolProfile
        Write-WinToolLog -Message ("Saved profile to {0}" -f $dialog.FileName) -Level "ok"
    }
    catch {
        Write-WinToolLog -Message ("Could not save that profile. {0}" -f $_.Exception.Message) -Level "error"
    }
}

function Invoke-WinToolLoadProfile {
    if ($script:WinToolState.Busy) {
        Write-WinToolLog -Message "Wait for the current task to finish." -Level "warn"
        return
    }
    $dialog = New-Object Microsoft.Win32.OpenFileDialog
    $dialog.Filter = "WinTool profile (*.json)|*.json"
    $dialog.Title = "Load WinTool profile"
    $accepted = $dialog.ShowDialog($script:WinToolWindow)
    if ($accepted -ne $true) {
        return
    }
    try {
        Import-WinToolProfileToUi -Path $dialog.FileName
    }
    catch {
        Write-WinToolLog -Message ("Could not load that profile. {0}" -f $_.Exception.Message) -Level "error"
    }
}

function Invoke-WinToolExportWinget {
    if ($script:WinToolState.Busy) {
        Write-WinToolLog -Message "Wait for the current task to finish." -Level "warn"
        return
    }
    $winget = Get-WinToolWingetPath
    if ([string]::IsNullOrWhiteSpace($winget)) {
        Write-WinToolLog -Message "winget was not found. Install App Installer from the Microsoft Store, then try again." -Level "warn"
        return
    }
    $dialog = New-Object Microsoft.Win32.SaveFileDialog
    $dialog.Filter = "winget package list (*.json)|*.json"
    $dialog.FileName = "winget-packages.json"
    $dialog.Title = "Export winget package list"
    $accepted = $dialog.ShowDialog($script:WinToolWindow)
    if ($accepted -ne $true) {
        return
    }
    $step = [pscustomobject]@{
        Type = "process"
        Label = "Export winget packages"
        FilePath = $winget
        Arguments = @("export", "-o", $dialog.FileName, "--accept-source-agreements")
    }
    Invoke-WinToolPlanAsync -Step @($step) -DoneMessage "winget export finished."
}

function Invoke-WinToolImportWinget {
    if ($script:WinToolState.Busy) {
        Write-WinToolLog -Message "Wait for the current task to finish." -Level "warn"
        return
    }
    $winget = Get-WinToolWingetPath
    if ([string]::IsNullOrWhiteSpace($winget)) {
        Write-WinToolLog -Message "winget was not found. Install App Installer from the Microsoft Store, then try again." -Level "warn"
        return
    }
    $dialog = New-Object Microsoft.Win32.OpenFileDialog
    $dialog.Filter = "winget package list (*.json)|*.json"
    $dialog.Title = "Import winget package list"
    $accepted = $dialog.ShowDialog($script:WinToolWindow)
    if ($accepted -ne $true) {
        return
    }
    $ok = Request-WinToolConfirmation -Message "Ask winget to install every package in this file?" -Title "Import winget list"
    if (-not $ok) {
        return
    }
    $step = [pscustomobject]@{
        Type = "process"
        Label = "Import winget packages"
        FilePath = $winget
        Arguments = @("import", "-i", $dialog.FileName, "--accept-package-agreements", "--accept-source-agreements", "--disable-interactivity")
    }
    Invoke-WinToolPlanAsync -Step @($step) -DoneMessage "winget import finished." -AfterDone "Start-WinToolAppDetection"
}

function Initialize-WinToolSystemView {
    $catalog = Get-WinToolSystemCatalog
    $providerBox = Get-WinToolUi -Name "DnsProvider"
    $providerBox.Items.Clear()
    foreach ($provider in (Get-WinToolDnsProvider -Catalog $catalog)) {
        $item = New-Object System.Windows.Controls.ComboBoxItem
        $item.Content = [string]$provider.name
        $item.Tag = [string]$provider.id
        $item.ToolTip = [string](Get-WinToolNote -Object $provider -Name "description" -Default "")
        [void]$providerBox.Items.Add($item)
    }
    $providerBox.SelectedIndex = 0
    $plan = Get-WinToolNote -Object $catalog -Name "powerPlan"
    (Get-WinToolUi -Name "PowerPlanDescription").Text = [string]$plan.description

    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "DnsAdapter") -EventName "SelectionChanged" -Name "Config: pick adapter" -Action { Sync-WinToolDnsSummary }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "RefreshDns") -EventName "Click" -Name "Config: refresh adapters" -Action { Update-WinToolSystemView }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "ApplyDns") -EventName "Click" -Name "Config: apply DNS" -Action { Invoke-WinToolDnsClick }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "AddUltimatePlan") -EventName "Click" -Name "Config: add Ultimate Performance" -Action { Invoke-WinToolPowerPlanClick -Action "add" }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "RemoveUltimatePlan") -EventName "Click" -Name "Config: remove Ultimate Performance" -Action { Invoke-WinToolPowerPlanClick -Action "remove" }
}

function Update-WinToolSystemView {
    $adapters = @()
    try {
        $adapters = @(Get-WinToolDnsAdapter)
    }
    catch {
        Write-WinToolLog -Message ("Could not read network adapters. " + $_.Exception.Message) -Level "warn"
    }
    $script:WinToolState.DnsAdapters = $adapters
    $box = Get-WinToolUi -Name "DnsAdapter"
    $box.Items.Clear()
    if ($adapters.Count -gt 1) {
        $all = New-Object System.Windows.Controls.ComboBoxItem
        $all.Content = "All connected adapters"
        $all.Tag = -1
        [void]$box.Items.Add($all)
    }
    foreach ($adapter in $adapters) {
        $item = New-Object System.Windows.Controls.ComboBoxItem
        $item.Content = ("{0}  -  {1}" -f [string]$adapter.Name, [string]$adapter.Description)
        $item.Tag = [int]$adapter.Index
        [void]$box.Items.Add($item)
    }
    if ($box.Items.Count -gt 0) {
        $box.SelectedIndex = 0
    }
    Sync-WinToolDnsSummary
    Sync-WinToolPowerPlanStatus
}

function Get-WinToolSelectedDnsAdapter {
    $item = (Get-WinToolUi -Name "DnsAdapter").SelectedItem
    if ($null -eq $item) {
        return @()
    }
    $index = [int]$item.Tag
    $list = New-Object System.Collections.Generic.List[object]
    foreach ($adapter in @($script:WinToolState.DnsAdapters)) {
        if ($index -eq -1 -or [int]$adapter.Index -eq $index) {
            $list.Add($adapter)
        }
    }
    return $list.ToArray()
}

function Sync-WinToolDnsSummary {
    $selected = @(Get-WinToolSelectedDnsAdapter)
    $text = "No connected network adapter found."
    if ($selected.Count -gt 0) {
        $lines = New-Object System.Collections.Generic.List[string]
        foreach ($adapter in $selected) {
            $lines.Add((Format-WinToolDnsSummary -Adapter $adapter))
        }
        $text = "Now: " + ($lines -join [Environment]::NewLine)
    }
    (Get-WinToolUi -Name "DnsCurrent").Text = $text
}

function Sync-WinToolPowerPlanStatus {
    $text = "Power plans are only on Windows."
    $script:WinToolState.UltimatePlanAdded = $false
    if (Test-WinToolWindows) {
        try {
            $schemes = ConvertFrom-WinToolPowerList -Text ((& powercfg.exe /list) | Out-String)
            $catalog = Get-WinToolSystemCatalog
            $state = Get-WinToolPowerPlanState -Scheme $schemes -Catalog $catalog
            $text = Format-WinToolPowerPlanStatus -State $state -Name ([string]$catalog.powerPlan.name)
            $script:WinToolState.UltimatePlanAdded = [bool]$state.Added
        }
        catch {
            $text = "Could not read power plans. " + $_.Exception.Message
        }
    }
    (Get-WinToolUi -Name "RemoveUltimatePlan").IsEnabled = (-not $script:WinToolState.Busy -and [bool]$script:WinToolState.UltimatePlanAdded)
    (Get-WinToolUi -Name "PowerPlanStatus").Text = $text
}

function Invoke-WinToolDnsClick {
    if ($script:WinToolState.Busy) {
        Write-WinToolLog -Message "Wait for the current task to finish." -Level "warn"
        return
    }
    $adapters = @(Get-WinToolSelectedDnsAdapter)
    if ($adapters.Count -eq 0) {
        Write-WinToolLog -Message "Pick a network adapter first." -Level "warn"
        return
    }
    $item = (Get-WinToolUi -Name "DnsProvider").SelectedItem
    if ($null -eq $item) {
        Write-WinToolLog -Message "Pick a DNS provider first." -Level "warn"
        return
    }
    $provider = Find-WinToolDnsProvider -Id ([string]$item.Tag)
    $ipv6 = ((Get-WinToolUi -Name "DnsIncludeIpv6").IsChecked -eq $true)
    $servers = @(Get-WinToolDnsServerList -Provider $provider -IncludeIpv6 $ipv6)
    $what = "automatic (DHCP)"
    if ($servers.Count -gt 0) {
        $what = [string]$provider.name + " (" + ($servers -join ", ") + ")"
    }
    $names = (@($adapters | ForEach-Object { [string]$_.Name })) -join ", "
    $ok = Request-WinToolConfirmation -Message ("Set DNS on {0} to {1}?" -f $names, $what) -Title "DNS servers"
    if (-not $ok) {
        return
    }
    $steps = @(Get-WinToolDnsPlan -Adapter $adapters -Provider $provider -IncludeIpv6 $ipv6)
    Invoke-WinToolPlanAsync -Step $steps -DoneMessage "DNS servers changed." -AfterDone "Update-WinToolSystemView"
}

function Invoke-WinToolPowerPlanClick {
    param(
        [Parameter(Mandatory = $true)][ValidateSet("add", "remove")][string]$Action
    )
    if ($script:WinToolState.Busy) {
        Write-WinToolLog -Message "Wait for the current task to finish." -Level "warn"
        return
    }
    $message = "Add the Ultimate Performance power plan and switch to it?"
    if ($Action -eq "remove") {
        $message = "Remove the Ultimate Performance plan WinTool added? If it is active, Windows goes back to Balanced."
    }
    $ok = Request-WinToolConfirmation -Message $message -Title "Power plan"
    if (-not $ok) {
        return
    }
    $steps = @(Get-WinToolPowerPlanPlan -Action $Action)
    Invoke-WinToolPlanAsync -Step $steps -DoneMessage "Power plan updated." -AfterDone "Sync-WinToolPowerPlanStatus"
}
# endregion

# region src/UI/HomeView.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

# The Home page: a score ring, five checks in a fixed order and three small
# cards. Every state (analyzing, done, fixing) uses the same slots, so only
# the content inside them changes.

function Get-WinToolHomeEllipsis {
    return [string][char]0x2026
}

function Test-WinToolHomeReduceMotion {
    if ($script:WinToolHomeReduceMotion) { return $true }
    try { return (-not [System.Windows.SystemParameters]::ClientAreaAnimation) } catch { return $false }
}

function New-WinToolHomeBrush {
    param([string]$From, [string]$To, [switch]$Vertical, [double]$Alpha = 1)
    $brush = New-Object System.Windows.Media.LinearGradientBrush
    $brush.StartPoint = [System.Windows.Point]::new(0, 0)
    if ($Vertical) { $brush.EndPoint = [System.Windows.Point]::new(0, 1) } else { $brush.EndPoint = [System.Windows.Point]::new(1, 1) }
    $first = [System.Windows.Media.ColorConverter]::ConvertFromString($From)
    $second = [System.Windows.Media.ColorConverter]::ConvertFromString($To)
    if ($Alpha -lt 1) {
        $first = [System.Windows.Media.Color]::FromArgb([byte][Math]::Round(255 * $Alpha), $first.R, $first.G, $first.B)
        $second = [System.Windows.Media.Color]::FromArgb([byte]0, $second.R, $second.G, $second.B)
    }
    $brush.GradientStops.Add((New-Object System.Windows.Media.GradientStop($first, 0)))
    $brush.GradientStops.Add((New-Object System.Windows.Media.GradientStop($second, 1)))
    return $brush
}

function Get-WinToolHomeArcData {
    # Path data for an arc that starts at the top and runs clockwise.
    param([double]$CenterX, [double]$CenterY, [double]$Radius, [double]$Angle)
    $culture = [System.Globalization.CultureInfo]::InvariantCulture
    $sweep = [Math]::Max(0.5, [Math]::Min(359.6, $Angle))
    $radians = $sweep * [Math]::PI / 180
    $x = $CenterX + $Radius * [Math]::Sin($radians)
    $y = $CenterY - $Radius * [Math]::Cos($radians)
    $large = 0
    if ($sweep -gt 180) { $large = 1 }
    $text = [string]::Format($culture, "M {0},{1} A {2},{2} 0 {3} 1 {4:0.###},{5:0.###}", $CenterX, ($CenterY - $Radius), $Radius, $large, $x, $y)
    return [pscustomobject]@{ Data = $text; X = $x; Y = $y }
}

function Set-WinToolHomeArc {
    param([double]$Angle)
    $hs = $script:WinToolState.Home
    $hs.Arc = $Angle
    $arc = Get-WinToolUi -Name "HomeArc"
    $cap = Get-WinToolUi -Name "HomeArcCap"
    if ($Angle -lt 1) {
        $arc.Visibility = "Hidden"
        $cap.Visibility = "Hidden"
        return
    }
    $shape = Get-WinToolHomeArcData -CenterX 118 -CenterY 118 -Radius 94 -Angle $Angle
    $arc.Data = [System.Windows.Media.Geometry]::Parse($shape.Data)
    [System.Windows.Controls.Canvas]::SetLeft($cap, $shape.X - 6)
    [System.Windows.Controls.Canvas]::SetTop($cap, $shape.Y - 6)
    $arc.Visibility = "Visible"
    $cap.Visibility = "Visible"
}

function New-WinToolHomeRow {
    param(
        [Parameter(Mandatory = $true)]$Check,
        [bool]$Last
    )
    $border = New-Object System.Windows.Controls.Border
    $border.Height = 56
    $border.Padding = [System.Windows.Thickness]::new(14, 0, 14, 0)
    if (-not $Last) {
        $border.BorderThickness = [System.Windows.Thickness]::new(0, 0, 0, 1)
        $border.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, "BrushLine")
    }
    $grid = New-Object System.Windows.Controls.Grid
    foreach ($width in @(28, 12, -1, 12, 76)) {
        $column = New-Object System.Windows.Controls.ColumnDefinition
        if ($width -lt 0) { $column.Width = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star) }
        else { $column.Width = [System.Windows.GridLength]::new($width) }
        $grid.ColumnDefinitions.Add($column)
    }
    $border.Child = $grid

    $content = New-Object System.Windows.Controls.Grid
    [System.Windows.Controls.Grid]::SetColumnSpan($content, 3)
    $null = $grid.Children.Add($content)
    foreach ($width in @(28, 12, -1)) {
        $column = New-Object System.Windows.Controls.ColumnDefinition
        if ($width -lt 0) { $column.Width = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star) }
        else { $column.Width = [System.Windows.GridLength]::new($width) }
        $content.ColumnDefinitions.Add($column)
    }

    $icon = New-Object System.Windows.Controls.Grid
    $icon.Width = 22
    $icon.Height = 22
    $icon.VerticalAlignment = "Center"
    $disc = New-Object System.Windows.Shapes.Ellipse
    $disc.Width = 22
    $disc.Height = 22
    $glyph = New-Object System.Windows.Shapes.Path
    $glyph.StrokeThickness = 2
    $glyph.StrokeStartLineCap = "Round"
    $glyph.StrokeEndLineCap = "Round"
    $glyph.StrokeLineJoin = "Round"
    $spinner = New-Object System.Windows.Shapes.Path
    $spinner.StrokeThickness = 2
    $spinner.StrokeStartLineCap = "Round"
    $spinner.StrokeEndLineCap = "Round"
    $spinner.Data = [System.Windows.Media.Geometry]::Parse("M 11,3 A 8,8 0 0 1 19,11")
    $spinner.SetResourceReference([System.Windows.Shapes.Shape]::StrokeProperty, "BrushAccent")
    $spinner.RenderTransformOrigin = [System.Windows.Point]::new(0.5, 0.5)
    $spinner.RenderTransform = New-Object System.Windows.Media.RotateTransform(0)
    $spinner.Width = 22
    $spinner.Height = 22
    $null = $icon.Children.Add($disc)
    $null = $icon.Children.Add($glyph)
    $null = $icon.Children.Add($spinner)
    $null = $content.Children.Add($icon)

    $text = New-Object System.Windows.Controls.StackPanel
    $text.VerticalAlignment = "Center"
    [System.Windows.Controls.Grid]::SetColumn($text, 2)
    $label = New-Object System.Windows.Controls.TextBlock
    $label.Text = [string]$Check.Name
    $label.FontWeight = "SemiBold"
    $label.TextTrimming = "CharacterEllipsis"
    $label.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, "BrushInk")
    $result = New-Object System.Windows.Controls.TextBlock
    $result.Text = "Waiting" + (Get-WinToolHomeEllipsis)
    $result.TextTrimming = "CharacterEllipsis"
    $result.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, "BrushMuted")
    $null = $text.Children.Add($label)
    $null = $text.Children.Add($result)
    $null = $content.Children.Add($text)

    $button = New-Object System.Windows.Controls.Button
    $button.Style = $script:WinToolWindow.FindResource("HomeRowButton")
    $button.Content = "Fix"
    $button.VerticalAlignment = "Center"
    $button.IsEnabled = $false
    [System.Windows.Controls.Grid]::SetColumn($button, 4)
    $null = $grid.Children.Add($button)

    $row = [pscustomobject]@{
        Id = [string]$Check.Id
        Name = [string]$Check.Name
        Border = $border
        Content = $content
        Disc = $disc
        Glyph = $glyph
        Spinner = $spinner
        Label = $label
        Result = $result
        Button = $button
        Status = "busy"
    }
    Register-WinToolUiEvent -Control $button -EventName "Click" -Name ("Home: " + [string]$Check.Name) -Data ([string]$Check.Id) -Action {
        param($source, $eventData, $checkId)
        $null = $source, $eventData
        Invoke-WinToolHomeAction -Id $checkId
    }
    return $row
}

function Set-WinToolHomeRow {
    # Shows one state in a row's fixed slots. Action "none" hides the button
    # but keeps its slot; "off" shows it greyed out.
    param(
        [Parameter(Mandatory = $true)]$Row,
        [Parameter(Mandatory = $true)][ValidateSet("busy", "ok", "warn", "bad", "unknown")][string]$Status,
        [Parameter(Mandatory = $true)][string]$Text,
        [ValidateSet("fix", "review", "none", "off")][string]$Action = "none",
        [switch]$Fade
    )
    $Row.Status = $Status
    $Row.Result.Text = $Text
    $rotate = $Row.Spinner.RenderTransform
    if ($Status -eq "busy") {
        $Row.Border.ToolTip = $null
        $Row.Disc.Fill = [System.Windows.Media.Brushes]::Transparent
        $Row.Glyph.Visibility = "Hidden"
        $Row.Spinner.Visibility = "Visible"
        if (-not (Test-WinToolHomeReduceMotion)) {
            $spin = New-Object System.Windows.Media.Animation.DoubleAnimation(0, 360, [System.Windows.Duration]::new([TimeSpan]::FromSeconds(1)))
            $spin.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
            $rotate.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty, $spin)
        }
    }
    else {
        $rotate.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty, $null)
        $Row.Spinner.Visibility = "Hidden"
        $Row.Glyph.Visibility = "Visible"
        $look = switch ($Status) {
            "ok" { @{ Soft = "BrushOkSoft"; Ink = "BrushOk"; Data = "M 7,11.5 L 10,14.5 L 15.5,8" } }
            "warn" { @{ Soft = "BrushWarnSoft"; Ink = "BrushWarn"; Data = "M 11,6.5 L 11,12 M 11,15.5 L 11,15.6" } }
            "bad" { @{ Soft = "BrushBadSoft"; Ink = "BrushBad"; Data = "M 8,8 L 14,14 M 14,8 L 8,14" } }
            default { @{ Soft = "BrushNavHover"; Ink = "BrushMuted"; Data = "M 11,10 L 11,15.5 M 11,6.5 L 11,6.6" } }
        }
        $Row.Disc.SetResourceReference([System.Windows.Shapes.Shape]::FillProperty, $look.Soft)
        $Row.Glyph.SetResourceReference([System.Windows.Shapes.Shape]::StrokeProperty, $look.Ink)
        $Row.Glyph.Data = [System.Windows.Media.Geometry]::Parse($look.Data)
    }
    $button = $Row.Button
    switch ($Action) {
        "fix" {
            $button.Content = "Fix"
            $button.SetResourceReference([System.Windows.Controls.Control]::BackgroundProperty, "BrushAccentSoft")
            $button.SetResourceReference([System.Windows.Controls.Control]::BorderBrushProperty, "BrushAccent")
            $button.Visibility = "Visible"
            $button.IsEnabled = $true
        }
        "review" {
            $button.Content = "Review"
            $button.Background = [System.Windows.Media.Brushes]::Transparent
            $button.SetResourceReference([System.Windows.Controls.Control]::BorderBrushProperty, "BrushLine")
            $button.Visibility = "Visible"
            $button.IsEnabled = $true
        }
        "off" {
            $button.Content = "Fix"
            $button.Background = [System.Windows.Media.Brushes]::Transparent
            $button.SetResourceReference([System.Windows.Controls.Control]::BorderBrushProperty, "BrushLine")
            $button.Visibility = "Visible"
            $button.IsEnabled = $false
        }
        default {
            $button.Visibility = "Hidden"
            $button.IsEnabled = $false
        }
    }
    if ($Fade -and -not (Test-WinToolHomeReduceMotion)) {
        $animation = New-Object System.Windows.Media.Animation.DoubleAnimation(0, 1, [System.Windows.Duration]::new([TimeSpan]::FromMilliseconds(320)))
        $Row.Content.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $animation)
    }
}

function New-WinToolHomeMini {
    param(
        [Parameter(Mandatory = $true)][string]$Key,
        [Parameter(Mandatory = $true)][string]$Title,
        [int]$Column,
        [string]$From,
        [string]$To,
        [string]$Line
    )
    $card = New-Object System.Windows.Controls.Border
    $card.CornerRadius = [System.Windows.CornerRadius]::new(16)
    $card.BorderThickness = [System.Windows.Thickness]::new(1)
    $card.Padding = [System.Windows.Thickness]::new(18)
    $card.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, "BrushCard")
    $card.SetResourceReference([System.Windows.Controls.Border]::BorderBrushProperty, "BrushLine")
    [System.Windows.Controls.Grid]::SetColumn($card, $Column)
    $grid = New-Object System.Windows.Controls.Grid
    $grid.RowDefinitions.Add((New-Object System.Windows.Controls.RowDefinition -Property @{ Height = [System.Windows.GridLength]::Auto }))
    $grid.RowDefinitions.Add((New-Object System.Windows.Controls.RowDefinition -Property @{ Height = [System.Windows.GridLength]::new(58) }))
    $card.Child = $grid

    $top = New-Object System.Windows.Controls.Grid
    $top.Height = 64
    foreach ($width in @(56, 14, -1)) {
        $colDef = New-Object System.Windows.Controls.ColumnDefinition
        if ($width -lt 0) { $colDef.Width = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star) }
        else { $colDef.Width = [System.Windows.GridLength]::new($width) }
        $top.ColumnDefinitions.Add($colDef)
    }
    $null = $grid.Children.Add($top)

    $ring = New-Object System.Windows.Controls.Canvas
    $ring.Width = 56
    $ring.Height = 56
    $ring.VerticalAlignment = "Center"
    $track = New-Object System.Windows.Shapes.Ellipse
    $track.Width = 49
    $track.Height = 49
    $track.StrokeThickness = 5
    $track.SetResourceReference([System.Windows.Shapes.Shape]::StrokeProperty, "BrushProgressTrack")
    [System.Windows.Controls.Canvas]::SetLeft($track, 3.5)
    [System.Windows.Controls.Canvas]::SetTop($track, 3.5)
    $arc = New-Object System.Windows.Shapes.Path
    $arc.StrokeThickness = 5
    $arc.StrokeStartLineCap = "Round"
    $arc.StrokeEndLineCap = "Round"
    $arc.Stroke = New-WinToolHomeBrush -From $From -To $To
    $arc.Visibility = "Hidden"
    $null = $ring.Children.Add($track)
    $null = $ring.Children.Add($arc)
    $null = $top.Children.Add($ring)

    $info = New-Object System.Windows.Controls.Grid
    $info.VerticalAlignment = "Center"
    [System.Windows.Controls.Grid]::SetColumn($info, 2)
    foreach ($height in @(24, 20, 20)) {
        $info.RowDefinitions.Add((New-Object System.Windows.Controls.RowDefinition -Property @{ Height = [System.Windows.GridLength]::new($height) }))
    }
    $null = $top.Children.Add($info)
    $titleRow = New-Object System.Windows.Controls.Grid
    $titleRow.ColumnDefinitions.Add((New-Object System.Windows.Controls.ColumnDefinition -Property @{ Width = [System.Windows.GridLength]::new(1, [System.Windows.GridUnitType]::Star) }))
    $titleRow.ColumnDefinitions.Add((New-Object System.Windows.Controls.ColumnDefinition -Property @{ Width = [System.Windows.GridLength]::Auto }))
    $null = $info.Children.Add($titleRow)
    $titleText = New-Object System.Windows.Controls.TextBlock
    $titleText.Text = $Title
    $titleText.FontWeight = "Bold"
    $titleText.VerticalAlignment = "Center"
    $titleText.TextTrimming = "CharacterEllipsis"
    $titleText.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, "BrushInk")
    $null = $titleRow.Children.Add($titleText)
    $tag = New-Object System.Windows.Controls.Border
    $tag.Height = 22
    $tag.Width = 96
    $tag.CornerRadius = [System.Windows.CornerRadius]::new(11)
    $tag.Padding = [System.Windows.Thickness]::new(6, 0, 6, 0)
    $tag.Margin = [System.Windows.Thickness]::new(8, 0, 0, 0)
    $tag.VerticalAlignment = "Center"
    [System.Windows.Controls.Grid]::SetColumn($tag, 1)
    $tagText = New-Object System.Windows.Controls.TextBlock
    $tagText.FontWeight = "SemiBold"
    $tagText.HorizontalAlignment = "Center"
    $tagText.VerticalAlignment = "Center"
    $tagText.TextTrimming = "CharacterEllipsis"
    $tagText.Text = "Reading"
    $tag.Child = $tagText
    $null = $titleRow.Children.Add($tag)
    $value = New-Object System.Windows.Controls.TextBlock
    $value.FontWeight = "SemiBold"
    $value.TextTrimming = "CharacterEllipsis"
    $value.Text = "Reading" + (Get-WinToolHomeEllipsis)
    $value.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, "BrushInk")
    [System.Windows.Controls.Grid]::SetRow($value, 1)
    $null = $info.Children.Add($value)
    $detail = New-Object System.Windows.Controls.TextBlock
    $detail.TextTrimming = "CharacterEllipsis"
    $detail.Text = " "
    $detail.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, "BrushMuted")
    [System.Windows.Controls.Grid]::SetRow($detail, 2)
    $null = $info.Children.Add($detail)

    $spark = New-Object System.Windows.Controls.Grid
    $spark.Height = 46
    $spark.Margin = [System.Windows.Thickness]::new(0, 12, 0, 0)
    $spark.VerticalAlignment = "Stretch"
    $spark.ClipToBounds = $true
    [System.Windows.Controls.Grid]::SetRow($spark, 1)
    $fill = New-Object System.Windows.Shapes.Path
    $fill.Fill = New-WinToolHomeBrush -From $Line -To $Line -Vertical -Alpha 0.28
    $stroke = New-Object System.Windows.Shapes.Path
    $stroke.StrokeThickness = 1.6
    $stroke.StrokeLineJoin = "Round"
    $stroke.Stroke = New-Object System.Windows.Media.SolidColorBrush([System.Windows.Media.ColorConverter]::ConvertFromString($Line))
    $null = $spark.Children.Add($fill)
    $null = $spark.Children.Add($stroke)
    $null = $grid.Children.Add($spark)

    $mini = [pscustomobject]@{
        Key = $Key
        Card = $card
        Arc = $arc
        Tag = $tag
        TagText = $tagText
        Value = $value
        Detail = $detail
        Spark = $spark
        SparkFill = $fill
        SparkLine = $stroke
        Points = (New-Object System.Collections.Generic.List[double])
    }
    Register-WinToolUiEvent -Control $spark -EventName "SizeChanged" -Name ("Home card " + $Key) -Data $mini -Action {
        param($source, $eventData, $card)
        $null = $source, $eventData
        Update-WinToolHomeSpark -Mini $card
    }
    return $mini
}

function Set-WinToolHomeMiniTag {
    param($Mini, [string]$Text, [ValidateSet("ok", "warn", "bad", "neutral")][string]$Tone)
    $Mini.TagText.Text = $Text
    $look = switch ($Tone) {
        "ok" { @("BrushOkSoft", "BrushOk") }
        "warn" { @("BrushWarnSoft", "BrushWarn") }
        "bad" { @("BrushBadSoft", "BrushBad") }
        default { @("BrushNavHover", "BrushMuted") }
    }
    $Mini.Tag.SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, $look[0])
    $Mini.TagText.SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, $look[1])
}

function Set-WinToolHomeMiniRing {
    param($Mini, [double]$Fraction)
    if ($Fraction -le 0) {
        $Mini.Arc.Visibility = "Hidden"
        return
    }
    $angle = [Math]::Min(1.0, $Fraction) * 360
    $shape = Get-WinToolHomeArcData -CenterX 28 -CenterY 28 -Radius 22 -Angle $angle
    $Mini.Arc.Data = [System.Windows.Media.Geometry]::Parse($shape.Data)
    $Mini.Arc.Visibility = "Visible"
}

function Add-WinToolHomeSparkPoint {
    param($Mini, [double]$Value)
    if ($Value -lt 0) { return }
    $Mini.Points.Add([Math]::Max(0, [Math]::Min(100, $Value)))
    while ($Mini.Points.Count -gt 24) { $Mini.Points.RemoveAt(0) }
    Update-WinToolHomeSpark -Mini $Mini
}

function Update-WinToolHomeSpark {
    # The newest sample sits on the right; 24 samples fill the width.
    param($Mini)
    $width = [double]$Mini.Spark.ActualWidth
    $height = [double]$Mini.Spark.ActualHeight
    $count = $Mini.Points.Count
    if ($width -le 0 -or $height -le 0 -or $count -lt 1) {
        $Mini.SparkLine.Data = $null
        $Mini.SparkFill.Data = $null
        return
    }
    $culture = [System.Globalization.CultureInfo]::InvariantCulture
    $step = $width / 23
    $points = New-Object System.Collections.Generic.List[string]
    $firstX = 0
    if ($count -eq 1) {
        $firstX = [Math]::Max(0, $width - $step)
        $y = ($height - 2) - ($Mini.Points[0] / 100) * ($height - 8)
        $points.Add([string]::Format($culture, "{0:0.##},{1:0.##}", $firstX, $y))
        $points.Add([string]::Format($culture, "{0:0.##},{1:0.##}", $width, $y))
    }
    else {
        for ($i = 0; $i -lt $count; $i++) {
            $x = $width - ($count - 1 - $i) * $step
            if ($i -eq 0) { $firstX = $x }
            $y = ($height - 2) - ($Mini.Points[$i] / 100) * ($height - 8)
            $points.Add([string]::Format($culture, "{0:0.##},{1:0.##}", $x, $y))
        }
    }
    $line = "M " + ($points -join " L ")
    $Mini.SparkLine.Data = [System.Windows.Media.Geometry]::Parse($line)
    $Mini.SparkFill.Data = [System.Windows.Media.Geometry]::Parse(($line + [string]::Format($culture, " L {0:0.##},{2:0.##} L {1:0.##},{2:0.##} Z", $width, $firstX, $height)))
}

function Format-WinToolHomeSize {
    # Installed sizes read best rounded: 32 GB of memory, 512 GB disk.
    param([double]$Bytes, [switch]$Decimal)
    $culture = [System.Globalization.CultureInfo]::InvariantCulture
    if ($Decimal) {
        $gb = $Bytes / 1e9
        if ($gb -ge 1000) { return [string]::Format($culture, "{0:0.#} TB", $gb / 1000) }
        return [string]::Format($culture, "{0:0} GB", $gb)
    }
    $gib = $Bytes / 1GB
    if ([Math]::Abs($gib - [Math]::Round($gib)) -lt 0.06) { return [string]::Format($culture, "{0:0} GB", $gib) }
    return [string]::Format($culture, "{0:0.0} GB", $gib)
}

function Update-WinToolHomeCard {
    # Fills the three cards from the static PC info and the latest sample.
    $hs = $script:WinToolState.Home
    $dot = " " + [string][char]0x00B7 + " "
    $info = $hs.Info
    $sample = $hs.LastSample
    $memory = $hs.Minis["memory"]
    $disk = $hs.Minis["disk"]
    $pc = $hs.Minis["pc"]
    if ($null -ne $sample -and [double]$sample.MemoryTotal -gt 0) {
        $fraction = [double]$sample.MemoryUsed / [double]$sample.MemoryTotal
        Set-WinToolHomeMiniRing -Mini $memory -Fraction $fraction
        Set-WinToolHomeMiniTag -Mini $memory -Text ("{0:0}% used" -f ($fraction * 100)) -Tone "neutral"
        $memory.Value.Text = (Format-WinToolByteSize -Bytes ([double]$sample.MemoryUsed)) + " in use"
        $total = [double]$sample.MemoryTotal
        $kind = ""
        if ($null -ne $info) {
            if ([double]$info.MemoryTotal -gt 0) { $total = [double]$info.MemoryTotal }
            $kind = Get-WinToolMemoryTypeName -Code ([int]$info.MemoryType)
        }
        $text = (Format-WinToolHomeSize -Bytes $total) + " total"
        if (-not [string]::IsNullOrWhiteSpace($kind)) { $text += $dot + $kind }
        $memory.Detail.Text = $text
        $memory.Card.ToolTip = ("Memory: {0} ({1})" -f $memory.Value.Text, $memory.Detail.Text)
    }
    if ($null -ne $sample -and [double]$sample.DiskTotal -gt 0) {
        $free = [double]$sample.DiskFree / [double]$sample.DiskTotal
        Set-WinToolHomeMiniRing -Mini $disk -Fraction (1 - $free)
        Set-WinToolHomeMiniTag -Mini $disk -Text ("{0:0}% free" -f ($free * 100)) -Tone (Get-WinToolHomeDiskTone -FreePercent ($free * 100))
        $disk.Value.Text = (Format-WinToolByteSize -Bytes ([double]$sample.DiskFree)) + " free"
        $size = [double]$sample.DiskTotal
        $media = ""
        if ($null -ne $info) {
            if ([double]$info.DiskSize -gt 0) { $size = [double]$info.DiskSize }
            if (@("SSD", "HDD") -contains [string]$info.DiskMedia) { $media = " " + [string]$info.DiskMedia }
        }
        $letter = ([string]$env:SystemDrive)
        if ([string]::IsNullOrWhiteSpace($letter)) { $letter = "C:" }
        $disk.Detail.Text = (Format-WinToolHomeSize -Bytes $size -Decimal) + $media + $dot + "Drive " + $letter
        $disk.Card.ToolTip = ("Windows disk: {0} ({1})" -f $disk.Value.Text, $disk.Detail.Text)
    }
    if ($null -ne $info) {
        Set-WinToolHomeMiniRing -Mini $pc -Fraction 1
        if (-not [string]::IsNullOrWhiteSpace([string]$info.Os)) { $pc.Value.Text = [string]$info.Os }
        $parts = @()
        if (-not [string]::IsNullOrWhiteSpace([string]$info.Version)) { $parts += [string]$info.Version }
        $cpu = Format-WinToolCpuName -Name ([string]$info.Cpu)
        if (-not [string]::IsNullOrWhiteSpace($cpu)) { $parts += $cpu }
        if ($parts.Count -gt 0) { $pc.Detail.Text = ($parts -join $dot) }
    }
    $driver = $hs.Results["drivers"]
    $diskHealth = $hs.Results["disk"]
    if ($hs.Phase -eq "analyzing" -or $null -eq $driver -or $null -eq $diskHealth) {
        Set-WinToolHomeMiniTag -Mini $pc -Text "Checking" -Tone "neutral"
        $pc.Card.ToolTip = "Checking device drivers and drive health."
    }
    elseif ($driver.Status -eq "bad" -and $diskHealth.Status -eq "bad") {
        Set-WinToolHomeMiniTag -Mini $pc -Text "2 issues" -Tone "warn"
        $pc.Card.ToolTip = ("Drivers: {0}`nDisk health: {1}" -f $driver.Text, $diskHealth.Text)
    }
    elseif ($driver.Status -eq "bad") {
        Set-WinToolHomeMiniTag -Mini $pc -Text "Driver issue" -Tone "warn"
        $tip = "Drivers: " + $driver.Text
        if (@($driver.Detail).Count -gt 0) { $tip += "`n" + ((@($driver.Detail | Select-Object -First 5)) -join "`n") }
        $pc.Card.ToolTip = $tip
    }
    elseif ($diskHealth.Status -eq "bad") {
        Set-WinToolHomeMiniTag -Mini $pc -Text "Disk issue" -Tone "bad"
        $tip = "Disk health: " + $diskHealth.Text
        if (@($diskHealth.Detail).Count -gt 0) { $tip += "`n" + ((@($diskHealth.Detail | Select-Object -First 5)) -join "`n") }
        $pc.Card.ToolTip = $tip
    }
    else {
        Set-WinToolHomeMiniTag -Mini $pc -Text "Healthy" -Tone "ok"
        $pc.Card.ToolTip = "Device drivers and drive health report no problems."
    }
}

function Add-WinToolHomeSample {
    param([Parameter(Mandatory = $true)]$Sample)
    $hs = $script:WinToolState.Home
    $hs.LastSample = $Sample
    if ([double]$Sample.MemoryTotal -gt 0) {
        Add-WinToolHomeSparkPoint -Mini $hs.Minis["memory"] -Value (100 * [double]$Sample.MemoryUsed / [double]$Sample.MemoryTotal)
    }
    Add-WinToolHomeSparkPoint -Mini $hs.Minis["disk"] -Value ([double]$Sample.DiskBusy)
    Add-WinToolHomeSparkPoint -Mini $hs.Minis["pc"] -Value ([double]$Sample.Cpu)
    Update-WinToolHomeCard
}

function Initialize-WinToolHomeView {
    $script:WinToolState.Home = @{
        Phase = "idle"
        Results = @{}
        Rows = @{}
        Minis = @{}
        Pending = @{}
        Started = $null
        Finished = $null
        Seconds = 0
        Score = $null
        Arc = 0.0
        ArcTarget = 0.0
        AnimStart = [DateTime]::Now
        Info = $null
        LastSample = $null
        WaitTweaks = $false
        Previous = $null
    }
    $hs = $script:WinToolState.Home
    $checkHost = Get-WinToolUi -Name "HomeChecks"
    $checks = @(Get-WinToolHomeCheckList)
    for ($i = 0; $i -lt $checks.Count; $i++) {
        $row = New-WinToolHomeRow -Check $checks[$i] -Last ($i -eq $checks.Count - 1)
        $hs.Rows[$row.Id] = $row
        $null = $checkHost.Children.Add($row.Border)
        Set-WinToolHomeRow -Row $row -Status "busy" -Text ("Waiting" + (Get-WinToolHomeEllipsis)) -Action "off"
    }
    $minis = Get-WinToolUi -Name "HomeMinis"
    $hs.Minis["memory"] = New-WinToolHomeMini -Key "memory" -Title "Memory" -Column 0 -From "#4C8DFF" -To "#8B5CF6" -Line "#8B7CF6"
    $hs.Minis["disk"] = New-WinToolHomeMini -Key "disk" -Title "Windows disk" -Column 2 -From "#F5B942" -To "#F07178" -Line "#F5A742"
    $hs.Minis["pc"] = New-WinToolHomeMini -Key "pc" -Title "This PC" -Column 4 -From "#3DD68C" -To "#4C8DFF" -Line "#4C8DFF"
    foreach ($key in @("memory", "disk", "pc")) { $null = $minis.Children.Add($hs.Minis[$key].Card) }
    Update-WinToolHomeCard

    $history = @(Read-WinToolHomeHistory)
    if ($history.Count -gt 0) { $hs.Previous = $history[-1] }
    (Get-WinToolUi -Name "HomeMetaText").Text = Format-WinToolHomeMeta -Last $hs.Previous
    Set-WinToolHomeArc -Angle 0
    Sync-WinToolHomeHeader

    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "HomeAgain") -EventName "Click" -Name "Analyze again" -Action {
        Start-WinToolHomeAnalysis
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "HomeFixAll") -EventName "Click" -Name "Fix all" -Action {
        Invoke-WinToolHomeFixAll
    }
    Register-WinToolUiEvent -Control (Get-WinToolUi -Name "HomeHistoryLink") -EventName "Click" -Name "View history" -Action {
        Show-WinToolHomeHistory
    }
    Register-WinToolUiEvent -Control $script:WinToolWindow -EventName "Loaded" -Name "Start the Home analysis" -Action {
        Start-WinToolHomeTimer
        Start-WinToolHomeSampler
        Start-WinToolHomeAnalysis
    }
}

function Sync-WinToolHomeHeader {
    $hs = $script:WinToolState.Home
    $done = @($hs.Results.Values).Count
    $total = @(Get-WinToolHomeCheckList).Count
    $busyRing = Get-WinToolUi -Name "HomeRingBusy"
    $doneRing = Get-WinToolUi -Name "HomeRingDone"
    $fixAll = Get-WinToolUi -Name "HomeFixAll"
    $again = Get-WinToolUi -Name "HomeAgain"
    $headline = Get-WinToolUi -Name "HomeHeadline"
    $lead = Get-WinToolUi -Name "HomeLead"
    $count = Get-WinToolUi -Name "HomeCheckCount"
    (Get-WinToolUi -Name "HomeRingProgress").Text = "{0} of {1} checks" -f $done, $total
    switch ($hs.Phase) {
        "done" {
            $results = @($hs.Results.Values)
            $score = $hs.Score
            if ($null -eq $score) { $score = Get-WinToolHomeScore -Result $results }
            $verdict = Get-WinToolHomeVerdict -Score $score
            $fixable = @($results | Where-Object { $_.Fixable }).Count
            $busyRing.Visibility = "Collapsed"
            $doneRing.Visibility = "Visible"
            (Get-WinToolUi -Name "HomeScore").Text = [string]$score
            (Get-WinToolUi -Name "HomeVerdictText").Text = $verdict.Text
            $tone = @{ ok = @("BrushOkSoft", "BrushOk"); warn = @("BrushWarnSoft", "BrushWarn"); bad = @("BrushBadSoft", "BrushBad") }[$verdict.Tone]
            (Get-WinToolUi -Name "HomeVerdict").SetResourceReference([System.Windows.Controls.Border]::BackgroundProperty, $tone[0])
            (Get-WinToolUi -Name "HomeVerdictText").SetResourceReference([System.Windows.Controls.TextBlock]::ForegroundProperty, $tone[1])
            $headline.Text = "Analysis complete"
            $lead.Text = Get-WinToolHomeLead -Result $results
            $count.Text = "{0} of {1} can be fixed" -f $fixable, $total
            $fixAll.IsEnabled = ($fixable -gt 0)
            $again.IsEnabled = $true
            $hs.ArcTarget = 360.0 * $score / 100
        }
        "fixing" {
            $busyRing.Visibility = "Collapsed"
            $doneRing.Visibility = "Visible"
            $headline.Text = "Fixing" + (Get-WinToolHomeEllipsis)
            $lead.Text = "Only safe changes are made. You can keep using your PC."
            $count.Text = "{0} of {1} complete" -f $done, $total
            $fixAll.IsEnabled = $false
            $again.IsEnabled = $false
        }
        default {
            $busyRing.Visibility = "Visible"
            $doneRing.Visibility = "Collapsed"
            $headline.Text = "Analyzing your PC" + (Get-WinToolHomeEllipsis)
            $lead.Text = "Takes less than a minute. Nothing is changed during the analysis."
            $count.Text = "{0} of {1} complete" -f $done, $total
            $fixAll.IsEnabled = $false
            $again.IsEnabled = ($hs.Phase -eq "idle")
        }
    }
    Sync-WinToolHomeRunText
}

function Sync-WinToolHomeRunText {
    $hs = $script:WinToolState.Home
    $text = Get-WinToolUi -Name "HomeRunText"
    if ($null -eq $hs.Started) {
        $text.Text = " "
        return
    }
    switch ($hs.Phase) {
        "analyzing" { $text.Text = "Running for {0}s" -f [int]([DateTime]::Now - [datetime]$hs.Started).TotalSeconds }
        "fixing" { $text.Text = "Fixing" + (Get-WinToolHomeEllipsis) }
        default { $text.Text = "Finished in {0}s" -f [int]$hs.Seconds }
    }
}

function Start-WinToolHomeTimer {
    if ($null -ne $script:WinToolState.HomeTimer) { return }
    $timer = New-Object System.Windows.Threading.DispatcherTimer
    $timer.Interval = [TimeSpan]::FromMilliseconds(250)
    Register-WinToolUiEvent -Control $timer -EventName "Tick" -Name "Home refresh" -Action { Update-WinToolHomePoll }
    $timer.Start()
    $script:WinToolState.HomeTimer = $timer
    $animation = New-Object System.Windows.Threading.DispatcherTimer
    $animation.Interval = [TimeSpan]::FromMilliseconds(16)
    Register-WinToolUiEvent -Control $animation -EventName "Tick" -Name "Home ring" -Action { Update-WinToolHomeAnimation }
    $script:WinToolState.HomeAnimTimer = $animation
}

function Start-WinToolHomeAnimation {
    if ((Test-WinToolHomeReduceMotion) -or $null -eq $script:WinToolState.HomeAnimTimer) {
        $hs = $script:WinToolState.Home
        if ($hs.Phase -eq "analyzing") {
            $done = @($hs.Results.Values).Count
            Set-WinToolHomeArc -Angle ([Math]::Max(24, 360.0 * $done / 5 * 0.9))
        }
        else {
            Set-WinToolHomeArc -Angle $hs.ArcTarget
        }
        return
    }
    $script:WinToolState.HomeAnimTimer.Start()
}

function Update-WinToolHomeAnimation {
    # While analyzing the arc grows and shrinks; afterwards it eases to the score.
    $hs = $script:WinToolState.Home
    if ($hs.Phase -eq "analyzing") {
        $t = ([DateTime]::Now - [datetime]$hs.AnimStart).TotalSeconds
        $wave = 0.5 - 0.5 * [Math]::Cos(2 * [Math]::PI * $t / 2.4)
        Set-WinToolHomeArc -Angle (50 + 260 * $wave)
        return
    }
    $diff = [double]$hs.ArcTarget - [double]$hs.Arc
    if ([Math]::Abs($diff) -lt 0.4) {
        Set-WinToolHomeArc -Angle $hs.ArcTarget
        $script:WinToolState.HomeAnimTimer.Stop()
        return
    }
    Set-WinToolHomeArc -Angle ([double]$hs.Arc + $diff * 0.14)
}

function Start-WinToolHomeCheck {
    # Starts one check in its own runspace. Tests set WinToolHomeNoJobs and
    # feed the results through Complete-WinToolHomeCheck.
    param([Parameter(Mandatory = $true)][string]$Id)
    $hs = $script:WinToolState.Home
    $hs.Pending[$Id] = $true
    $hs.Results.Remove($Id)
    Set-WinToolHomeRow -Row $hs.Rows[$Id] -Status "busy" -Text ("Checking" + (Get-WinToolHomeEllipsis)) -Action "off"
    if ($script:WinToolHomeNoJobs) { return }
    $key = "HomeJob_" + $Id
    Stop-WinToolThread -Job $script:WinToolState[$key]
    try {
        $scriptText = Get-WinToolHomeCheckScript -Id $Id
        switch ($Id) {
            "junk" { $job = Start-WinToolHomeJob -ScriptText $scriptText -Argument @(, @(Get-WinToolHomeJunkLocation)) }
            "tweaks" {
                $recommended = @(Get-WinToolPresetTweak -Catalog (Get-WinToolTweakCatalog) -PresetId "recommended")
                $job = Start-WinToolHomeJob -ScriptText $scriptText -Argument @(, $recommended) -WithWinTool
            }
            default { $job = Start-WinToolHomeJob -ScriptText $scriptText }
        }
        $script:WinToolState[$key] = $job
    }
    catch {
        Complete-WinToolHomeCheck -Id $Id -ErrorMessage $_.Exception.Message
    }
}

function Sync-WinToolHomeCurrentScore {
    $hs = $script:WinToolState.Home
    if ($null -eq $hs -or $hs.Phase -ne "done") { return }
    $results = @($hs.Results.Values)
    if ($results.Count -lt @(Get-WinToolHomeCheckList).Count) { return }
    $score = Get-WinToolHomeScore -Result $results
    $hs.Score = $score
    if ($null -ne $hs.Finished) {
        $hs.Previous = [pscustomobject]@{ Time = $hs.Finished; Score = $score; Seconds = $hs.Seconds }
        (Get-WinToolUi -Name "HomeMetaText").Text = Format-WinToolHomeMeta -Last $hs.Previous
        if (-not $script:WinToolHomeNoJobs) {
            Set-WinToolHomeLatestHistory -Score $score
        }
    }
    Sync-WinToolHomeHeader
    Update-WinToolHomeCard
    Start-WinToolHomeAnimation
}

function Sync-WinToolHomeTweakRow {
    # Updates the Home tweaks check from the Tweaks page rows when the analysis
    # has already finished, so toggling switches keeps Home's score in sync.
    $hs = $script:WinToolState.Home
    if ($null -eq $hs -or $hs.Phase -ne "done" -or $hs.WaitTweaks) { return }
    if (-not $script:WinToolState.TweakStateRead) { return }
    $byId = @{}
    foreach ($row in @($script:WinToolState.TweakRows)) {
        $byId[[string]$row.Id] = $row
    }
    $data = foreach ($tweak in @(Get-WinToolPresetTweak -Catalog (Get-WinToolTweakCatalog) -PresetId "recommended")) {
        $id = [string]$tweak.id
        $state = "unknown"
        if ($byId.ContainsKey($id)) {
            $tweakRow = $byId[$id]
            if ($tweakRow.Checkbox.IsChecked -eq $true) { $state = "on" }
            elseif ($tweakRow.State -eq "off" -or $tweakRow.Checkbox.IsChecked -eq $false) { $state = "off" }
        }
        [pscustomobject]@{ Id = $id; Name = [string]$tweak.name; State = $state }
    }
    Complete-WinToolHomeCheck -Id "tweaks" -Data @($data)
}

function Complete-WinToolHomeCheck {
    param(
        [Parameter(Mandatory = $true)][string]$Id,
        $Data,
        [string]$ErrorMessage
    )
    $hs = $script:WinToolState.Home
    $result = ConvertTo-WinToolHomeResult -Id $Id -Data $Data -ErrorMessage $ErrorMessage
    $hs.Results[$Id] = $result
    $hs.Pending.Remove($Id)
    $action = [string]$result.Action
    $row = $hs.Rows[$Id]
    Set-WinToolHomeRow -Row $row -Status $result.Status -Text $result.Text -Action $action -Fade
    $tipLines = @($result.Name + ": " + $result.Text)
    if (@($result.Detail).Count -gt 0) {
        $tipLines += @($result.Detail | Select-Object -First 10 | ForEach-Object { "- " + $_ })
        if (@($result.Detail).Count -gt 10) { $tipLines += "- ..." }
    }
    $row.Border.ToolTip = ($tipLines -join "`n")
    if ($result.Status -eq "unknown" -and @($result.Detail).Count -gt 0) {
        Write-WinToolLog -Message ("Home: {0} could not be checked. {1}" -f $result.Name, (@($result.Detail) -join " ")) -Level "warn" -Diagnostic
    }
    if ($hs.Phase -eq "analyzing") {
        Sync-WinToolHomeHeader
        if ($hs.Pending.Count -eq 0) { Complete-WinToolHomeAnalysis }
        elseif (Test-WinToolHomeReduceMotion) { Start-WinToolHomeAnimation }
        return
    }
    if ($hs.Phase -eq "fixing") {
        Test-WinToolHomeFixDone
        return
    }
    Sync-WinToolHomeCurrentScore
}

function Start-WinToolHomeAnalysis {
    $hs = $script:WinToolState.Home
    if ($null -eq $hs -or $hs.Phase -eq "analyzing" -or $hs.Phase -eq "fixing") { return }
    $hs.Phase = "analyzing"
    $hs.Results = @{}
    $hs.Pending = @{}
    $hs.Score = $null
    $hs.Started = [DateTime]::Now
    $hs.AnimStart = [DateTime]::Now
    Sync-WinToolHomeHeader
    foreach ($check in @(Get-WinToolHomeCheckList)) {
        Start-WinToolHomeCheck -Id $check.Id
    }
    Update-WinToolHomeCard
    Start-WinToolHomeAnimation
    if ($hs.Phase -eq "analyzing" -and $hs.Pending.Count -eq 0) { Complete-WinToolHomeAnalysis }
}

function Complete-WinToolHomeAnalysis {
    $hs = $script:WinToolState.Home
    $hs.Phase = "done"
    $hs.Finished = [DateTime]::Now
    $hs.Seconds = [int][Math]::Max(1, ([datetime]$hs.Finished - [datetime]$hs.Started).TotalSeconds)
    $results = @($hs.Results.Values)
    $score = Get-WinToolHomeScore -Result $results
    $hs.Score = $score
    if (-not $script:WinToolHomeNoJobs) {
        Add-WinToolHomeHistory -Time $hs.Finished -Score $score -Seconds $hs.Seconds
    }
    $hs.Previous = [pscustomobject]@{ Time = $hs.Finished; Score = $score; Seconds = $hs.Seconds }
    (Get-WinToolUi -Name "HomeMetaText").Text = Format-WinToolHomeMeta -Last $hs.Previous
    Sync-WinToolHomeHeader
    Update-WinToolHomeCard
    Start-WinToolHomeAnimation
    Write-WinToolLog -Message ("Home: analysis finished in {0}s, score {1}." -f $hs.Seconds, $score) -Level "info" -Diagnostic
}

function Start-WinToolHomeInfo {
    if ($script:WinToolHomeNoJobs -or $null -ne $script:WinToolState.HomeInfoJob) { return }
    $script:WinToolState.HomeInfoJob = Start-WinToolHomeJob -ScriptText (Get-WinToolHomeCheckScript -Id "info")
}

function Start-WinToolHomeSampler {
    if ($script:WinToolHomeNoJobs) { return }
    Start-WinToolHomeInfo
    if ($null -ne $script:WinToolState.HomeSampler) { return }
    $script:WinToolState.HomeSampler = Start-WinToolHomeJob -ScriptText (Get-WinToolHomeCheckScript -Id "sampler")
}

function Update-WinToolHomePoll {
    $hs = $script:WinToolState.Home
    if ($null -eq $hs) { return }
    foreach ($check in @(Get-WinToolHomeCheckList)) {
        $key = "HomeJob_" + $check.Id
        $job = $script:WinToolState[$key]
        if ($null -eq $job -or -not $job.Sync.Done) { continue }
        $data = $job.Sync.Data
        $errorText = [string]$job.Sync.Error
        Stop-WinToolThread -Job $job
        $script:WinToolState[$key] = $null
        Complete-WinToolHomeCheck -Id $check.Id -Data $data -ErrorMessage $errorText
    }
    $clean = $script:WinToolState.HomeCleanJob
    if ($null -ne $clean -and $clean.Sync.Done) {
        $freed = [double]$clean.Sync.Data
        $errorText = [string]$clean.Sync.Error
        Stop-WinToolThread -Job $clean
        $script:WinToolState.HomeCleanJob = $null
        if ([string]::IsNullOrWhiteSpace($errorText)) {
            Write-WinToolLog -Message ("Junk files: freed {0}. Files in use were skipped." -f (Format-WinToolByteSize -Bytes $freed)) -Level "ok"
        }
        else {
            Write-WinToolLog -Message ("Junk files: cleaning stopped. {0}" -f $errorText) -Level "warn"
        }
        Start-WinToolHomeCheck -Id "junk"
    }
    if ($hs.WaitTweaks -and $null -eq $script:WinToolState.TweakQueue -and $null -eq $script:WinToolState.RestoreJob -and -not $script:WinToolState.Busy) {
        $hs.WaitTweaks = $false
        Start-WinToolHomeCheck -Id "tweaks"
    }
    $info = $script:WinToolState.HomeInfoJob
    if ($null -ne $info -and $info.Sync.Done -and $null -eq $hs.Info) {
        $hs.Info = $info.Sync.Data
        if ($null -eq $hs.Info) { $hs.Info = [pscustomobject]@{ Os = ""; Version = ""; Cpu = ""; MemoryTotal = 0; MemoryType = 0; DiskSize = 0; DiskMedia = "" } }
        Update-WinToolHomeCard
    }
    $sampler = $script:WinToolState.HomeSampler
    if ($null -ne $sampler) {
        $sampler.Sync.Paused = ((Get-WinToolUi -Name "ViewHome").Visibility -ne "Visible")
        $sample = $null
        while ($sampler.Sync.Queue.TryDequeue([ref]$sample)) {
            Add-WinToolHomeSample -Sample $sample
        }
    }
    if ($hs.Phase -eq "analyzing") { Sync-WinToolHomeRunText }
}

function Test-WinToolHomeFixDone {
    $hs = $script:WinToolState.Home
    if ($hs.Phase -ne "fixing") { return }
    if ($hs.Pending.Count -gt 0 -or $hs.WaitTweaks -or $null -ne $script:WinToolState.HomeCleanJob) { return }
    $hs.Phase = "done"
    Sync-WinToolHomeCurrentScore
}

function Start-WinToolHomeClean {
    $hs = $script:WinToolState.Home
    $hs.Phase = "fixing"
    $hs.Pending["junk"] = $true
    $hs.Results.Remove("junk")
    Set-WinToolHomeRow -Row $hs.Rows["junk"] -Status "busy" -Text ("Cleaning" + (Get-WinToolHomeEllipsis)) -Action "off"
    Sync-WinToolHomeHeader
    Write-WinToolLog -Message "Junk files: cleaning temporary files, the Recycle Bin and caches." -Level "info"
    if ($script:WinToolHomeNoJobs) { return }
    $script:WinToolState.HomeCleanJob = Start-WinToolHomeJob -ScriptText (Get-WinToolHomeCheckScript -Id "clean") -Argument @(, @(Get-WinToolHomeJunkLocation))
}

function Start-WinToolHomeTweakFix {
    # Uses the Tweaks page's own apply path: same confirmation, same restore point.
    param([switch]$NoConfirm)
    $hs = $script:WinToolState.Home
    if (-not $script:WinToolState.TweakStateRead) { Update-WinToolTweakState }
    $ids = @(Get-WinToolPresetTweak -Catalog (Get-WinToolTweakCatalog) -PresetId "recommended" | ForEach-Object { [string]$_.id })
    $script:WinToolState.TweakRequestStarted = $false
    Request-WinToolTweakOn -Id $ids -Label "the Recommended preset" -NoConfirm:$NoConfirm
    if (-not $script:WinToolState.TweakRequestStarted) {
        $wanted = @{}
        foreach ($id in $ids) { $wanted[$id] = $true }
        $remaining = @($script:WinToolState.TweakRows | Where-Object { $wanted.ContainsKey([string]$_.Id) -and $_.Checkbox.IsChecked -ne $true })
        if ($remaining.Count -eq 0) {
            Sync-WinToolHomeTweakRow
        }
        return $false
    }
    $hs.Phase = "fixing"
    $hs.WaitTweaks = $true
    $hs.Pending["tweaks"] = $true
    $hs.Results.Remove("tweaks")
    Set-WinToolHomeRow -Row $hs.Rows["tweaks"] -Status "busy" -Text ("Applying" + (Get-WinToolHomeEllipsis)) -Action "off"
    Sync-WinToolHomeHeader
    return $true
}

function Get-WinToolHomeJunkPrompt {
    $result = $script:WinToolState.Home.Results["junk"]
    $lines = @($result.Detail | ForEach-Object { "- " + $_ })
    return ("Delete {0} of junk files?`n`n{1}`n`nTemporary files from the last day and files in use are kept." -f (Format-WinToolByteSize -Bytes ([double]$result.Amount)), ($lines -join "`n"))
}

function Invoke-WinToolHomeAction {
    param([Parameter(Mandatory = $true)][string]$Id)
    $hs = $script:WinToolState.Home
    $result = $hs.Results[$Id]
    if ($hs.Phase -ne "done" -or $null -eq $result) { return }
    if ($result.Action -eq "review") {
        Show-WinToolHomeReview -Result $result
        return
    }
    if ($result.Action -ne "fix") { return }
    if ($Id -eq "junk") {
        if (Request-WinToolConfirmation -Message (Get-WinToolHomeJunkPrompt) -Title "Junk files") {
            Start-WinToolHomeClean
        }
        return
    }
    if ($Id -eq "tweaks") {
        $null = Start-WinToolHomeTweakFix
    }
}

function Invoke-WinToolHomeFixAll {
    $hs = $script:WinToolState.Home
    if ($hs.Phase -ne "done") { return }
    $fixable = @($hs.Results.Values | Where-Object { $_.Fixable })
    if ($fixable.Count -eq 0) { return }
    $lines = New-Object System.Collections.Generic.List[string]
    $junk = $hs.Results["junk"]
    $tweaks = $hs.Results["tweaks"]
    if ($null -ne $junk -and $junk.Fixable) { $lines.Add(("- Delete {0} of junk files (recent and in-use files are kept)" -f (Format-WinToolByteSize -Bytes ([double]$junk.Amount)))) }
    if ($null -ne $tweaks -and $tweaks.Fixable) { $lines.Add(("- Turn on {0} Recommended tweak(s); WinTool creates a restore point first" -f [int]$tweaks.Amount)) }
    $ok = Request-WinToolConfirmation -Message ("Fix {0} item(s)?`n`n{1}`n`nNothing else is changed." -f $lines.Count, ($lines -join "`n")) -Title "Fix all"
    if (-not $ok) { return }
    if ($null -ne $tweaks -and $tweaks.Fixable) { $null = Start-WinToolHomeTweakFix -NoConfirm }
    if ($null -ne $junk -and $junk.Fixable) { Start-WinToolHomeClean }
}

function Show-WinToolHomeReview {
    param([Parameter(Mandatory = $true)]$Result)
    $lines = @($Result.Detail | Select-Object -First 15 | ForEach-Object { "- " + $_ })
    if (@($Result.Detail).Count -gt 15) { $lines += "- ..." }
    $list = $lines -join "`n"
    switch ($Result.Id) {
        "startup" {
            if (Request-WinToolConfirmation -Message ("{0}:`n`n{1}`n`nOpen Task Manager to turn programs off?" -f $Result.Text, $list) -Title "Startup programs") {
                try { Start-Process -FilePath "taskmgr.exe" -ArgumentList "/0 /startup" } catch { Write-WinToolLog -Message ("Could not open Task Manager. {0}" -f $_.Exception.Message) -Level "warn" }
            }
        }
        "drivers" {
            if (Request-WinToolConfirmation -Message ("{0}:`n`n{1}`n`nOpen Device Manager?" -f $Result.Text, $list) -Title "Drivers") {
                try { Start-Process -FilePath "devmgmt.msc" } catch { Write-WinToolLog -Message ("Could not open Device Manager. {0}" -f $_.Exception.Message) -Level "warn" }
            }
        }
        "disk" {
            if (Request-WinToolConfirmation -Message ("{0}:`n`n{1}`n`nBack up your files soon. Open Disks and volumes in Settings?" -f $Result.Text, $list) -Title "Disk health") {
                try { Start-Process -FilePath "ms-settings:disksandvolumes" } catch { Write-WinToolLog -Message ("Could not open Settings. {0}" -f $_.Exception.Message) -Level "warn" }
            }
        }
    }
}

function Show-WinToolHomeHistory {
    $items = @(Read-WinToolHomeHistory | Select-Object -Last 10)
    if ($items.Count -eq 0) {
        $null = [System.Windows.MessageBox]::Show("No analysis was saved yet.", "History")
        return
    }
    [array]::Reverse($items)
    $lines = @($items | ForEach-Object { "{0}    Score {1}    {2}s" -f (Format-WinToolHomeWhen -Time ([datetime]$_.Time)), [int]$_.Score, [int]$_.Seconds })
    $null = [System.Windows.MessageBox]::Show(($lines -join "`n"), "History")
}
# endregion

# region src/UI/Shell.ps1
